import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum Role {
  USER = 'user',
  MODEL = 'model',
  SYSTEM = 'system'
}

export interface GroundingChunk {
  web?: {
    uri: string;
    title: string;
  };
}

export interface Message {
  id: string;
  role: Role;
  content: string;
  timestamp: number;
  isLoading?: boolean;
  images?: string[]; // base64 strings
  groundingSources?: GroundingChunk[];
}

export interface ChatConfig {
  model: string;
  temperature: number;
  useSearch: boolean;
  useThinking: boolean;
  systemInstruction: string;
}

export const DEFAULT_CONFIG: ChatConfig = {
  model: 'gemini-3-flash-preview',
  temperature: 0.7,
  useSearch: false,
  useThinking: false,
  systemInstruction: "You are a helpful, knowledgeable, and creative AI assistant. Answer concisely and accurately."
};

export const AVAILABLE_MODELS = [
  { id: 'gemini-3-flash-preview', name: 'Gemini 3 Flash (Fast)', description: 'Best for general tasks and speed.' },
  { id: 'gemini-3-pro-preview', name: 'Gemini 3 Pro (Smart)', description: 'Best for reasoning, coding, and complex tasks.' },
];

import { GoogleGenAI, GenerateContentStreamResult, Part } from "@google/genai";
import { ChatConfig, Message, Role } from '../types';

export class GeminiService {
  private ai: GoogleGenAI;

  constructor() {
    // Ensure API Key is available
    if (!process.env.API_KEY) {
      console.error("API_KEY is missing from environment variables.");
    }
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }

  async *streamChat(
    history: Message[], 
    newMessage: string, 
    images: string[], 
    config: ChatConfig
  ): AsyncGenerator<string | { groundingChunks: any[] }, void, unknown> {

    // Transform internal history to API format
    // Filter out error messages or loading states if necessary
    const chatHistory = history
      .filter(msg => !msg.isLoading && msg.role !== Role.SYSTEM) // System instruction is passed in config
      .map(msg => ({
        role: msg.role === Role.USER ? 'user' : 'model',
        parts: msg.images && msg.images.length > 0 
          ? [
              ...msg.images.map(img => ({ inlineData: { mimeType: 'image/jpeg', data: img.split(',')[1] } })),
              { text: msg.content }
            ]
          : [{ text: msg.content }]
      }));

    // Construct the current message parts
    const currentParts: Part[] = [];
    if (images.length > 0) {
      images.forEach(img => {
        // Assume base64 string includes prefix "data:image/jpeg;base64,"
        const base64Data = img.split(',')[1];
        currentParts.push({
          inlineData: {
            mimeType: 'image/jpeg', // Defaulting to jpeg for simplicity in this demo
            data: base64Data
          }
        });
      });
    }
    currentParts.push({ text: newMessage });

    // Prepare Tools
    const tools: any[] = [];
    if (config.useSearch) {
      tools.push({ googleSearch: {} });
    }

    // Prepare Thinking Config
    const thinkingConfig = config.useThinking 
      ? { thinkingBudget: 2048 } // A moderate budget for demo purposes
      : undefined;

    // Use chats.create to maintain session context easily if we were persisting the object,
    // but here we are stateless between calls for simplicity, re-hydrating history.
    // However, for correct "chat" behavior with the SDK, we can just use generateContent with history context manually
    // OR use the chat helper. Let's use the chat helper for cleaner code.

    const chat = this.ai.chats.create({
      model: config.model,
      history: chatHistory,
      config: {
        systemInstruction: config.systemInstruction,
        temperature: config.useThinking ? undefined : config.temperature, // Thinking models dictate their own temp usually
        tools: tools.length > 0 ? tools : undefined,
        thinkingConfig: thinkingConfig,
      }
    });

    try {
      const result: GenerateContentStreamResult = await chat.sendMessageStream({
        message: { parts: currentParts }
      });

      for await (const chunk of result) {
        // Check for text content
        const text = chunk.text;
        if (text) {
          yield text;
        }

        // Check for grounding metadata
        const groundingChunks = chunk.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (groundingChunks) {
           yield { groundingChunks };
        }
      }
    } catch (error) {
      console.error("Gemini API Error:", error);
      throw error;
    }
  }
}

export const geminiService = new GeminiService();

import React from 'react';
import ReactMarkdown from 'react-markdown';
import { Message, Role } from '../types';
import { Bot, User, Globe, FileImage } from 'lucide-react';

interface ChatMessageProps {
  message: Message;
}

const ChatMessage: React.FC<ChatMessageProps> = ({ message }) => {
  const isUser = message.role === Role.USER;

  return (
    <div className={`flex w-full mb-6 ${isUser ? 'justify-end' : 'justify-start'}`}>
      <div className={`flex max-w-[85%] md:max-w-[75%] gap-4 ${isUser ? 'flex-row-reverse' : 'flex-row'}`}>

        {/* Avatar */}
        <div className={`flex-shrink-0 w-8 h-8 rounded-full flex items-center justify-center ${isUser ? 'bg-blue-600' : 'bg-emerald-600'}`}>
          {isUser ? <User size={16} className="text-white" /> : <Bot size={16} className="text-white" />}
        </div>

        {/* Content Bubble */}
        <div className={`flex flex-col ${isUser ? 'items-end' : 'items-start'}`}>

          <div className={`px-5 py-4 rounded-2xl ${
            isUser 
              ? 'bg-blue-600 text-white rounded-tr-none' 
              : 'bg-zinc-800 text-zinc-100 rounded-tl-none border border-zinc-700'
          }`}>

            {/* Images if any */}
            {message.images && message.images.length > 0 && (
              <div className="flex flex-wrap gap-2 mb-3">
                {message.images.map((img, idx) => (
                  <img 
                    key={idx} 
                    src={img} 
                    alt={`attachment-${idx}`} 
                    className="max-w-[200px] max-h-[200px] rounded-lg object-cover border border-zinc-600/50"
                  />
                ))}
              </div>
            )}

            {/* Loading Indicator */}
            {message.isLoading ? (
              <div className="flex space-x-2 h-6 items-center">
                <div className="w-2 h-2 bg-zinc-400 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></div>
                <div className="w-2 h-2 bg-zinc-400 rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></div>
                <div className="w-2 h-2 bg-zinc-400 rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></div>
              </div>
            ) : (
              <div className="markdown-content text-sm md:text-base leading-relaxed break-words">
                <ReactMarkdown>{message.content}</ReactMarkdown>
              </div>
            )}
          </div>

          {/* Grounding Sources */}
          {message.groundingSources && message.groundingSources.length > 0 && (
            <div className="mt-2 text-xs text-zinc-400 bg-zinc-900/50 p-2 rounded-lg border border-zinc-800 self-start">
              <div className="flex items-center gap-1 mb-1 font-semibold text-zinc-300">
                <Globe size={12} />
                <span>Sources</span>
              </div>
              <ul className="flex flex-col gap-1">
                {message.groundingSources.map((source, idx) => (
                  source.web && (
                    <li key={idx}>
                      <a 
                        href={source.web.uri} 
                        target="_blank" 
                        rel="noopener noreferrer"
                        className="hover:text-blue-400 transition-colors truncate block max-w-[300px]"
                      >
                        {source.web.title}
                      </a>
                    </li>
                  )
                ))}
              </ul>
            </div>
          )}

          <span className="text-xs text-zinc-500 mt-1 px-1">
            {new Date(message.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
          </span>
        </div>
      </div>
    </div>
  );
};

export default ChatMessage;

import React, { useState, useRef, useEffect } from 'react';
import { Send, Image as ImageIcon, X, Loader2 } from 'lucide-react';

interface ChatInputProps {
  onSendMessage: (text: string, images: string[]) => void;
  isLoading: boolean;
}

const ChatInput: React.FC<ChatInputProps> = ({ onSendMessage, isLoading }) => {
  const [text, setText] = useState('');
  const [images, setImages] = useState<string[]>([]);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Auto-resize textarea
  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = Math.min(textareaRef.current.scrollHeight, 160) + 'px';
    }
  }, [text]);

  const handleSend = () => {
    if ((!text.trim() && images.length === 0) || isLoading) return;
    onSendMessage(text, images);
    setText('');
    setImages([]);
    if (textareaRef.current) textareaRef.current.style.height = 'auto';
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onloadend = () => {
        if (typeof reader.result === 'string') {
          setImages(prev => [...prev, reader.result as string]);
        }
      };
      reader.readAsDataURL(file);
    }
    // Reset input
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const removeImage = (index: number) => {
    setImages(prev => prev.filter((_, i) => i !== index));
  };

  return (
    <div className="w-full max-w-4xl mx-auto p-4">
      {/* Image Preview Area */}
      {images.length > 0 && (
        <div className="flex gap-3 mb-3 overflow-x-auto pb-2">
          {images.map((img, idx) => (
            <div key={idx} className="relative group flex-shrink-0">
              <img 
                src={img} 
                alt="Preview" 
                className="w-20 h-20 object-cover rounded-lg border border-zinc-700"
              />
              <button
                onClick={() => removeImage(idx)}
                className="absolute -top-2 -right-2 bg-zinc-800 text-zinc-400 hover:text-red-400 rounded-full p-1 shadow-lg border border-zinc-700 opacity-0 group-hover:opacity-100 transition-opacity"
              >
                <X size={12} />
              </button>
            </div>
          ))}
        </div>
      )}

      <div className="relative flex items-end bg-zinc-800/50 border border-zinc-700 rounded-2xl shadow-lg backdrop-blur-sm focus-within:ring-2 focus-within:ring-blue-500/50 focus-within:border-blue-500/50 transition-all">

        {/* Attachment Button */}
        <button
          onClick={() => fileInputRef.current?.click()}
          className="p-3 text-zinc-400 hover:text-zinc-200 transition-colors mb-[2px]"
          title="Attach Image"
          disabled={isLoading}
        >
          <ImageIcon size={20} />
        </button>
        <input 
          type="file" 
          ref={fileInputRef} 
          className="hidden" 
          accept="image/*"
          onChange={handleFileSelect}
        />

        {/* Text Input */}
        <textarea
          ref={textareaRef}
          value={text}
          onChange={(e) => setText(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder="Message Gemini Nexus..."
          className="w-full bg-transparent text-zinc-100 placeholder-zinc-500 p-3 max-h-40 resize-none focus:outline-none custom-scrollbar"
          rows={1}
          disabled={isLoading}
        />

        {/* Send Button */}
        <button
          onClick={handleSend}
          disabled={(!text.trim() && images.length === 0) || isLoading}
          className={`p-2 m-1.5 rounded-xl transition-all mb-[5px] ${
            (!text.trim() && images.length === 0) || isLoading
              ? 'bg-zinc-700 text-zinc-500 cursor-not-allowed'
              : 'bg-blue-600 text-white hover:bg-blue-500 shadow-lg shadow-blue-900/20'
          }`}
        >
          {isLoading ? <Loader2 size={18} className="animate-spin" /> : <Send size={18} />}
        </button>
      </div>

      <div className="text-center mt-2 text-xs text-zinc-500">
        Gemini may display inaccurate info, including about people, so double-check its responses.
      </div>
    </div>
  );
};

export default ChatInput;

