import { GoogleGenAI, Part } from "@google/genai";
import { ChatConfig, Message, Role } from '../types';

export class GeminiService {
  private ai: GoogleGenAI;

  constructor() {
    // Ensure API Key is available
    if (!process.env.API_KEY) {
      console.error("API_KEY is missing from environment variables.");
    }
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }

  async *streamChat(
    history: Message[], 
    newMessage: string, 
    images: string[], 
    config: ChatConfig
  ): AsyncGenerator<string | { groundingChunks: any[] }, void, unknown> {

    // Transform internal history to API format
    // Filter out error messages or loading states if necessary
    const chatHistory = history
      .filter(msg => !msg.isLoading && msg.role !== Role.SYSTEM) // System instruction is passed in config
      .map(msg => ({
        role: msg.role === Role.USER ? 'user' : 'model',
        parts: msg.images && msg.images.length > 0 
          ? [
              ...msg.images.map(img => ({ inlineData: { mimeType: 'image/jpeg', data: img.split(',')[1] } })),
              { text: msg.content }
            ]
          : [{ text: msg.content }]
      }));

    // Construct the current message parts
    const currentParts: Part[] = [];
    if (images.length > 0) {
      images.forEach(img => {
        // Assume base64 string includes prefix "data:image/jpeg;base64,"
        const base64Data = img.split(',')[1];
        currentParts.push({
          inlineData: {
            mimeType: 'image/jpeg', // Defaulting to jpeg for simplicity in this demo
            data: base64Data
          }
        });
      });
    }
    currentParts.push({ text: newMessage });

    // Prepare Tools
    const tools: any[] = [];
    if (config.useSearch) {
      tools.push({ googleSearch: {} });
    }

    // Prepare Thinking Config
    const thinkingConfig = config.useThinking 
      ? { thinkingBudget: 2048 } // A moderate budget for demo purposes
      : undefined;

    // Use chats.create to maintain session context easily if we were persisting the object,
    // but here we are stateless between calls for simplicity, re-hydrating history.
    // However, for correct "chat" behavior with the SDK, we can just use generateContent with history context manually
    // OR use the chat helper. Let's use the chat helper for cleaner code.

    const chat = this.ai.chats.create({
      model: config.model,
      history: chatHistory,
      config: {
        systemInstruction: config.systemInstruction,
        temperature: config.useThinking ? undefined : config.temperature, // Thinking models dictate their own temp usually
        tools: tools.length > 0 ? tools : undefined,
        thinkingConfig: thinkingConfig,
      }
    });

    try {
      const result = await chat.sendMessageStream({
        message: currentParts
      });

      for await (const chunk of result) {
        // Check for text content
        const text = chunk.text;
        if (text) {
          yield text;
        }

        // Check for grounding metadata
        const groundingChunks = chunk.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (groundingChunks) {
           yield { groundingChunks };
        }
      }
    } catch (error) {
      console.error("Gemini API Error:", error);
      throw error;
    }
  }
}

