import React, { useState, useRef, useEffect } from 'react';
import { Menu } from 'lucide-react';
import ChatMessage from './components/ChatMessage';
import ChatInput from './components/ChatInput';
import Sidebar from './components/Sidebar';
import { Message, Role, ChatConfig, DEFAULT_CONFIG, ChatSession } from './types';
import { geminiService } from './services/geminiService';

const App: React.FC = () => {
  // State for sessions and config
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [config, setConfig] = useState<ChatConfig>(DEFAULT_CONFIG);
  const [sidebarOpen, setSidebarOpen] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);

  // Load from local storage on mount
  useEffect(() => {
    const savedSessions = localStorage.getItem('gemini_nexus_sessions');
    if (savedSessions) {
      try {
        const parsed = JSON.parse(savedSessions);
        setSessions(parsed);
        if (parsed.length > 0) {
          setCurrentSessionId(parsed[parsed.length - 1].id);
        } else {
          createNewChat();
        }
      } catch (e) {
        console.error("Failed to load sessions", e);
        createNewChat();
      }
    } else {
      createNewChat();
    }
  }, []);

  // Save to local storage whenever sessions change
  useEffect(() => {
    if (sessions.length > 0) {
      localStorage.setItem('gemini_nexus_sessions', JSON.stringify(sessions));
    }
  }, [sessions]);

  // Derived state for current messages
  const currentSession = sessions.find(s => s.id === currentSessionId);
  const messages = currentSession ? currentSession.messages : [];

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const createNewChat = () => {
    const newSession: ChatSession = {
      id: Date.now().toString(),
      title: 'New Chat',
      messages: [],
      createdAt: Date.now(),
    };
    setSessions(prev => [...prev, newSession]);
    setCurrentSessionId(newSession.id);
    setIsLoading(false);
    if (window.innerWidth < 1024) setSidebarOpen(false);
  };

  const deleteSession = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    setSessions(prev => {
      const newSessions = prev.filter(s => s.id !== id);
      if (currentSessionId === id) {
        // If we deleted the current session, select the last one, or create new
        if (newSessions.length > 0) {
          setCurrentSessionId(newSessions[newSessions.length - 1].id);
        } else {
          // We can't call createNewChat directly here because we are in a state update
          // Just let the useEffect or next render handle empty state if we wanted, 
          // but better to manually trigger a reset if empty.
          // For simplicity, we'll allow empty state momentarily and creating a new one.
          setTimeout(() => createNewChat(), 0);
        }
      }
      // If we deleted the last session, clear local storage key to be clean
      if (newSessions.length === 0) {
         localStorage.removeItem('gemini_nexus_sessions');
      }
      return newSessions;
    });
  };

  const updateCurrentSessionMessages = (updateFn: (msgs: Message[]) => Message[]) => {
    setSessions(prev => prev.map(session => {
      if (session.id === currentSessionId) {
        const updatedMessages = updateFn(session.messages);

        // Auto-update title if it's the first message
        let newTitle = session.title;
        if (session.messages.length === 0 && updatedMessages.length > 0) {
          const firstUserMsg = updatedMessages.find(m => m.role === Role.USER);
          if (firstUserMsg) {
            newTitle = firstUserMsg.content.slice(0, 30) + (firstUserMsg.content.length > 30 ? '...' : '');
          }
        }

        return { ...session, messages: updatedMessages, title: newTitle };
      }
      return session;
    }));
  };

  const handleSendMessage = async (text: string, images: string[]) => {
    if (!currentSessionId) return;

    const newMessage: Message = {
      id: Date.now().toString(),
      role: Role.USER,
      content: text,
      timestamp: Date.now(),
      images: images
    };

    updateCurrentSessionMessages(prev => [...prev, newMessage]);
    setIsLoading(true);

    try {
      // Create a placeholder message for the bot
      const botMessageId = (Date.now() + 1).toString();
      updateCurrentSessionMessages(prev => [...prev, {
        id: botMessageId,
        role: Role.MODEL,
        content: '',
        timestamp: Date.now(),
        isLoading: true
      }]);

      // We need to pass the *current* messages plus the new one to the service.
      // Since state update is async, we construct the history manually here.
      const currentHistory = messages; 
      const historyWithUserMsg = [...currentHistory, newMessage];

      const stream = geminiService.streamChat(historyWithUserMsg, text, images, config);

      let fullContent = '';
      let groundingSources: any[] = [];

      for await (const chunk of stream) {
        updateCurrentSessionMessages(prev => prev.map(msg => {
          if (msg.id === botMessageId) {
            if (typeof chunk === 'string') {
              fullContent += chunk;
              return { ...msg, content: fullContent, isLoading: false };
            } 
            else if (typeof chunk === 'object' && 'groundingChunks' in chunk) {
              groundingSources = chunk.groundingChunks;
              return { ...msg, groundingSources: groundingSources, isLoading: false };
            }
          }
          return msg;
        }));
      }

    } catch (error) {
      console.error("Error sending message:", error);
      updateCurrentSessionMessages(prev => [...prev, {
        id: (Date.now() + 2).toString(),
        role: Role.MODEL,
        content: "I encountered an error while processing your request. Please try again.",
        timestamp: Date.now(),
        isLoading: false
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex h-screen bg-black overflow-hidden">
      {/* Sidebar */}
      <Sidebar 
        isOpen={sidebarOpen} 
        onClose={() => setSidebarOpen(false)}
        config={config}
        setConfig={setConfig}
        sessions={sessions}
        currentSessionId={currentSessionId}
        onSelectSession={setCurrentSessionId}
        onDeleteSession={deleteSession}
        onNewChat={createNewChat}
      />

      {/* Main Chat Area */}
      <div className="flex-1 flex flex-col h-full relative w-full">

        {/* Mobile Header */}
        <header className="lg:hidden flex items-center p-4 border-b border-zinc-800 bg-zinc-900/50 backdrop-blur-md sticky top-0 z-30">
          <button 
            onClick={() => setSidebarOpen(true)}
            className="text-zinc-400 hover:text-white p-2 -ml-2"
          >
            <Menu size={24} />
          </button>
          <span className="ml-2 font-semibold text-zinc-100">
            {currentSession?.title || 'Gemini Nexus'}
          </span>
        </header>

        {/* Messages List */}
        <main className="flex-1 overflow-y-auto p-4 md:p-6 scroll-smooth">
          {messages.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-zinc-500 space-y-4">
              <div className="w-20 h-20 bg-zinc-800 rounded-3xl flex items-center justify-center shadow-2xl shadow-blue-900/20 border border-zinc-700 rotate-3 transform hover:rotate-6 transition-transform duration-500">
                <span className="text-4xl">✨</span>
              </div>
              <h1 className="text-2xl font-bold text-zinc-200">Welcome to Gemini Nexus</h1>
              <p className="text-center max-w-md text-sm">
                Start a conversation to experience the power of Gemini 3. <br/>
                Try asking complex questions or uploading images.
              </p>
            </div>
          ) : (
            <div className="max-w-4xl mx-auto w-full pb-4">
              {messages.map((msg) => (
                <ChatMessage key={msg.id} message={msg} />
              ))}
              <div ref={messagesEndRef} />
            </div>
          )}
        </main>

        {/* Input Area */}
        <div className="p-4 bg-gradient-to-t from-black via-black to-transparent z-20">
          <ChatInput onSendMessage={handleSendMessage} isLoading={isLoading} />
        </div>
      </div>
    </div>
  );
};

export default App;

import React from 'react';
import ReactMarkdown from 'react-markdown';
import { Message, Role } from '../types';
import { User, Globe, Copy, Check } from 'lucide-react';

interface ChatMessageProps {
  message: Message;
}

const NexusLogo = () => (
  <svg width="100%" height="100%" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
    <path d="M12 2L2 7V17L12 22L22 17V7L12 2Z" className="fill-zinc-900 stroke-emerald-500" strokeWidth="2"/>
    <path d="M12 6L12 18M6 9L18 15M18 9L6 15" className="stroke-blue-400" strokeWidth="2" strokeLinecap="round"/>
  </svg>
);

const ChatMessage: React.FC<ChatMessageProps> = ({ message }) => {
  const isUser = message.role === Role.USER;
  const [copied, setCopied] = React.useState(false);

  const handleCopy = () => {
    navigator.clipboard.writeText(message.content);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className={`flex w-full mb-8 ${isUser ? 'justify-end' : 'justify-start'} group`}>
      <div className={`flex max-w-[90%] md:max-w-[80%] gap-4 ${isUser ? 'flex-row-reverse' : 'flex-row'}`}>

        {/* Avatar */}
        <div className="flex-shrink-0 flex flex-col items-center">
          <div className={`w-10 h-10 rounded-xl flex items-center justify-center shadow-lg ${
            isUser 
              ? 'bg-gradient-to-br from-blue-600 to-indigo-600' 
              : 'bg-zinc-900 border border-zinc-700'
          }`}>
            {isUser ? (
              <User size={20} className="text-white/90" />
            ) : (
              <div className="w-6 h-6">
                <NexusLogo />
              </div>
            )}
          </div>
        </div>

        {/* Content Bubble */}
        <div className={`flex flex-col ${isUser ? 'items-end' : 'items-start'} min-w-0`}>

          <div className={`relative px-6 py-5 shadow-md ${
            isUser 
              ? 'bg-gradient-to-br from-blue-600 via-blue-600 to-indigo-700 text-white rounded-2xl rounded-tr-sm' 
              : 'bg-zinc-800/60 backdrop-blur-sm text-zinc-100 rounded-2xl rounded-tl-sm border border-zinc-700/50'
          }`}>

            {/* Images if any */}
            {message.images && message.images.length > 0 && (
              <div className="flex flex-wrap gap-2 mb-4">
                {message.images.map((img, idx) => (
                  <img 
                    key={idx} 
                    src={img} 
                    alt={`attachment-${idx}`} 
                    className="max-w-[200px] max-h-[200px] rounded-lg object-cover border border-zinc-600/30 shadow-sm"
                  />
                ))}
              </div>
            )}

            {/* Loading Indicator */}
            {message.isLoading ? (
              <div className="flex space-x-2 h-6 items-center px-2">
                <div className="w-2 h-2 bg-gradient-to-r from-blue-400 to-emerald-400 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></div>
                <div className="w-2 h-2 bg-gradient-to-r from-blue-400 to-emerald-400 rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></div>
                <div className="w-2 h-2 bg-gradient-to-r from-blue-400 to-emerald-400 rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></div>
              </div>
            ) : (
              <div className="markdown-content text-[15px] leading-7 tracking-wide">
                <ReactMarkdown>{message.content}</ReactMarkdown>
              </div>
            )}

            {/* Copy Button (only for model messages) */}
            {!isUser && !message.isLoading && (
              <button 
                onClick={handleCopy}
                className="absolute bottom-2 right-2 p-1.5 text-zinc-500 hover:text-zinc-300 opacity-0 group-hover:opacity-100 transition-opacity rounded-md hover:bg-zinc-700/50"
                title="Copy response"
              >
                {copied ? <Check size={14} className="text-emerald-400" /> : <Copy size={14} />}
              </button>
            )}
          </div>

          {/* Metadata Row */}
          <div className="flex items-center gap-3 mt-2 px-1">
            <span className="text-[11px] text-zinc-500 font-medium">
               {isUser ? 'You' : 'Gemini Nexus'} • {new Date(message.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
            </span>

            {/* Grounding Sources */}
            {message.groundingSources && message.groundingSources.length > 0 && (
              <div className="flex items-center gap-2">
                <span className="text-zinc-700">•</span>
                <div className="flex items-center gap-1 text-[11px] text-blue-400 bg-blue-900/10 px-2 py-0.5 rounded-full border border-blue-900/20">
                  <Globe size={10} />
                  <span>{message.groundingSources.length} Sources</span>
                </div>
              </div>
            )}
          </div>

          {/* Sources Detail View */}
          {message.groundingSources && message.groundingSources.length > 0 && (
            <div className="mt-3 grid gap-2 w-full max-w-md">
               {message.groundingSources.map((source, idx) => (
                  source.web && (
                    <a 
                      key={idx}
                      href={source.web.uri} 
                      target="_blank" 
                      rel="noopener noreferrer"
                      className="flex items-center gap-2 p-2 rounded-lg bg-zinc-900/40 border border-zinc-800 hover:border-zinc-700 hover:bg-zinc-800/60 transition-all group/link"
                    >
                      <div className="w-6 h-6 rounded bg-zinc-800 flex items-center justify-center shrink-0 text-zinc-500 group-hover/link:text-zinc-300">
                        <Globe size={14} />
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="text-xs font-medium text-zinc-300 truncate group-hover/link:text-blue-400 transition-colors">
                          {source.web.title}
                        </div>
                        <div className="text-[10px] text-zinc-600 truncate">
                          {new URL(source.web.uri).hostname}
                        </div>
                      </div>
                    </a>
                  )
                ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default ChatMessage;

import React from 'react';
import { Settings, BrainCircuit, Globe, MessageSquare, X, Trash2, Clock } from 'lucide-react';
import { ChatConfig, AVAILABLE_MODELS, ChatSession } from '../types';

interface SidebarProps {
  isOpen: boolean;
  onClose: () => void;
  config: ChatConfig;
  setConfig: React.Dispatch<React.SetStateAction<ChatConfig>>;
  sessions: ChatSession[];
  currentSessionId: string | null;
  onSelectSession: (id: string) => void;
  onDeleteSession: (id: string, e: React.MouseEvent) => void;
  onNewChat: () => void;
}

const NexusLogo = () => (
  <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
    <path d="M12 2L2 7V17L12 22L22 17V7L12 2Z" className="fill-blue-500/20 stroke-blue-500" strokeWidth="2"/>
    <path d="M12 6L12 18M6 9L18 15M18 9L6 15" className="stroke-emerald-400" strokeWidth="2" strokeLinecap="round"/>
  </svg>
);

const Sidebar: React.FC<SidebarProps> = ({ 
  isOpen, 
  onClose, 
  config, 
  setConfig, 
  sessions, 
  currentSessionId, 
  onSelectSession, 
  onDeleteSession,
  onNewChat 
}) => {
  return (
    <>
      {/* Backdrop */}
      {isOpen && (
        <div 
          className="fixed inset-0 bg-black/50 backdrop-blur-sm z-40 lg:hidden"
          onClick={onClose}
        />
      )}

      {/* Sidebar Panel */}
      <div className={`fixed inset-y-0 left-0 z-50 w-72 bg-zinc-950 border-r border-zinc-800 transform transition-transform duration-300 ease-in-out ${
        isOpen ? 'translate-x-0' : '-translate-x-full'
      } lg:translate-x-0 lg:static lg:w-80 flex flex-col shadow-2xl lg:shadow-none`}>

        {/* Header */}
        <div className="p-6 border-b border-zinc-800/50 flex justify-between items-center shrink-0 bg-zinc-900/50">
          <div className="flex items-center gap-3">
            <div className="p-1 rounded-lg bg-zinc-900 border border-zinc-800">
               <NexusLogo />
            </div>
            <h2 className="text-xl font-bold bg-gradient-to-r from-blue-100 to-emerald-100 bg-clip-text text-transparent">
              Gemini Nexus
            </h2>
          </div>
          <button onClick={onClose} className="lg:hidden text-zinc-400 hover:text-white transition-colors">
            <X size={20} />
          </button>
        </div>

        {/* New Chat Button */}
        <div className="p-4 shrink-0">
            <button 
            onClick={() => {
              onNewChat();
              if (window.innerWidth < 1024) onClose();
            }}
            className="group w-full flex items-center justify-center gap-2 bg-zinc-100 hover:bg-white text-zinc-900 py-3 rounded-xl transition-all font-semibold shadow-lg shadow-zinc-900/20 active:scale-[0.98]"
            >
              <MessageSquare size={18} className="text-zinc-600 group-hover:text-zinc-900" />
              New Chat
            </button>
        </div>

        {/* Scrollable Content */}
        <div className="flex-1 overflow-y-auto min-h-0 custom-scrollbar">
          <div className="p-4 space-y-8">

            {/* Recent Chats Section */}
            {sessions.length > 0 && (
              <div className="space-y-3">
                <label className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest px-2 flex items-center gap-2">
                  <Clock size={10} /> Recent
                </label>
                <div className="space-y-1">
                  {sessions.slice().reverse().map(session => (
                    <div 
                      key={session.id}
                      onClick={() => {
                        onSelectSession(session.id);
                        if (window.innerWidth < 1024) onClose();
                      }}
                      className={`group flex items-center justify-between p-2.5 rounded-lg cursor-pointer transition-all border ${
                        currentSessionId === session.id
                          ? 'bg-zinc-800 border-zinc-700 text-zinc-100'
                          : 'text-zinc-400 hover:bg-zinc-900 hover:text-zinc-200 border-transparent hover:border-zinc-800'
                      }`}
                    >
                      <div className="flex items-center gap-3 overflow-hidden">
                        <div className={`w-1.5 h-1.5 rounded-full shrink-0 ${currentSessionId === session.id ? 'bg-blue-500' : 'bg-zinc-700'}`} />
                        <span className="text-sm truncate font-medium">{session.title}</span>
                      </div>
                      <button
                        onClick={(e) => onDeleteSession(session.id, e)}
                        className={`p-1.5 rounded-md hover:bg-red-500/10 hover:text-red-400 opacity-0 group-hover:opacity-100 transition-all ${
                          currentSessionId === session.id ? 'opacity-100' : ''
                        }`}
                        title="Delete chat"
                      >
                        <Trash2 size={12} />
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Model Selection */}
            <div className="space-y-3">
              <label className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest px-2">Model</label>
              <div className="space-y-2">
                {AVAILABLE_MODELS.map((m) => (
                  <div 
                    key={m.id}
                    onClick={() => setConfig(prev => ({ ...prev, model: m.id }))}
                    className={`p-3 rounded-lg border cursor-pointer transition-all relative overflow-hidden ${
                      config.model === m.id 
                        ? 'bg-gradient-to-r from-blue-900/20 to-emerald-900/20 border-blue-500/30' 
                        : 'bg-zinc-900 border-zinc-800 hover:border-zinc-700'
                    }`}
                  >
                    <div className="flex items-center justify-between mb-1 relative z-10">
                      <span className={`font-medium text-sm ${config.model === m.id ? 'text-blue-400' : 'text-zinc-300'}`}>
                        {m.name}
                      </span>
                      {config.model === m.id && <div className="w-2 h-2 rounded-full bg-blue-500 shadow-[0_0_8px_rgba(59,130,246,0.5)]" />}
                    </div>
                    <p className="text-[11px] text-zinc-500 relative z-10">{m.description}</p>
                  </div>
                ))}
              </div>
            </div>

            {/* Capabilities */}
            <div className="space-y-3">
              <label className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest px-2">Capabilities</label>

              {/* Thinking Toggle */}
              <div className="flex items-center justify-between p-3 rounded-lg bg-zinc-900 border border-zinc-800">
                <div className="flex items-center gap-3">
                  <div className={`p-2 rounded-md ${config.useThinking ? 'bg-purple-500/20 text-purple-400' : 'bg-zinc-800 text-zinc-500'}`}>
                    <BrainCircuit size={16} />
                  </div>
                  <div>
                    <div className="text-sm font-medium text-zinc-200">Deep Thinking</div>
                    <div className="text-[10px] text-zinc-500">Reasoning capabilities</div>
                  </div>
                </div>
                <button
                  onClick={() => setConfig(prev => ({ ...prev, useThinking: !prev.useThinking }))}
                  className={`w-9 h-5 rounded-full transition-colors relative ${
                    config.useThinking ? 'bg-purple-600' : 'bg-zinc-700'
                  }`}
                >
                  <div className={`absolute top-1 left-1 bg-white w-3 h-3 rounded-full transition-transform ${
                    config.useThinking ? 'translate-x-4' : 'translate-x-0'
                  }`} />
                </button>
              </div>

              {/* Search Toggle */}
              <div className="flex items-center justify-between p-3 rounded-lg bg-zinc-900 border border-zinc-800">
                <div className="flex items-center gap-3">
                  <div className={`p-2 rounded-md ${config.useSearch ? 'bg-blue-500/20 text-blue-400' : 'bg-zinc-800 text-zinc-500'}`}>
                    <Globe size={16} />
                  </div>
                  <div>
                    <div className="text-sm font-medium text-zinc-200">Google Search</div>
                    <div className="text-[10px] text-zinc-500">Real-time web data</div>
                  </div>
                </div>
                <button
                  onClick={() => setConfig(prev => ({ ...prev, useSearch: !prev.useSearch }))}
                  className={`w-9 h-5 rounded-full transition-colors relative ${
                    config.useSearch ? 'bg-blue-600' : 'bg-zinc-700'
                  }`}
                >
                  <div className={`absolute top-1 left-1 bg-white w-3 h-3 rounded-full transition-transform ${
                    config.useSearch ? 'translate-x-4' : 'translate-x-0'
                  }`} />
                </button>
              </div>
            </div>

            {/* System Instruction */}
            <div className="space-y-3">
              <label className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest px-2">System Persona</label>
              <textarea 
                value={config.systemInstruction}
                onChange={(e) => setConfig(prev => ({ ...prev, systemInstruction: e.target.value }))}
                className="w-full h-24 bg-zinc-900 border border-zinc-800 rounded-lg p-3 text-xs text-zinc-300 focus:outline-none focus:border-zinc-600 focus:ring-1 focus:ring-zinc-600 resize-none placeholder-zinc-600 transition-all"
                placeholder="How should the AI behave?"
              />
            </div>
          </div>
        </div>

        {/* Footer */}
        <div className="p-4 border-t border-zinc-800 shrink-0 bg-zinc-900/30">
          <div className="flex items-center gap-2 text-zinc-500 text-[11px] justify-center">
            <Settings size={12} />
            <span>Powered by Google Gemini</span>
          </div>
        </div>
      </div>
    </>
  );
};

export default Sidebar;

