import React, { useState, useRef, useEffect } from 'react';
import { Menu } from 'lucide-react';
import ChatMessage from './components/ChatMessage';
import ChatInput from './components/ChatInput';
import Sidebar from './components/Sidebar';
import { Message, Role, ChatConfig, DEFAULT_CONFIG, ChatSession } from './types';
import { geminiService } from './services/geminiService';

const App: React.FC = () => {
  // State for sessions and config
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [config, setConfig] = useState<ChatConfig>(DEFAULT_CONFIG);
  const [sidebarOpen, setSidebarOpen] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);

  // Load from local storage on mount
  useEffect(() => {
    const savedSessions = localStorage.getItem('neby_sessions');
    if (savedSessions) {
      try {
        const parsed = JSON.parse(savedSessions);
        setSessions(parsed);
        if (parsed.length > 0) {
          setCurrentSessionId(parsed[parsed.length - 1].id);
        } else {
          createNewChat();
        }
      } catch (e) {
        console.error("Failed to load sessions", e);
        createNewChat();
      }
    } else {
      createNewChat();
    }
  }, []);

  // Save to local storage whenever sessions change
  useEffect(() => {
    if (sessions.length > 0) {
      localStorage.setItem('neby_sessions', JSON.stringify(sessions));
    }
  }, [sessions]);

  // Derived state for current messages
  const currentSession = sessions.find(s => s.id === currentSessionId);
  const messages = currentSession ? currentSession.messages : [];

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const createNewChat = () => {
    const newSession: ChatSession = {
      id: Date.now().toString(),
      title: 'New Chat',
      messages: [],
      createdAt: Date.now(),
    };
    setSessions(prev => [...prev, newSession]);
    setCurrentSessionId(newSession.id);
    setIsLoading(false);
    if (window.innerWidth < 1024) setSidebarOpen(false);
  };

  const deleteSession = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    setSessions(prev => {
      const newSessions = prev.filter(s => s.id !== id);
      if (currentSessionId === id) {
        // If we deleted the current session, select the last one, or create new
        if (newSessions.length > 0) {
          setCurrentSessionId(newSessions[newSessions.length - 1].id);
        } else {
          // We can't call createNewChat directly here because we are in a state update
          // Just let the useEffect or next render handle empty state if we wanted, 
          // but better to manually trigger a reset if empty.
          // For simplicity, we'll allow empty state momentarily and creating a new one.
          setTimeout(() => createNewChat(), 0);
        }
      }
      // If we deleted the last session, clear local storage key to be clean
      if (newSessions.length === 0) {
         localStorage.removeItem('neby_sessions');
      }
      return newSessions;
    });
  };

  const updateCurrentSessionMessages = (updateFn: (msgs: Message[]) => Message[]) => {
    setSessions(prev => prev.map(session => {
      if (session.id === currentSessionId) {
        const updatedMessages = updateFn(session.messages);

        // Auto-update title if it's the first message
        let newTitle = session.title;
        if (session.messages.length === 0 && updatedMessages.length > 0) {
          const firstUserMsg = updatedMessages.find(m => m.role === Role.USER);
          if (firstUserMsg) {
            newTitle = firstUserMsg.content.slice(0, 30) + (firstUserMsg.content.length > 30 ? '...' : '');
          }
        }

        return { ...session, messages: updatedMessages, title: newTitle };
      }
      return session;
    }));
  };

  const handleSendMessage = async (text: string, images: string[]) => {
    if (!currentSessionId) return;

    const newMessage: Message = {
      id: Date.now().toString(),
      role: Role.USER,
      content: text,
      timestamp: Date.now(),
      images: images
    };

    updateCurrentSessionMessages(prev => [...prev, newMessage]);
    setIsLoading(true);

    try {
      // Create a placeholder message for the bot
      const botMessageId = (Date.now() + 1).toString();
      updateCurrentSessionMessages(prev => [...prev, {
        id: botMessageId,
        role: Role.MODEL,
        content: '',
        timestamp: Date.now(),
        isLoading: true
      }]);

      // We need to pass the *current* messages plus the new one to the service.
      // Since state update is async, we construct the history manually here.
      const currentHistory = messages; 
      const historyWithUserMsg = [...currentHistory, newMessage];

      const stream = geminiService.streamChat(historyWithUserMsg, text, images, config);

      let fullContent = '';
      let groundingSources: any[] = [];

      for await (const chunk of stream) {
        updateCurrentSessionMessages(prev => prev.map(msg => {
          if (msg.id === botMessageId) {
            if (typeof chunk === 'string') {
              fullContent += chunk;
              return { ...msg, content: fullContent, isLoading: false };
            } 
            else if (typeof chunk === 'object' && 'groundingChunks' in chunk) {
              groundingSources = chunk.groundingChunks;
              return { ...msg, groundingSources: groundingSources, isLoading: false };
            }
          }
          return msg;
        }));
      }

    } catch (error) {
      console.error("Error sending message:", error);
      updateCurrentSessionMessages(prev => [...prev, {
        id: (Date.now() + 2).toString(),
        role: Role.MODEL,
        content: "I encountered an error while processing your request. Please try again.",
        timestamp: Date.now(),
        isLoading: false
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex h-screen bg-black overflow-hidden">
      {/* Sidebar */}
      <Sidebar 
        isOpen={sidebarOpen} 
        onClose={() => setSidebarOpen(false)}
        config={config}
        setConfig={setConfig}
        sessions={sessions}
        currentSessionId={currentSessionId}
        onSelectSession={setCurrentSessionId}
        onDeleteSession={deleteSession}
        onNewChat={createNewChat}
      />

      {/* Main Chat Area */}
      <div className="flex-1 flex flex-col h-full relative w-full">

        {/* Mobile Header */}
        <header className="lg:hidden flex items-center p-4 border-b border-zinc-800 bg-zinc-900/50 backdrop-blur-md sticky top-0 z-30">
          <button 
            onClick={() => setSidebarOpen(true)}
            className="text-zinc-400 hover:text-white p-2 -ml-2"
          >
            <Menu size={24} />
          </button>
          <span className="ml-2 font-semibold text-zinc-100">
            {currentSession?.title || 'Neby'}
          </span>
        </header>

        {/* Messages List */}
        <main className="flex-1 overflow-y-auto p-4 md:p-6 scroll-smooth">
          {messages.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-zinc-500 space-y-4">
              <div className="w-20 h-20 bg-zinc-800 rounded-3xl flex items-center justify-center shadow-2xl shadow-blue-900/20 border border-zinc-700 rotate-3 transform hover:rotate-6 transition-transform duration-500">
                <span className="text-4xl">✨</span>
              </div>
              <h1 className="text-2xl font-bold text-zinc-200">Welcome to Neby</h1>
              <p className="text-center max-w-md text-sm">
                Start a conversation to experience the power of Gemini 3. <br/>
                Try asking complex questions or uploading images.
              </p>
            </div>
          ) : (
            <div className="max-w-4xl mx-auto w-full pb-4">
              {messages.map((msg) => (
                <ChatMessage key={msg.id} message={msg} />
              ))}
              <div ref={messagesEndRef} />
            </div>
          )}
        </main>

        {/* Input Area */}
        <div className="p-4 bg-gradient-to-t from-black via-black to-transparent z-20">
          <ChatInput onSendMessage={handleSendMessage} isLoading={isLoading} />
        </div>
      </div>
    </div>
  );
};

export default App;

