import React, { useState, useRef, useEffect } from 'react';
import { Send, Image as ImageIcon, X, Loader2, Mic, MicOff } from 'lucide-react';

interface ChatInputProps {
  onSendMessage: (text: string, images: string[]) => void;
  isLoading: boolean;
}

const ChatInput: React.FC<ChatInputProps> = ({ onSendMessage, isLoading }) => {
  const [text, setText] = useState('');
  const [images, setImages] = useState<string[]>([]);
  const [isListening, setIsListening] = useState(false);

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const recognitionRef = useRef<any>(null);

  // Auto-resize textarea
  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = Math.min(textareaRef.current.scrollHeight, 160) + 'px';
    }
  }, [text]);

  // Cleanup recognition on unmount
  useEffect(() => {
    return () => {
      if (recognitionRef.current) {
        recognitionRef.current.stop();
      }
    };
  }, []);

  const handleSend = () => {
    if ((!text.trim() && images.length === 0) || isLoading) return;
    onSendMessage(text, images);
    setText('');
    setImages([]);
    if (textareaRef.current) textareaRef.current.style.height = 'auto';
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onloadend = () => {
        if (typeof reader.result === 'string') {
          setImages(prev => [...prev, reader.result as string]);
        }
      };
      reader.readAsDataURL(file);
    }
    // Reset input
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const removeImage = (index: number) => {
    setImages(prev => prev.filter((_, i) => i !== index));
  };

  const toggleListening = async () => {
    if (isListening) {
      recognitionRef.current?.stop();
      setIsListening(false);
      return;
    }

    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      alert("Speech recognition is not supported in this browser.");
      return;
    }

    // Explicitly request microphone permission first.
    // This often fixes the 'not-allowed' error by triggering the browser's permission prompt.
    try {
      await navigator.mediaDevices.getUserMedia({ audio: true });
    } catch (err) {
      console.error("Microphone permission denied:", err);
      alert("Microphone access is denied. Please enable microphone permissions in your browser settings (usually the lock icon in the address bar).");
      return;
    }

    const recognition = new SpeechRecognition();
    recognition.continuous = true;
    recognition.interimResults = true;
    recognition.lang = 'en-US';

    recognition.onstart = () => setIsListening(true);

    recognition.onresult = (event: any) => {
      let finalTranscript = '';
      for (let i = event.resultIndex; i < event.results.length; ++i) {
        if (event.results[i].isFinal) {
          finalTranscript += event.results[i][0].transcript;
        }
      }

      if (finalTranscript) {
        setText(prev => {
          const prefix = prev && !prev.endsWith(' ') ? ' ' : '';
          return prev + prefix + finalTranscript;
        });
      }
    };

    recognition.onerror = (event: any) => {
      console.error("Speech recognition error", event.error);
      setIsListening(false);

      // Handle specific error codes
      if (event.error === 'not-allowed' || event.error === 'permission-denied') {
        alert("Microphone access is blocked. Please allow microphone access in your browser settings.");
      } else if (event.error === 'no-speech') {
        // Ignore "no speech detected" errors, just stop listening silently
        return;
      } else if (event.error === 'service-not-allowed') {
         alert("Speech recognition service is not allowed by your browser. Please check your privacy settings.");
      }
    };

    recognition.onend = () => {
      setIsListening(false);
    };

    recognitionRef.current = recognition;

    try {
      recognition.start();
    } catch (e) {
      console.error("Failed to start recognition:", e);
      setIsListening(false);
    }
  };

  return (
    <div className="w-full max-w-4xl mx-auto p-4">
      {/* Image Preview Area */}
      {images.length > 0 && (
        <div className="flex gap-3 mb-3 overflow-x-auto pb-2">
          {images.map((img, idx) => (
            <div key={idx} className="relative group flex-shrink-0">
              <img 
                src={img} 
                alt="Preview" 
                className="w-20 h-20 object-cover rounded-lg border border-zinc-700"
              />
              <button
                onClick={() => removeImage(idx)}
                className="absolute -top-2 -right-2 bg-zinc-800 text-zinc-400 hover:text-red-400 rounded-full p-1 shadow-lg border border-zinc-700 opacity-0 group-hover:opacity-100 transition-opacity"
              >
                <X size={12} />
              </button>
            </div>
          ))}
        </div>
      )}

      <div className="relative flex items-end bg-zinc-800/50 border border-zinc-700 rounded-2xl shadow-lg backdrop-blur-sm focus-within:ring-2 focus-within:ring-blue-500/50 focus-within:border-blue-500/50 transition-all">

        {/* Attachment Button */}
        <button
          onClick={() => fileInputRef.current?.click()}
          className="p-3 text-zinc-400 hover:text-zinc-200 transition-colors mb-[2px]"
          title="Attach Image"
          disabled={isLoading}
        >
          <ImageIcon size={20} />
        </button>
        <input 
          type="file" 
          ref={fileInputRef} 
          className="hidden" 
          accept="image/*"
          onChange={handleFileSelect}
        />

        {/* Microphone Button */}
        <button
          onClick={toggleListening}
          className={`p-3 transition-colors mb-[2px] ${
            isListening 
              ? 'text-red-500 hover:text-red-400 animate-pulse' 
              : 'text-zinc-400 hover:text-zinc-200'
          }`}
          title={isListening ? "Stop Recording" : "Start Voice Input"}
          disabled={isLoading}
        >
          {isListening ? <MicOff size={20} /> : <Mic size={20} />}
        </button>

        {/* Text Input */}
        <textarea
          ref={textareaRef}
          value={text}
          onChange={(e) => setText(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder={isListening ? "Listening..." : "Message Neby..."}
          className="w-full bg-transparent text-zinc-100 placeholder-zinc-500 p-3 max-h-40 resize-none focus:outline-none custom-scrollbar"
          rows={1}
          disabled={isLoading}
        />

        {/* Send Button */}
        <button
          onClick={handleSend}
          disabled={(!text.trim() && images.length === 0) || isLoading}
          className={`p-2 m-1.5 rounded-xl transition-all mb-[5px] ${
            (!text.trim() && images.length === 0) || isLoading
              ? 'bg-zinc-700 text-zinc-500 cursor-not-allowed'
              : 'bg-blue-600 text-white hover:bg-blue-500 shadow-lg shadow-blue-900/20'
          }`}
        >
          {isLoading ? <Loader2 size={18} className="animate-spin" /> : <Send size={18} />}
        </button>
      </div>

      <div className="text-center mt-2 text-xs text-zinc-500">
        Neby may display inaccurate info, including about people, so double-check its responses.
      </div>
    </div>
  );
};

export default ChatInput;

import React, { useState, useRef, useEffect } from 'react';
import { Menu } from 'lucide-react';
import ChatMessage from './components/ChatMessage';
import ChatInput from './components/ChatInput';
import Sidebar from './components/Sidebar';
import { Message, Role, ChatConfig, DEFAULT_CONFIG, ChatSession } from './types';
import { geminiService } from './services/geminiService';

const App: React.FC = () => {
  // State for sessions and config
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [config, setConfig] = useState<ChatConfig>(DEFAULT_CONFIG);

  // Initialize sidebarOpen based on screen width
  const [sidebarOpen, setSidebarOpen] = useState(() => typeof window !== 'undefined' ? window.innerWidth >= 1024 : false);

  const messagesEndRef = useRef<HTMLDivElement>(null);

  // Load from local storage on mount
  useEffect(() => {
    const savedSessions = localStorage.getItem('neby_sessions');
    if (savedSessions) {
      try {
        const parsed = JSON.parse(savedSessions);
        setSessions(parsed);
        if (parsed.length > 0) {
          setCurrentSessionId(parsed[parsed.length - 1].id);
        } else {
          createNewChat();
        }
      } catch (e) {
        console.error("Failed to load sessions", e);
        createNewChat();
      }
    } else {
      createNewChat();
    }
  }, []);

  // Save to local storage whenever sessions change
  useEffect(() => {
    if (sessions.length > 0) {
      localStorage.setItem('neby_sessions', JSON.stringify(sessions));
    }
  }, [sessions]);

  // Derived state for current messages
  const currentSession = sessions.find(s => s.id === currentSessionId);
  const messages = currentSession ? currentSession.messages : [];

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const createNewChat = () => {
    const newSession: ChatSession = {
      id: Date.now().toString(),
      title: 'New Chat',
      messages: [],
      createdAt: Date.now(),
    };
    setSessions(prev => [...prev, newSession]);
    setCurrentSessionId(newSession.id);
    setIsLoading(false);
    // Only close sidebar on mobile when creating new chat
    if (window.innerWidth < 1024) setSidebarOpen(false);
  };

  const deleteSession = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    setSessions(prev => {
      const newSessions = prev.filter(s => s.id !== id);
      if (currentSessionId === id) {
        if (newSessions.length > 0) {
          setCurrentSessionId(newSessions[newSessions.length - 1].id);
        } else {
          setTimeout(() => createNewChat(), 0);
        }
      }
      if (newSessions.length === 0) {
         localStorage.removeItem('neby_sessions');
      }
      return newSessions;
    });
  };

  const updateCurrentSessionMessages = (updateFn: (msgs: Message[]) => Message[]) => {
    setSessions(prev => prev.map(session => {
      if (session.id === currentSessionId) {
        const updatedMessages = updateFn(session.messages);

        let newTitle = session.title;
        if (session.messages.length === 0 && updatedMessages.length > 0) {
          const firstUserMsg = updatedMessages.find(m => m.role === Role.USER);
          if (firstUserMsg) {
            newTitle = firstUserMsg.content.slice(0, 30) + (firstUserMsg.content.length > 30 ? '...' : '');
          }
        }

        return { ...session, messages: updatedMessages, title: newTitle };
      }
      return session;
    }));
  };

  const handleSendMessage = async (text: string, images: string[]) => {
    if (!currentSessionId) return;

    const newMessage: Message = {
      id: Date.now().toString(),
      role: Role.USER,
      content: text,
      timestamp: Date.now(),
      images: images
    };

    updateCurrentSessionMessages(prev => [...prev, newMessage]);
    setIsLoading(true);

    try {
      const botMessageId = (Date.now() + 1).toString();
      updateCurrentSessionMessages(prev => [...prev, {
        id: botMessageId,
        role: Role.MODEL,
        content: '',
        timestamp: Date.now(),
        isLoading: true
      }]);

      const currentHistory = messages; 
      const historyWithUserMsg = [...currentHistory, newMessage];

      const stream = geminiService.streamChat(historyWithUserMsg, text, images, config);

      let fullContent = '';
      let groundingSources: any[] = [];

      for await (const chunk of stream) {
        updateCurrentSessionMessages(prev => prev.map(msg => {
          if (msg.id === botMessageId) {
            if (typeof chunk === 'string') {
              fullContent += chunk;
              return { ...msg, content: fullContent, isLoading: false };
            } 
            else if (typeof chunk === 'object' && 'groundingChunks' in chunk) {
              groundingSources = chunk.groundingChunks;
              return { ...msg, groundingSources: groundingSources, isLoading: false };
            }
          }
          return msg;
        }));
      }

    } catch (error) {
      console.error("Error sending message:", error);
      updateCurrentSessionMessages(prev => [...prev, {
        id: (Date.now() + 2).toString(),
        role: Role.MODEL,
        content: "I encountered an error while processing your request. Please try again.",
        timestamp: Date.now(),
        isLoading: false
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex h-screen bg-transparent overflow-hidden relative">
      {/* Sidebar */}
      <Sidebar 
        isOpen={sidebarOpen} 
        onClose={() => setSidebarOpen(false)}
        config={config}
        setConfig={setConfig}
        sessions={sessions}
        currentSessionId={currentSessionId}
        onSelectSession={setCurrentSessionId}
        onDeleteSession={deleteSession}
        onNewChat={createNewChat}
      />

      {/* Main Chat Area */}
      <div className={`flex-1 flex flex-col h-full relative w-full transition-all duration-300 ease-in-out ${sidebarOpen ? 'lg:ml-80' : 'lg:ml-0'}`}>

        {/* Header */}
        <header className="flex items-center p-4 border-b border-white/10 bg-black/20 backdrop-blur-md sticky top-0 z-30">
          <button 
            onClick={() => setSidebarOpen(prev => !prev)}
            className="text-zinc-400 hover:text-white p-2 -ml-2 rounded-lg hover:bg-white/10 transition-colors"
          >
            <Menu size={24} />
          </button>
          <span className="ml-4 font-semibold text-zinc-100 truncate shadow-black drop-shadow-sm">
            {currentSession?.title || 'Neby'}
          </span>
        </header>

        {/* Messages List */}
        <main className="flex-1 overflow-y-auto p-4 md:p-6 scroll-smooth">
          {messages.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-zinc-400 space-y-4">
              <div className="w-20 h-20 bg-white/5 backdrop-blur-xl rounded-3xl flex items-center justify-center shadow-2xl shadow-purple-900/40 border border-white/10 rotate-3 transform hover:rotate-6 transition-transform duration-500">
                <span className="text-4xl filter drop-shadow-[0_0_10px_rgba(168,85,247,0.5)]">✨</span>
              </div>
              <h1 className="text-3xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-200 via-indigo-200 to-purple-200 drop-shadow-sm">
                Welcome to Neby
              </h1>
              <p className="text-center max-w-md text-sm text-zinc-400 leading-relaxed">
                Your cosmic companion powered by Gemini 3.<br/>
                Ready to explore ideas, reason through problems, and create.
              </p>
            </div>
          ) : (
            <div className="max-w-4xl mx-auto w-full pb-4">
              {messages.map((msg) => (
                <ChatMessage key={msg.id} message={msg} />
              ))}
              <div ref={messagesEndRef} />
            </div>
          )}
        </main>

        {/* Input Area */}
        <div className="p-4 bg-gradient-to-t from-[#030014] via-[#030014]/80 to-transparent z-20">
          <ChatInput onSendMessage={handleSendMessage} isLoading={isLoading} />
        </div>
      </div>
    </div>
  );
};

export default App;

