            {message.isLoading ? (
              <div className="flex space-x-2 h-6 items-center px-2">
                <div className="w-2 h-2 bg-gradient-to-r from-indigo-400 to-purple-400 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></div>
