    recognition.onerror = (event: any) => {
      console.error("Speech recognition error", event.error);
      // Don't turn off if it's just 'no-speech' which happens during pauses
      if (event.error === 'no-speech') return;

      setIsListening(false);
      if (event.error === 'not-allowed' || event.error === 'permission-denied') {
        alert("Microphone access is blocked. Please allow microphone access in your browser settings.");
      }
    };

    recognition.onend = () => {
      // Only set to false if we didn't manually stop it (which handles state change)
      // For simple toggle logic, this is fine, but loop prevention matters.
      // If the user stops talking, we usually want to keep listening until they hit the button, 
      // but 'continuous=true' handles that mostly. onend fires when it completely stops.
      setIsListening(false);
    };

    recognitionRef.current = recognition;

    try {
      recognition.start();
    } catch (e) {
      console.error("Failed to start recognition:", e);
      setIsListening(false);
    }
  };

  return (
    <div className="w-full max-w-4xl mx-auto p-4">
      {/* Image Preview Area */}
      {images.length > 0 && (
        <div className="flex gap-3 mb-3 overflow-x-auto pb-2">
          {images.map((img, idx) => (
            <div key={idx} className="relative group flex-shrink-0">
              <img 
                src={img} 
                alt="Preview" 
                className="w-20 h-20 object-cover rounded-lg border border-white/20"
              />
              <button
                onClick={() => removeImage(idx)}
                className="absolute -top-2 -right-2 bg-black/80 text-zinc-400 hover:text-red-400 rounded-full p-1 shadow-lg border border-white/10 opacity-0 group-hover:opacity-100 transition-opacity"
              >
                <X size={12} />
              </button>
            </div>
          ))}
        </div>
      )}

      <div className="relative flex items-end bg-black/40 border border-white/10 rounded-2xl shadow-xl backdrop-blur-xl focus-within:ring-2 focus-within:ring-indigo-500/40 focus-within:border-indigo-500/40 transition-all">

        {/* Attachment Button */}
        <button
          onClick={() => fileInputRef.current?.click()}
          className="p-3 text-zinc-400 hover:text-indigo-300 transition-colors mb-[2px]"
          title="Attach Image"
          disabled={isLoading}
        >
          <ImageIcon size={20} />
        </button>
        <input 
          type="file" 
          ref={fileInputRef} 
          className="hidden" 
          accept="image/*"
          onChange={handleFileSelect}
        />

        {/* Microphone Button */}
        <button
          onClick={toggleListening}
          className={`p-3 transition-colors mb-[2px] ${
            isListening 
              ? 'text-red-500 hover:text-red-400 animate-pulse' 
              : 'text-zinc-400 hover:text-zinc-200'
          }`}
          title={isListening ? "Stop Recording" : "Start Voice Input"}
          disabled={isLoading}
        >
          {isListening ? <MicOff size={20} /> : <Mic size={20} />}
        </button>

        {/* Text Input */}
        <textarea
          ref={textareaRef}
          value={text}
          onChange={(e) => setText(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder={isListening ? "Listening..." : "Message Neby..."}
          className="w-full bg-transparent text-zinc-100 placeholder-zinc-500 p-3 max-h-40 resize-none focus:outline-none custom-scrollbar"
          rows={1}
          disabled={isLoading}
        />

        {/* Send Button */}
        <button
          onClick={handleSend}
          disabled={(!text.trim() && images.length === 0) || isLoading}
          className={`p-2 m-1.5 rounded-xl transition-all mb-[5px] ${
            (!text.trim() && images.length === 0) || isLoading
              ? 'bg-white/5 text-zinc-600 cursor-not-allowed'
              : 'bg-indigo-600 text-white hover:bg-indigo-500 shadow-lg shadow-indigo-900/30'
          }`}
        >
          {isLoading ? <Loader2 size={18} className="animate-spin" /> : <Send size={18} />}
        </button>
      </div>

      <div className="text-center mt-2 text-xs text-zinc-500/80">
        Neby may display inaccurate info, including about people, so double-check its responses.
      </div>
    </div>
  );
};

