import React, { useState, useRef, useEffect } from 'react';
import { Send, Image as ImageIcon, X, Loader2, Mic, MicOff } from 'lucide-react';

interface ChatInputProps {
  onSendMessage: (text: string, images: string[]) => void;
  isLoading: boolean;
}

const ChatInput: React.FC<ChatInputProps> = ({ onSendMessage, isLoading }) => {
  const [text, setText] = useState('');
  const [interimText, setInterimText] = useState('');
  const [images, setImages] = useState<string[]>([]);
  const [isListening, setIsListening] = useState(false);

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const recognitionRef = useRef<any>(null);

  // Auto-resize textarea
  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = Math.min(textareaRef.current.scrollHeight, 160) + 'px';
    }
  }, [text, interimText]);

  // Cleanup recognition on unmount
  useEffect(() => {
    return () => {
      if (recognitionRef.current) {
        recognitionRef.current.abort();
      }
    };
  }, []);

  const handleSend = () => {
    const finalMsg = (text + ' ' + interimText).trim();
    if ((!finalMsg && images.length === 0) || isLoading) return;

    onSendMessage(finalMsg, images);
    setText('');
    setInterimText('');
    setImages([]);
    if (textareaRef.current) textareaRef.current.style.height = 'auto';

    // Stop listening if we send a message
    if (isListening) {
      stopListening();
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onloadend = () => {
        if (typeof reader.result === 'string') {
          setImages(prev => [...prev, reader.result as string]);
        }
      };
      reader.readAsDataURL(file);
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const removeImage = (index: number) => {
    setImages(prev => prev.filter((_, i) => i !== index));
  };

  const stopListening = () => {
    if (recognitionRef.current) {
      recognitionRef.current.stop();
      recognitionRef.current = null;
    }
    setIsListening(false);
    setInterimText('');
  };

  const toggleListening = async () => {
    if (isListening) {
      stopListening();
      return;
    }

    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      alert("Speech recognition is not supported in this browser. Please try Chrome or Edge.");
      return;
    }

    try {
      if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
        throw new Error("Browser does not support audio capture.");
      }
      await navigator.mediaDevices.getUserMedia({ audio: true });
    } catch (err: any) {
      console.error("Microphone initialization error:", err);
      let msg = "Could not access microphone.";
      if (err.name === 'NotAllowedError' || err.name === 'PermissionDeniedError') {
        msg = "Microphone access blocked. Please allow permissions in your browser settings.";
      }
      alert(msg);
      return;
    }

    const recognition = new SpeechRecognition();
    recognition.continuous = true;
    recognition.interimResults = true;
    recognition.lang = 'en-US';

    recognition.onstart = () => {
      setIsListening(true);
    };

    recognition.onresult = (event: any) => {
      let finalTranscript = '';
      let interimTranscript = '';

      for (let i = event.resultIndex; i < event.results.length; ++i) {
        const transcript = event.results[i][0].transcript;
        if (event.results[i].isFinal) {
          finalTranscript += transcript;
        } else {
          interimTranscript += transcript;
        }
      }

      if (finalTranscript) {
        setText(prev => {
          const prefix = prev && !prev.endsWith(' ') ? ' ' : '';
          return prev + prefix + finalTranscript.trim();
        });
      }
      setInterimText(interimTranscript);
    };

    recognition.onerror = (event: any) => {
      console.error("Speech recognition error:", event.error);
      if (event.error === 'no-speech') return;

      setIsListening(false);
      setInterimText('');

      if (event.error === 'not-allowed') {
        alert("Microphone access blocked. Check browser settings.");
      } else if (event.error === 'network') {
        alert("Network error occurred during speech recognition.");
      }
    };

    recognition.onend = () => {
      // If we didn't stop it manually and it ended, reset state
      if (recognitionRef.current === recognition) {
        setIsListening(false);
        setInterimText('');
      }
    };

    recognitionRef.current = recognition;

    try {
      recognition.start();
    } catch (e) {
      console.error("Failed to start recognition:", e);
      setIsListening(false);
    }
  };

  return (
    <div className="w-full max-w-4xl mx-auto p-4">
      {/* Image Preview Area */}
      {images.length > 0 && (
        <div className="flex gap-3 mb-3 overflow-x-auto pb-2">
          {images.map((img, idx) => (
            <div key={idx} className="relative group flex-shrink-0">
              <img 
                src={img} 
                alt="Preview" 
                className="w-20 h-20 object-cover rounded-lg border border-white/20"
              />
              <button
                onClick={() => removeImage(idx)}
                className="absolute -top-2 -right-2 bg-black/80 text-zinc-400 hover:text-red-400 rounded-full p-1 shadow-lg border border-white/10 opacity-0 group-hover:opacity-100 transition-opacity"
              >
                <X size={12} />
              </button>
            </div>
          ))}
        </div>
      )}

      <div className="relative flex flex-col bg-black/40 border border-white/10 rounded-2xl shadow-xl backdrop-blur-xl focus-within:ring-2 focus-within:ring-indigo-500/40 focus-within:border-indigo-500/40 transition-all overflow-hidden">

        <div className="flex items-end">
          {/* Attachment Button */}
          <button
            onClick={() => fileInputRef.current?.click()}
            className="p-3 text-zinc-400 hover:text-indigo-300 transition-colors mb-[2px]"
            title="Attach Image"
            disabled={isLoading}
          >
            <ImageIcon size={20} />
          </button>
          <input 
            type="file" 
            ref={fileInputRef} 
            className="hidden" 
            accept="image/*"
            onChange={handleFileSelect}
          />

          {/* Microphone Button */}
          <button
            onClick={toggleListening}
            className={`p-3 transition-colors mb-[2px] ${
              isListening 
                ? 'text-red-500 hover:text-red-400' 
                : 'text-zinc-400 hover:text-zinc-200'
            }`}
            title={isListening ? "Stop Recording" : "Start Voice Input"}
            disabled={isLoading}
          >
            {isListening ? (
              <div className="relative">
                <MicOff size={20} />
                <span className="absolute -top-1 -right-1 w-2 h-2 bg-red-500 rounded-full animate-ping"></span>
              </div>
            ) : (
              <Mic size={20} />
            )}
          </button>

          {/* Text Input */}
          <div className="flex-1 relative">
            <textarea
              ref={textareaRef}
              value={isListening ? text + (interimText ? (text ? ' ' : '') + interimText : '') : text}
              onChange={(e) => {
                if (!isListening) setText(e.target.value);
              }}
              onKeyDown={handleKeyDown}
              placeholder={isListening ? "Listening... Speak now" : "Message Neby..."}
              className={`w-full bg-transparent text-zinc-100 placeholder-zinc-500 p-3 max-h-40 resize-none focus:outline-none custom-scrollbar transition-opacity ${isListening ? 'cursor-default' : ''}`}
              rows={1}
              disabled={isLoading}
              readOnly={isListening}
            />
          </div>

          {/* Send Button */}
          <button
            onClick={handleSend}
            disabled={(!text.trim() && !interimText.trim() && images.length === 0) || isLoading}
            className={`p-2 m-1.5 rounded-xl transition-all mb-[5px] ${
              (!text.trim() && !interimText.trim() && images.length === 0) || isLoading
                ? 'bg-white/5 text-zinc-600 cursor-not-allowed'
                : 'bg-indigo-600 text-white hover:bg-indigo-500 shadow-lg shadow-indigo-900/30'
            }`}
          >
            {isLoading ? <Loader2 size={18} className="animate-spin" /> : <Send size={18} />}
          </button>
        </div>

        {/* Listening Indicator Bar */}
        {isListening && (
          <div className="h-1 bg-zinc-800 w-full overflow-hidden">
            <div className="h-full bg-gradient-to-r from-indigo-500 via-purple-500 to-indigo-500 w-full animate-[shimmer_2s_infinite] bg-[length:200%_100%]"></div>
          </div>
        )}
      </div>

      <div className="text-center mt-2 text-xs text-zinc-500/80">
        Neby may display inaccurate info, including about people, so double-check its responses.
      </div>

      <style>{`
        @keyframes shimmer {
          0% { background-position: 100% 0; }
          100% { background-position: -100% 0; }
        }
      `}</style>
    </div>
  );
};

