import React, { useState, useRef, useEffect } from 'react';
import { Send, Image as ImageIcon, X, Loader2, Mic, MicOff, AlertCircle } from 'lucide-react';

interface ChatInputProps {
  onSendMessage: (text: string, images: string[]) => void;
  isLoading: boolean;
}

const ChatInput: React.FC<ChatInputProps> = ({ onSendMessage, isLoading }) => {
  const [text, setText] = useState('');
  const [interimText, setInterimText] = useState('');
  const [images, setImages] = useState<string[]>([]);
  const [isListening, setIsListening] = useState(false);
  const [speechError, setSpeechError] = useState<string | null>(null);

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const recognitionRef = useRef<any>(null);

  // Auto-resize textarea
  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = Math.min(textareaRef.current.scrollHeight, 160) + 'px';
    }
  }, [text, interimText]);

  // Cleanup recognition on unmount
  useEffect(() => {
    return () => {
      if (recognitionRef.current) {
        try {
          recognitionRef.current.abort();
        } catch (e) {
          // Ignore cleanup errors
        }
      }
    };
  }, []);

  const handleSend = () => {
    const finalMsg = (text + ' ' + interimText).trim();
    if ((!finalMsg && images.length === 0) || isLoading) return;

    onSendMessage(finalMsg, images);
    setText('');
    setInterimText('');
    setImages([]);
    setSpeechError(null);
    if (textareaRef.current) textareaRef.current.style.height = 'auto';

    if (isListening) {
      stopListening();
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onloadend = () => {
        if (typeof reader.result === 'string') {
          setImages(prev => [...prev, reader.result as string]);
        }
      };
      reader.readAsDataURL(file);
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const removeImage = (index: number) => {
    setImages(prev => prev.filter((_, i) => i !== index));
  };

  const stopListening = () => {
    if (recognitionRef.current) {
      try {
        // Use abort for a cleaner, immediate cut-off
        recognitionRef.current.abort();
      } catch (e) {
        console.warn("Recognition already stopped.");
      }
      recognitionRef.current = null;
    }
    setIsListening(false);
    setInterimText('');
  };

  const toggleListening = async () => {
    // Clear any previous error when attempting to start again
    if (speechError) setSpeechError(null);

    if (isListening) {
      stopListening();
      return;
    }

    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      setSpeechError("Browser not supported");
      return;
    }

    try {
      // Prompt for microphone access first to ensure we have it
      await navigator.mediaDevices.getUserMedia({ audio: true });
    } catch (err: any) {
      console.error("Microphone access denied:", err);
      setSpeechError("Mic access denied");
      return;
    }

    // Defensive cleanup of any existing instance
    if (recognitionRef.current) {
      try { recognitionRef.current.abort(); } catch(e) {}
    }

    const recognition = new SpeechRecognition();
    recognition.continuous = true;
    recognition.interimResults = true;
    recognition.lang = 'en-US';

    recognition.onstart = () => {
      setIsListening(true);
      setSpeechError(null);
    };

    recognition.onresult = (event: any) => {
      let finalTranscript = '';
      let interimTranscript = '';

      for (let i = event.resultIndex; i < event.results.length; ++i) {
        const transcript = event.results[i][0].transcript;
        if (event.results[i].isFinal) {
          finalTranscript += transcript;
        } else {
          interimTranscript += transcript;
        }
      }

      if (finalTranscript) {
        setText(prev => {
          const prefix = prev && !prev.endsWith(' ') ? ' ' : '';
          return prev + prefix + finalTranscript.trim();
        });
      }
      setInterimText(interimTranscript);
    };

    recognition.onerror = (event: any) => {
      console.error("Speech recognition error:", event.error);

      // 'no-speech' is usually transient, we don't necessarily want to kill the UI
      if (event.error === 'no-speech') return;

      setIsListening(false);
      setInterimText('');

      // Critical: Immediately abort the instance on hard errors like 'network'
      if (recognitionRef.current) {
        try { recognitionRef.current.abort(); } catch(e) {}
        recognitionRef.current = null;
      }

      if (event.error === 'network') {
        setSpeechError("Network error. Try again?");
      } else if (event.error === 'not-allowed') {
        setSpeechError("Mic blocked.");
      } else if (event.error === 'audio-capture') {
        setSpeechError("No mic found.");
      } else {
        setSpeechError(`Error: ${event.error}`);
      }
    };

    recognition.onend = () => {
      // If the engine ends unexpectedly (not via stopListening), clean up state
      if (recognitionRef.current === recognition) {
        setIsListening(false);
        setInterimText('');
        recognitionRef.current = null;
      }
    };

    recognitionRef.current = recognition;

    try {
      recognition.start();
    } catch (e) {
      console.error("Failed to start recognition:", e);
      setIsListening(false);
      setSpeechError("Service failed");
      recognitionRef.current = null;
    }
  };

  const currentInputValue = isListening 
    ? text + (interimText ? (text ? ' ' : '') + interimText : '') 
    : text;

  const placeholderText = isLoading 
    ? "Thinking..." 
    : speechError 
      ? speechError 
      : isListening 
        ? "Listening..." 
        : "Message Neby...";

  return (
    <div className="w-full max-w-4xl mx-auto p-4">
      {/* Image Preview Area */}
      {images.length > 0 && (
        <div className="flex gap-3 mb-3 overflow-x-auto pb-2 custom-scrollbar">
          {images.map((img, idx) => (
            <div key={idx} className="relative group flex-shrink-0">
              <img 
                src={img} 
                alt="Preview" 
                className="w-20 h-20 object-cover rounded-lg border border-white/20 shadow-xl"
              />
              <button
                onClick={() => removeImage(idx)}
                className="absolute -top-2 -right-2 bg-black/80 text-zinc-400 hover:text-red-400 rounded-full p-1 shadow-lg border border-white/10 opacity-0 group-hover:opacity-100 transition-opacity"
              >
                <X size={12} />
              </button>
            </div>
          ))}
        </div>
      )}

      <div className={`relative flex flex-col bg-black/40 border rounded-2xl shadow-2xl backdrop-blur-xl transition-all duration-300 overflow-hidden ${
        speechError 
          ? 'border-red-500/50 ring-2 ring-red-500/10' 
          : 'border-white/10 focus-within:ring-2 focus-within:ring-indigo-500/40 focus-within:border-indigo-500/40'
      }`}>

        <div className="flex items-end">
          {/* Attachment Button */}
          <button
            onClick={() => fileInputRef.current?.click()}
            className="p-3 text-zinc-400 hover:text-indigo-300 transition-colors mb-[2px]"
            title="Attach Image"
            disabled={isLoading}
          >
            <ImageIcon size={20} />
          </button>
          <input 
            type="file" 
            ref={fileInputRef} 
            className="hidden" 
            accept="image/*"
            onChange={handleFileSelect}
          />

          {/* Microphone Button */}
          <button
            onClick={toggleListening}
            className={`p-3 transition-all mb-[2px] ${
              isListening 
                ? 'text-red-500 hover:text-red-400 scale-110' 
                : speechError 
                  ? 'text-red-500' 
                  : 'text-zinc-400 hover:text-zinc-200'
            }`}
            title={isListening ? "Stop Recording" : "Start Voice Input"}
            disabled={isLoading}
          >
            {isListening ? (
              <div className="relative">
                <MicOff size={20} />
                <span className="absolute -top-1 -right-1 w-2 h-2 bg-red-500 rounded-full animate-ping"></span>
              </div>
            ) : speechError ? (
              <AlertCircle size={20} className="animate-pulse" />
            ) : (
              <Mic size={20} />
            )}
          </button>

          {/* Text Input */}
          <div className="flex-1 relative">
            <textarea
              ref={textareaRef}
              value={currentInputValue}
              onChange={(e) => {
                if (!isListening) {
                  setText(e.target.value);
                  if (speechError) setSpeechError(null);
                }
              }}
              onKeyDown={handleKeyDown}
              placeholder={placeholderText}
              className={`w-full bg-transparent text-zinc-100 placeholder-zinc-500 p-3 max-h-40 resize-none focus:outline-none custom-scrollbar transition-opacity ${
                isListening ? 'cursor-default opacity-80' : ''
