import { GoogleGenAI, Part } from "@google/genai";
import { ChatConfig, Message, Role } from '../types';

export class GeminiService {
  private ai: GoogleGenAI;

  constructor() {
    // Ensure API Key is available
    if (!process.env.API_KEY) {
      console.error("API_KEY is missing from environment variables.");
    }
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }

  /**
   * Generates audio from text using the specialized TTS model.
   * Returns a base64 string of raw PCM data.
   */
  async generateSpeech(text: string): Promise<string> {
    try {
      const response = await this.ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: `Read this message naturally: ${text}` }] }],
        config: {
          responseModalities: ['AUDIO' as any], // Cast for SDK compatibility if Modality enum is tricky
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: 'Kore' },
            },
          },
        },
      });

      const audioBase64 = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (!audioBase64) {
        throw new Error("No audio data returned from Gemini TTS");
      }
      return audioBase64;
    } catch (error) {
      console.error("Gemini TTS Error:", error);
      throw error;
    }
  }

  async *streamChat(
    history: Message[], 
    newMessage: string, 
    images: string[], 
    config: ChatConfig
  ): AsyncGenerator<string | { groundingChunks: any[] }, void, unknown> {

    // Transform internal history to API format
    const chatHistory = history
      .filter(msg => !msg.isLoading && msg.role !== Role.SYSTEM) 
      .map(msg => ({
        role: msg.role === Role.USER ? 'user' : 'model',
        parts: msg.images && msg.images.length > 0 
          ? [
              ...msg.images.map(img => ({ inlineData: { mimeType: 'image/jpeg', data: img.split(',')[1] } })),
              { text: msg.content }
            ]
          : [{ text: msg.content }]
      }));

    // Construct the current message parts
    const currentParts: Part[] = [];
    if (images.length > 0) {
      images.forEach(img => {
        const base64Data = img.split(',')[1];
        currentParts.push({
          inlineData: {
            mimeType: 'image/jpeg',
            data: base64Data
          }
        });
      });
    }
    currentParts.push({ text: newMessage });

    // Prepare Tools
    const tools: any[] = [];
    if (config.useSearch) {
      tools.push({ googleSearch: {} });
    }

    // Prepare Thinking Config
    // Thinking Config is only available for the Gemini 3 and 2.5 series models.
    const isThinkingSupported = config.model.includes('gemini-3') || config.model.includes('gemini-2.5');
    const thinkingConfig = (config.useThinking && isThinkingSupported)
      ? { thinkingBudget: 4096 } 
      : undefined;

    // Detect if model supports multi-turn history.
    const isSingleTurnOnly = config.model.includes('tts');

    // Construct the contents array.
    const contents = isSingleTurnOnly 
      ? [{ role: 'user', parts: currentParts }]
      : [
          ...chatHistory,
          { role: 'user', parts: currentParts }
        ];

    try {
      const result = await this.ai.models.generateContentStream({
        model: config.model,
        contents: contents,
        config: {
          systemInstruction: config.systemInstruction,
          temperature: config.useThinking ? undefined : config.temperature,
          tools: tools.length > 0 ? tools : undefined,
          thinkingConfig: thinkingConfig,
        }
      });

      for await (const chunk of result) {
        // Check for text content
        const text = chunk.text;
        if (text) {
          yield text;
        }

        // Check for grounding metadata
        const groundingChunks = chunk.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (groundingChunks) {
           yield { groundingChunks };
        }

        // Handle Safety Finish Reason
        const candidate = chunk.candidates?.[0];
        if (candidate?.finishReason === 'SAFETY') {
          yield "\n\n⚠️ *The response was filtered by safety settings.*";
        }
      }
    } catch (error: any) {
      console.error("Gemini API Error Detail:", error);

      const errorMessage = error.message || "";
      const statusCode = error.status || (error.response?.status);

      // 429: Rate Limit
      if (statusCode === 429 || errorMessage.toLowerCase().includes('rate limit') || errorMessage.toLowerCase().includes('resource_exhausted')) {
        yield "🚀 **Rate Limit Reached**: Neby needs a short break! You've reached the API rate limit. Please wait a minute and try again.";
        return;
      }

      // 401/403: Auth
      if (statusCode === 401 || statusCode === 403 || errorMessage.toLowerCase().includes('api key') || errorMessage.toLowerCase().includes('unauthorized')) {
        yield "🔐 **Authentication Error**: The API key provided is invalid or has expired. Please check your system configuration.";
        return;
      }

      // 400: Bad Request / Capability Mismatch
      if (statusCode === 400) {
        if (errorMessage.toLowerCase().includes('thinking_config')) {
          yield "🧠 **Feature Unsupported**: This model does not support Deep Thinking. Try enabling it for Gemini 3 models or disabling it in the slidebar.";
        } else if (errorMessage.toLowerCase().includes('tool') || errorMessage.toLowerCase().includes('search')) {
          yield "🌐 **Search Not Supported**: Google Search is not supported by this model. Please try another or disable search.";
        } else if (errorMessage.toLowerCase().includes('multiturn') || errorMessage.toLowerCase().includes('history')) {
          yield "🔄 **Context Error**: This model doesn't support conversation history. Try starting a 'New Chat' or switching to a more advanced model.";
        } else {
          yield "❌ **Invalid Request**: The parameters sent were rejected by the model. Try a standard model like Gemini 3 Flash with default settings.";
        }
        return;
      }

      // 500/503: Backend
      if (statusCode >= 500) {
        yield "🌪️ **Cosmic Interference**: Google's servers are experiencing temporary issues. Please wait a moment and try your request again.";
        return;
      }

      // Fallback logic for string matching
      if (errorMessage.includes('thinking_config')) {
         yield "⚠️ This model does not support Deep Thinking. Try enabling it for Gemini 3 models.";
      } else if (errorMessage.includes('search') || errorMessage.includes('tool')) {
         yield "⚠️ Google Search is not supported by this model. Please try another.";
      } else if (errorMessage.includes('Multiturn chat')) {
         yield "⚠️ Conversation history is not supported by this model. Try a Gemini 3 series model.";
      } else {
         yield "☄️ **Unexpected Error**: Something went wrong in the neural mesh. Please check your connection and try again.";
      }
    }
  }
}

