// PCM Decoding Helpers
function decodeBase64(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const ChatMessage: React.FC<ChatMessageProps> = ({ message }) => {
  const isUser = message.role === Role.USER;
  const [copied, setCopied] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isSpeechLoading, setIsSpeechLoading] = useState(false);

  const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);

  const handleCopy = () => {
    navigator.clipboard.writeText(message.content);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const stopSpeaking = () => {
    if (audioSourceRef.current) {
      try {
        audioSourceRef.current.stop();
      } catch (e) {}
      audioSourceRef.current = null;
    }
    setIsSpeaking(false);
  };

  const handleSpeak = async () => {
    if (isSpeaking) {
      stopSpeaking();
      return;
    }

    setIsSpeechLoading(true);

    try {
      // 1. Get Audio Data (cached or from API)
      let audioBase64 = message.audioBase64;
      if (!audioBase64) {
        audioBase64 = await geminiService.generateSpeech(message.content);
        // Note: In a production app, we'd update the session state to save this 
        // but for now we'll just use it in the component.
        message.audioBase64 = audioBase64; 
      }

      // 2. Setup Audio Context
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({
          sampleRate: 24000 // Gemini TTS uses 24kHz
        });
      }

      const ctx = audioContextRef.current;
      if (ctx.state === 'suspended') {
        await ctx.resume();
      }

      // 3. Decode & Play
      const bytes = decodeBase64(audioBase64);
      const audioBuffer = await decodeAudioData(bytes, ctx, 24000, 1);

      const source = ctx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(ctx.destination);

      source.onended = () => {
        setIsSpeaking(false);
        audioSourceRef.current = null;
      };

      audioSourceRef.current = source;
      source.start();
      setIsSpeaking(true);
    } catch (error) {
      console.error("Failed to play speech:", error);
    } finally {
      setIsSpeechLoading(false);
    }
  };

  return (
    <div className={`flex w-full mb-8 ${isUser ? 'justify-end' : 'justify-start'} group`}>
      <div className={`flex max-w-[90%] md:max-w-[80%] gap-4 ${isUser ? 'flex-row-reverse' : 'flex-row'}`}>

        {/* Avatar */}
        <div className="flex-shrink-0 flex flex-col items-center">
          <div className={`w-10 h-10 rounded-xl flex items-center justify-center shadow-lg overflow-hidden ${
            isUser 
              ? 'bg-gradient-to-br from-indigo-600 to-purple-600' 
              : 'bg-black/40 border border-white/10 backdrop-blur-md'
          }`}>
            {isUser ? (
              <User size={20} className="text-white/90" />
            ) : (
              <StarBoxLogo />
            )}
          </div>
        </div>

        {/* Content Bubble */}
        <div className={`flex flex-col ${isUser ? 'items-end' : 'items-start'} min-w-0`}>

          <div className={`relative px-6 py-5 shadow-lg ${
            isUser 
              ? 'bg-gradient-to-br from-indigo-600 via-indigo-600 to-purple-700 text-white rounded-2xl rounded-tr-sm' 
              : 'bg-black/30 backdrop-blur-md text-zinc-100 rounded-2xl rounded-tl-sm border border-white/10'
          }`}>

            {/* Images if any */}
            {message.images && message.images.length > 0 && (
              <div className="flex flex-wrap gap-2 mb-4">
                {message.images.map((img, idx) => (
                  <img 
                    key={idx} 
                    src={img} 
                    alt={`attachment-${idx}`} 
                    className="max-w-[200px] max-h-[200px] rounded-lg object-cover border border-white/20 shadow-sm"
                  />
                ))}
              </div>
            )}

            {/* Loading Indicator */}
            {message.isLoading ? (
              <div className="flex flex-col gap-3 py-2 px-1 min-w-[160px]">
                <div className="flex items-center gap-3">
                  <div className="relative flex items-center justify-center w-5 h-5">
                    <div className="absolute inset-0 bg-indigo-500/30 rounded-full animate-ping"></div>
                    <ThinkingLogo />
                  </div>
                  <span className="text-[10px] font-bold text-zinc-400 uppercase tracking-[0.2em] animate-pulse">
                    Neby is thinking
                  </span>
                </div>
                <div className="relative h-[2px] w-full bg-white/5 rounded-full overflow-hidden">
                  <div className="absolute inset-0 bg-gradient-to-r from-transparent via-indigo-500 to-transparent w-full animate-thinking-shimmer"></div>
                </div>
              </div>
            ) : (
              <div className="markdown-content text-[15px] leading-7 tracking-wide">
                <ReactMarkdown>{message.content}</ReactMarkdown>
              </div>
            )}

            {/* Actions Bar (only for model messages) */}
            {!isUser && !message.isLoading && (
              <div className="absolute bottom-2 right-2 flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                {/* TTS Play/Pause */}
                <button 
                  onClick={handleSpeak}
                  disabled={isSpeechLoading}
                  className={`p-1.5 rounded-md transition-all ${
                    isSpeaking 
                      ? 'bg-indigo-500/20 text-indigo-300 shadow-[0_0_8px_rgba(129,140,248,0.3)]' 
                      : 'text-zinc-500 hover:text-zinc-300 hover:bg-white/10'
                  }`}
                  title={isSpeaking ? "Stop listening" : "Listen to response"}
                >
                  {isSpeechLoading ? (
                    <Loader2 size={14} className="animate-spin text-indigo-400" />
                  ) : isSpeaking ? (
                    <Pause size={14} fill="currentColor" />
                  ) : (
                    <Volume2 size={14} />
                  )}
                </button>

                {/* Copy Button */}
                <button 
                  onClick={handleCopy}
                  className="p-1.5 text-zinc-500 hover:text-zinc-300 rounded-md hover:bg-white/10"
                  title="Copy response"
                >
                  {copied ? <Check size={14} className="text-emerald-400" /> : <Copy size={14} />}
                </button>
              </div>
            )}
          </div>

          {/* Metadata Row */}
          <div className="flex items-center gap-3 mt-2 px-1">
            <span className="text-[11px] text-zinc-500 font-medium shadow-black drop-shadow-sm">
               {isUser ? 'You' : 'Neby'} • {new Date(message.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
            </span>

            {/* Grounding Sources */}
            {message.groundingSources && message.groundingSources.length > 0 && (
              <div className="flex items-center gap-2">
                <span className="text-zinc-700">•</span>
                <div className="flex items-center gap-1 text-[11px] text-indigo-300 bg-indigo-900/20 px-2 py-0.5 rounded-full border border-indigo-500/30">
                  <Globe size={10} />
                  <span>{message.groundingSources.length} Sources</span>
                </div>
              </div>
            )}
          </div>

          {/* Sources Detail View */}
          {message.groundingSources && message.groundingSources.length > 0 && (
            <div className="mt-3 grid gap-2 w-full max-w-md">
               {message.groundingSources.map((source, idx) => (
                  source.web && (
                    <a 
                      key={idx}
                      href={source.web.uri} 
                      target="_blank" 
                      rel="noopener noreferrer"
                      className="flex items-center gap-2 p-2 rounded-lg bg-black/40 border border-white/10 hover:border-white/20 hover:bg-white/5 transition-all group/link"
                    >
                      <div className="w-6 h-6 rounded bg-white/5 flex items-center justify-center shrink-0 text-zinc-500 group-hover/link:text-zinc-300">
                        <Globe size={14} />
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="text-xs font-medium text-zinc-300 truncate group-hover/link:text-indigo-300 transition-colors">
                          {source.web.title}
                        </div>
                        <div className="text-[10px] text-zinc-500 truncate">
                          {new URL(source.web.uri).hostname}
                        </div>
                      </div>
                    </a>
                  )
                ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

