import { GoogleGenAI, Part, Modality } from "@google/genai";
import { ChatConfig, Message, Role } from '../types';

export class GeminiService {
  private getAiInstance() {
    // Always use latest API key which might have been updated via window.aistudio
    return new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }

  async generateSpeech(text: string): Promise<string> {
    const ai = this.getAiInstance();
    try {
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: `Read this message naturally: ${text}` }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: 'Kore' },
            },
          },
        },
      });

      const audioBase64 = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (!audioBase64) throw new Error("No audio data returned");
      return audioBase64;
    } catch (error) {
      console.error("Gemini TTS Error:", error);
      throw error;
    }
  }

  async generateImage(prompt: string): Promise<string[]> {
    const ai = this.getAiInstance();
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: { parts: [{ text: prompt }] },
        config: { imageConfig: { aspectRatio: "1:1" } }
      });

      const images: string[] = [];
      const parts = response.candidates?.[0]?.content?.parts || [];
      for (const part of parts) {
        if (part.inlineData) {
          images.push(`data:${part.inlineData.mimeType};base64,${part.inlineData.data}`);
        }
      }
      if (images.length === 0) throw new Error("No images generated");
      return images;
    } catch (error) {
      console.error("Gemini Image Gen Error:", error);
      throw error;
    }
  }

  async generateVideo(prompt: string, onProgress?: (msg: string) => void): Promise<string> {
    const ai = this.getAiInstance();
    try {
      onProgress?.("Initiating neural render engine...");
      let operation = await ai.models.generateVideos({
        model: 'veo-3.1-fast-generate-preview',
        prompt: prompt,
        config: {
          numberOfVideos: 1,
          resolution: '720p',
          aspectRatio: '16:9'
        }
      });

      const progressMessages = [
        "Synthesizing motion vectors...",
        "Applying cinematic lighting...",
        "Resolving temporal consistency...",
        "Finalizing cosmic frames..."
      ];
      let msgIdx = 0;

      while (!operation.done) {
        onProgress?.(progressMessages[msgIdx % progressMessages.length]);
        msgIdx++;
        await new Promise(resolve => setTimeout(resolve, 10000));
        operation = await ai.operations.getVideosOperation({ operation: operation });
      }

      const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
      if (!downloadLink) throw new Error("Video generation failed - no URI");

      const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
      const blob = await response.blob();
      return URL.createObjectURL(blob);
    } catch (error) {
      console.error("Gemini Video Gen Error:", error);
      throw error;
    }
  }

  async *streamChat(
    history: Message[], 
    newMessage: string, 
    images: string[], 
    config: ChatConfig
  ): AsyncGenerator<string | { groundingChunks: any[] }, void, unknown> {
    const ai = this.getAiInstance();

    const chatHistory = history
      .filter(msg => !msg.isLoading && msg.role !== Role.SYSTEM) 
      .map(msg => ({
        role: msg.role === Role.USER ? 'user' : 'model',
        parts: msg.images && msg.images.length > 0 
          ? [
              ...msg.images.map(img => ({ inlineData: { mimeType: 'image/jpeg', data: img.split(',')[1] } })),
              { text: msg.content }
            ]
          : [{ text: msg.content }]
      }));

    const currentParts: Part[] = [];
    if (images.length > 0) {
      images.forEach(img => {
        currentParts.push({ inlineData: { mimeType: 'image/jpeg', data: img.split(',')[1] } });
      });
    }
    currentParts.push({ text: newMessage });

    const tools: any[] = [];
    if (config.useSearch) tools.push({ googleSearch: {} });

    const isThinkingSupported = config.model.includes('gemini-3') || config.model.includes('gemini-2.5');
    const thinkingConfig = (config.useThinking && isThinkingSupported) ? { thinkingBudget: 4096 } : undefined;

    try {
      const result = await ai.models.generateContentStream({
        model: config.model,
        contents: [...chatHistory, { role: 'user', parts: currentParts }],
        config: {
          systemInstruction: config.systemInstruction,
          temperature: config.useThinking ? undefined : config.temperature,
          tools: tools.length > 0 ? tools : undefined,
          thinkingConfig: thinkingConfig,
        }
      });

      for await (const chunk of result) {
        if (chunk.text) yield chunk.text;
        const grounding = chunk.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (grounding) yield { groundingChunks: grounding };
      }
    } catch (error: any) {
      yield `☄️ **Error**: ${error.message || "Connection disruption."}`;
    }
  }
}

