          <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileSelect} />

          <textarea
            ref={textareaRef}
            value={text}
            onChange={(e) => setText(e.target.value)}
            onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }}
            placeholder="Describe an idea, image, or video..."
            className="flex-1 bg-transparent text-zinc-100 p-3 max-h-40 resize-none focus:outline-none"
            rows={1}
            disabled={isLoading}
          />

