import React, { useState, useRef, useEffect } from 'react';
import { Menu, Sparkles, AlertTriangle } from 'lucide-react';
import ChatMessage from './components/ChatMessage';
import ChatInput from './components/ChatInput';
import Sidebar from './components/Sidebar';
import AuthScreen from './components/AuthScreen';
import { Message, Role, ChatConfig, DEFAULT_CONFIG, ChatSession, User } from './types';
import { geminiService } from './services/geminiService';

const WelcomeLogo = () => {
  return (
    <div className="w-full h-full bg-gradient-to-br from-indigo-600 via-indigo-700 to-purple-800 rounded-[2.5rem] flex items-center justify-center shadow-2xl shadow-indigo-500/20 border border-white/20">
      <Sparkles size={64} className="text-white fill-white/10 animate-pulse" />
    </div>
  );
};

const App: React.FC = () => {
  // Auth State
  const [user, setUser] = useState<User | null>(null);
  const [isGuest, setIsGuest] = useState(false);
  const [authChecked, setAuthChecked] = useState(false);

  // App State
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [config, setConfig] = useState<ChatConfig>(DEFAULT_CONFIG);
  const [slidebarOpen, setSlidebarOpen] = useState(() => typeof window !== 'undefined' ? window.innerWidth >= 1024 : false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  // 1. Check for logged-in user on mount
  useEffect(() => {
    const storedUser = localStorage.getItem('neby_auth_user');
    if (storedUser) {
      setUser(JSON.parse(storedUser));
    }
    setAuthChecked(true);
  }, []);

  // 2. Load sessions whenever User changes or Guest mode activates
  useEffect(() => {
    // If not logged in and not in guest mode, don't load anything yet
    if (!user && !isGuest) {
      setSessions([]);
      setCurrentSessionId(null);
      return;
    }

    const sessionKey = user ? `neby_sessions_${user.id}` : `neby_sessions_guest`;
    const saved = localStorage.getItem(sessionKey);

    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed) && parsed.length > 0) {
          setSessions(parsed);
          setCurrentSessionId(parsed[parsed.length - 1].id);
        } else {
          createNewChat();
        }
      } catch (e) {
        createNewChat();
      }
    } else {
      createNewChat();
    }
  }, [user, isGuest]);

  // 3. Save sessions to specific user key or guest key
  useEffect(() => {
    if ((user || isGuest) && sessions.length > 0) {
      const sessionKey = user ? `neby_sessions_${user.id}` : `neby_sessions_guest`;
      localStorage.setItem(sessionKey, JSON.stringify(sessions));
    }
  }, [sessions, user, isGuest]);

  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);
    setIsGuest(false);
    localStorage.setItem('neby_auth_user', JSON.stringify(loggedInUser));
  };

  const handleGuestAccess = () => {
    setUser(null);
    setIsGuest(true);
  };

  const handleLogout = () => {
    setUser(null);
    setIsGuest(false);
    localStorage.removeItem('neby_auth_user');
    setSessions([]);
    setCurrentSessionId(null);
  };

  const currentSession = sessions.find(s => s.id === currentSessionId);
  const messages = currentSession ? currentSession.messages : [];

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const createNewChat = () => {
    const newSession = { id: Date.now().toString(), title: 'New Cosmic Chat', messages: [], createdAt: Date.now() };
    setSessions(prev => [...prev, newSession]);
    setCurrentSessionId(newSession.id);
  };

  const deleteSession = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    setSessions(prev => {
      const newSessions = prev.filter(s => s.id !== id);
      if (currentSessionId === id) {
        if (newSessions.length > 0) {
          setCurrentSessionId(newSessions[newSessions.length - 1].id);
        } else {
          setTimeout(() => createNewChat(), 0);
        }
      }
      return newSessions;
    });
  };

  const renameSession = (id: string, newTitle: string) => {
    setSessions(prev => prev.map(session => 
      session.id === id ? { ...session, title: newTitle } : session
    ));
  };

  const updateCurrentSessionMessages = (updateFn: (msgs: Message[]) => Message[]) => {
    setSessions(prev => prev.map(session => {
      if (session.id === currentSessionId) {
        const msgs = updateFn(session.messages);
        let title = session.title;
        if (session.messages.length === 0 && msgs.length > 0) {
          title = msgs[0].content.slice(0, 30);
        }
        return { ...session, messages: msgs, title };
      }
      return session;
    }));
  };

  const handleSendMessage = async (text: string, images: string[], type: 'text' | 'image' | 'video' = 'text') => {
    if (!currentSessionId) return;

    const userMsg = { id: Date.now().toString(), role: Role.USER, content: text, timestamp: Date.now(), images };
    updateCurrentSessionMessages(prev => [...prev, userMsg]);
    setIsLoading(true);

    const botMsgId = (Date.now() + 1).toString();

    try {
      if (type === 'video') {
        const aistudio = (window as any).aistudio;
        const hasKey = await aistudio.hasSelectedApiKey();
        if (!hasKey) await aistudio.openSelectKey();

        updateCurrentSessionMessages(prev => [...prev, { id: botMsgId, role: Role.MODEL, content: 'Synthesizing cosmic motion...', timestamp: Date.now(), isDirecting: true }]);
        const videoUri = await geminiService.generateVideo(text, (msg) => {
          updateCurrentSessionMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, content: msg } : m));
        });
        updateCurrentSessionMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, content: 'Cosmic render complete.', videoUri, isDirecting: false } : m));
      } else if (type === 'image' || config.model.includes('image')) {
        updateCurrentSessionMessages(prev => [...prev, { id: botMsgId, role: Role.MODEL, content: '', timestamp: Date.now(), isPainting: true }]);
        const generatedImages = await geminiService.generateImage(text);
        updateCurrentSessionMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, content: `I've visualized: "${text}"`, images: generatedImages, isPainting: false } : m));
      } else {
        updateCurrentSessionMessages(prev => [...prev, { id: botMsgId, role: Role.MODEL, content: '', timestamp: Date.now(), isLoading: true }]);
        const stream = geminiService.streamChat([...messages, userMsg], text, images, config);
        let fullContent = '';
        for await (const chunk of stream) {
          if (typeof chunk === 'string') {
            fullContent += chunk;
            updateCurrentSessionMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, content: fullContent, isLoading: false } : m));
          } else if (chunk.groundingChunks) {
            updateCurrentSessionMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, groundingSources: chunk.groundingChunks } : m));
          }
        }
      }
    } catch (error: any) {
      const isEntityNotFound = error.message?.includes("Requested entity was not found");
      updateCurrentSessionMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, content: isEntityNotFound ? "⚠️ Project not found. Please re-select your paid API key." : "☄️ Neural mesh disruption.", isLoading: false, isPainting: false, isDirecting: false } : m));
      if (isEntityNotFound) await (window as any).aistudio.openSelectKey();
    } finally {
      setIsLoading(false);
      messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  };

  if (!authChecked) return null; // or a loading spinner

  // If not logged in AND not selected guest mode, show auth screen
  if (!user && !isGuest) {
    return <AuthScreen onLogin={handleLogin} onGuest={handleGuestAccess} />;
  }

  return (
    <div className="flex h-screen bg-transparent overflow-hidden">
      <Sidebar 
        isOpen={slidebarOpen} 
        onClose={() => setSlidebarOpen(false)} 
        config={config} 
        setConfig={setConfig} 
        sessions={sessions} 
        currentSessionId={currentSessionId} 
        onSelectSession={setCurrentSessionId} 
        onDeleteSession={deleteSession} 
        onRenameSession={renameSession} 
        onNewChat={createNewChat} 
        user={user}
        onLogout={handleLogout}
      />
      <div className={`flex-1 flex flex-col transition-all duration-300 ${slidebarOpen ? 'lg:ml-80' : 'lg:ml-0'}`}>
        <header className="flex items-center p-4 border-b border-white/10 bg-black/20 backdrop-blur-md z-30">
          <button onClick={() => setSlidebarOpen(!slidebarOpen)} className="text-zinc-400 p-2"><Menu size={24} /></button>
          <span className="ml-4 font-semibold text-zinc-100 truncate">{currentSession?.title || 'Neby'}</span>
        </header>
        <main className="flex-1 overflow-y-auto p-4 md:p-6 custom-scrollbar">
          {messages.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-zinc-400 space-y-4">
              <div className="w-32 h-32 bg-white/5 backdrop-blur-xl rounded-[2.5rem] flex items-center justify-center shadow-2xl shadow-purple-900/40 border border-white/10 rotate-3 transform hover:rotate-6 transition-transform duration-500 overflow-hidden">
                <WelcomeLogo />
              </div>
              <h1 className="text-3xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-200 via-indigo-200 to-purple-200 drop-shadow-sm">
                {user ? `Welcome back, ${user.name.split(' ')[0]}` : 'Welcome to Neby'}
              </h1>
              <p className="text-center max-w-md text-sm text-zinc-400 leading-relaxed">
                Neby is ready to explore ideas, reason through problems, and create with you.
              </p>
            </div>
          ) : (
            <>
              {messages.map(m => <ChatMessage key={m.id} message={m} />)}
              <div ref={messagesEndRef} />
            </>
          )}
        </main>
        <ChatInput onSendMessage={handleSendMessage} isLoading={isLoading} />
      </div>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Settings, BrainCircuit, Globe, MessageSquare, X, Trash2, Clock, Pencil, Brain, Sparkles, LogOut, User, LogIn } from 'lucide-react';
import { ChatConfig, AVAILABLE_MODELS, ChatSession, User as UserType } from '../types';

interface SidebarProps {
  isOpen: boolean;
  onClose: () => void;
  config: ChatConfig;
  setConfig: React.Dispatch<React.SetStateAction<ChatConfig>>;
  sessions: ChatSession[];
  currentSessionId: string | null;
  onSelectSession: (id: string) => void;
  onDeleteSession: (id: string, e: React.MouseEvent) => void;
  onRenameSession: (id: string, newTitle: string) => void;
  onNewChat: () => void;
  user: UserType | null;
  onLogout: () => void;
}

const NebyLogo = () => {
  const [error, setError] = useState(false);
  if (error) return <Brain size={20} className="text-indigo-400" />;
  return (
    <img 
      src="logo.png" 
      alt="Neby Logo" 
      onError={() => setError(true)}
      className="w-8 h-8 object-contain filter drop-shadow-[0_0_5px_rgba(129,140,248,0.3)]"
    />
  );
};

export default function Sidebar({ 
  isOpen, 
  onClose, 
  config, 
  setConfig, 
  sessions, 
  currentSessionId, 
  onSelectSession, 
  onDeleteSession,
  onRenameSession,
  onNewChat,
  user,
  onLogout
}: SidebarProps) {
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editValue, setEditValue] = useState('');

  const startEditing = (e: React.MouseEvent, session: ChatSession) => {
    e.stopPropagation();
    setEditingId(session.id);
    setEditValue(session.title);
  };

  const saveEditing = () => {
    if (editingId) {
        if (editValue.trim() && editValue.trim() !== sessions.find(s => s.id === editingId)?.title) {
            onRenameSession(editingId, editValue.trim());
        }
        setEditingId(null);
        setEditValue('');
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') saveEditing();
    else if (e.key === 'Escape') {
        setEditingId(null);
        setEditValue('');
    }
  };

  return (
    <>
      {isOpen && <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-40 lg:hidden" onClick={onClose} />}
      <div className={`fixed inset-y-0 left-0 z-50 w-72 bg-black/40 backdrop-blur-xl border-r border-white/10 transform transition-transform duration-300 ease-in-out ${isOpen ? 'translate-x-0' : '-translate-x-full'} lg:w-80 flex flex-col shadow-2xl`}>

        {/* Header */}
        <div className="p-6 border-b border-white/5 flex justify-between items-center shrink-0">
          <div className="flex items-center gap-3">
            <div className="p-1 rounded-lg bg-white/5 border border-white/10 flex items-center justify-center">
               <NebyLogo />
            </div>
            <h2 className="text-xl font-bold bg-gradient-to-r from-blue-100 via-indigo-100 to-purple-100 bg-clip-text text-transparent">Neby</h2>
          </div>
          <button onClick={onClose} className="lg:hidden text-zinc-400 hover:text-white transition-colors"><X size={20} /></button>
        </div>

        {/* New Chat Button */}
        <div className="p-4 shrink-0">
            <button onClick={() => { onNewChat(); if (window.innerWidth < 1024) onClose(); }} className="group w-full flex items-center justify-center gap-2 bg-indigo-600/20 hover:bg-indigo-600/30 text-indigo-100 py-3 rounded-xl transition-all font-semibold shadow-lg shadow-indigo-900/20 active:scale-[0.98] border border-indigo-500/30 hover:border-indigo-500/50">
              <MessageSquare size={18} className="text-indigo-300 group-hover:text-indigo-200" />
              New Chat
            </button>
        </div>

        {/* Scrollable Content */}
        <div className="flex-1 overflow-y-auto min-h-0 custom-scrollbar">
          <div className="p-4 space-y-8">

            {/* Recent Chats */}
            {sessions.length > 0 && (
              <div className="space-y-3">
                <label className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest px-2 flex items-center gap-2"><Clock size={10} /> Recent</label>
                <div className="space-y-1">
                  {sessions.slice().reverse().map(session => (
                    <div key={session.id} onClick={() => { onSelectSession(session.id); if (window.innerWidth < 1024) onClose(); }} className={`group flex items-center justify-between p-2.5 rounded-lg cursor-pointer transition-all border ${currentSessionId === session.id ? 'bg-white/10 border-white/10 text-zinc-100 shadow-md' : 'text-zinc-400 hover:bg-white/5 hover:text-zinc-200 border-transparent hover:border-white/5'}`}>
                      {editingId === session.id ? (
                        <div className="flex items-center gap-2 w-full">
                             <input type="text" autoFocus value={editValue} onChange={(e) => setEditValue(e.target.value)} onBlur={saveEditing} onKeyDown={handleKeyDown} onClick={(e) => e.stopPropagation()} className="bg-black/40 text-white text-sm rounded-md px-2 py-1.5 w-full border border-indigo-500/50 outline-none focus:ring-2 focus:ring-indigo-500/30 transition-all" />
                        </div>
                      ) : (
                        <>
                          <div className="flex items-center gap-3 overflow-hidden flex-1" onDoubleClick={(e) => startEditing(e, session)} title="Double-click to rename">
                            <div className={`w-1.5 h-1.5 rounded-full shrink-0 ${currentSessionId === session.id ? 'bg-indigo-400 shadow-[0_0_8px_rgba(129,140,248,0.5)]' : 'bg-zinc-700'}`} />
                            <span className="text-sm truncate font-medium select-none">{session.title}</span>
                          </div>
                          <div className={`flex items-center opacity-0 group-hover:opacity-100 transition-opacity ${currentSessionId === session.id ? 'opacity-100' : ''}`}>
                            <button onClick={(e) => startEditing(e, session)} className="p-1.5 rounded-md hover:bg-indigo-500/20 hover:text-indigo-300 transition-colors mr-1"><Pencil size={12} /></button>
                            <button onClick={(e) => onDeleteSession(session.id, e)} className="p-1.5 rounded-md hover:bg-red-500/20 hover:text-red-400 transition-colors"><Trash2 size={12} /></button>
                          </div>
                        </>
                      )}
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Config Sections */}
            <div className="space-y-3">
              <label className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest px-2">Model</label>
              <div className="space-y-2">
                {AVAILABLE_MODELS.map((m) => (
                  <div key={m.id} onClick={() => setConfig(prev => ({ ...prev, model: m.id }))} className={`p-3 rounded-lg border cursor-pointer transition-all relative overflow-hidden group/model ${config.model === m.id ? 'bg-gradient-to-r from-indigo-900/30 to-purple-900/30 border-indigo-500/40' : 'bg-black/20 border-white/5 hover:border-white/10 hover:bg-white/5'}`}>
                    <div className="flex items-center justify-between mb-1 relative z-10">
                      <div className="flex items-center gap-2 overflow-hidden flex-1">
                        <span className={`font-medium text-sm truncate ${config.model === m.id ? 'text-indigo-300' : 'text-zinc-300'}`}>{m.name}</span>
                        <div className="flex items-center gap-1.5 shrink-0 ml-auto mr-1">
                          {m.supportsThinking && <div className="p-1 rounded-md bg-purple-500/15 text-purple-400 ring-1 ring-purple-500/20" title="Supports Deep Thinking"><BrainCircuit size={11} /></div>}
                          {m.supportsSearch && <div className="p-1 rounded-md bg-blue-500/15 text-blue-400 ring-1 ring-blue-500/20" title="Supports Google Search"><Globe size={11} /></div>}
                        </div>
                      </div>
                      {config.model === m.id && <div className="w-1.5 h-1.5 rounded-full bg-indigo-400 shadow-[0_0_8px_rgba(129,140,248,0.6)] shrink-0 ml-1" />}
                    </div>
                    <p className="text-[11px] text-zinc-500 relative z-10 line-clamp-1 group-hover/model:text-zinc-400 transition-colors">{m.description}</p>
                  </div>
                ))}
              </div>
            </div>

            <div className="space-y-3">
              <label className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest px-2">Capabilities</label>
              <div className="flex items-center justify-between p-3 rounded-lg bg-black/20 border border-white/5">
                <div className="flex items-center gap-3">
                  <div className={`p-2 rounded-md ${config.useThinking ? 'bg-purple-500/20 text-purple-300' : 'bg-white/5 text-zinc-500'}`}><BrainCircuit size={16} /></div>
                  <div><div className="text-sm font-medium text-zinc-200">Deep Thinking</div><div className="text-[10px] text-zinc-500">Reasoning capabilities</div></div>
                </div>
                <button onClick={() => setConfig(prev => ({ ...prev, useThinking: !prev.useThinking }))} className={`w-9 h-5 rounded-full transition-colors relative ${config.useThinking ? 'bg-purple-600' : 'bg-zinc-700'}`}><div className={`absolute top-1 left-1 bg-white w-3 h-3 rounded-full transition-transform ${config.useThinking ? 'translate-x-4' : 'translate-x-0'}`} /></button>
              </div>
              <div className="flex items-center justify-between p-3 rounded-lg bg-black/20 border border-white/5">
                <div className="flex items-center gap-3">
                  <div className={`p-2 rounded-md ${config.useSearch ? 'bg-blue-500/20 text-blue-300' : 'bg-white/5 text-zinc-500'}`}><Globe size={16} /></div>
                  <div><div className="text-sm font-medium text-zinc-200">Google Search</div><div className="text-[10px] text-zinc-500">Real-time web data</div></div>
                </div>
                <button onClick={() => setConfig(prev => ({ ...prev, useSearch: !prev.useSearch }))} className={`w-9 h-5 rounded-full transition-colors relative ${config.useSearch ? 'bg-blue-600' : 'bg-zinc-700'}`}><div className={`absolute top-1 left-1 bg-white w-3 h-3 rounded-full transition-transform ${config.useSearch ? 'translate-x-4' : 'translate-x-0'}`} /></button>
              </div>
            </div>

            <div className="space-y-3">
              <label className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest px-2">System Persona</label>
              <textarea value={config.systemInstruction} onChange={(e) => setConfig(prev => ({ ...prev, systemInstruction: e.target.value }))} className="w-full h-24 bg-black/20 border border-white/10 rounded-lg p-3 text-xs text-zinc-300 focus:outline-none focus:border-indigo-500/50 focus:ring-1 focus:ring-indigo-500/50 resize-none placeholder-zinc-600 transition-all backdrop-blur-sm" placeholder="How should the AI behave?" />
            </div>
          </div>
        </div>

        {/* User Footer */}
        <div className="p-4 border-t border-white/5 shrink-0 bg-black/30 backdrop-blur-md">
          {user ? (
            <div className="flex items-center gap-3 group">
              <div className="w-9 h-9 rounded-full bg-gradient-to-tr from-indigo-500 to-purple-500 p-[1px]">
                 <img src={user.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${user.name}`} alt="avatar" className="w-full h-full rounded-full bg-black/50" />
              </div>
              <div className="flex-1 min-w-0">
                <div className="text-sm font-bold text-white truncate">{user.name}</div>
                <div className="text-[10px] text-zinc-400 truncate">{user.email}</div>
              </div>
              <button 
                onClick={onLogout}
                className="p-2 text-zinc-500 hover:text-red-400 hover:bg-white/5 rounded-lg transition-colors" 
                title="Sign out"
              >
                <LogOut size={16} />
              </button>
            </div>
          ) : (
             <div className="flex items-center justify-between">
                <div className="flex items-center gap-2 text-zinc-500 text-[11px]">
                   <Settings size={12} />
                   <span>Guest Mode</span>
                </div>
                <button 
                  onClick={onLogout}
                  className="flex items-center gap-1.5 text-xs font-medium text-indigo-400 hover:text-indigo-300 transition-colors"
                >
                  <span>Sign In</span>
                  <LogIn size={12} />
                </button>
             </div>
          )}
        </div>
      </div>
    </>
  );
}

import React, { useState, useRef, useEffect } from 'react';
import { Send, Image as ImageIcon, X, Loader2, Mic, MicOff, AlertCircle, RefreshCw, Sparkles, Wand2 } from 'lucide-react';

interface ChatInputProps {
  onSendMessage: (text: string, images: string[], type: 'text' | 'image' | 'video') => void;
  isLoading: boolean;
}

const ChatInput: React.FC<ChatInputProps> = ({ onSendMessage, isLoading }) => {
  const [text, setText] = useState('');
  const [interimText, setInterimText] = useState('');
  const [images, setImages] = useState<string[]>([]);
  const [isListening, setIsListening] = useState(false);
  const [isInitializing, setIsInitializing] = useState(false);
  const [speechError, setSpeechError] = useState<string | null>(null);

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const recognitionRef = useRef<any>(null);

  // Auto-resize textarea
  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = Math.min(textareaRef.current.scrollHeight, 160) + 'px';
    }
  }, [text, interimText]);

  // Cleanup recognition on unmount
  useEffect(() => {
    return () => {
      if (recognitionRef.current) {
        try {
          recognitionRef.current.onend = null;
          recognitionRef.current.onerror = null;
          recognitionRef.current.abort();
        } catch (e) {}
      }
    };
  }, []);

  const handleSend = (type: 'text' | 'image' | 'video' = 'text') => {
    const finalMsg = (text + ' ' + interimText).trim();
    if ((!finalMsg && images.length === 0) || isLoading) return;

    onSendMessage(finalMsg, images, type);
    setText('');
    setInterimText('');
    setImages([]);
    setSpeechError(null);
    if (textareaRef.current) textareaRef.current.style.height = 'auto';

    if (isListening) {
      stopListening();
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend('text');
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onloadend = () => {
        if (typeof reader.result === 'string') {
          setImages(prev => [...prev, reader.result as string]);
        }
      };
      reader.readAsDataURL(file);
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const removeImage = (index: number) => {
    setImages(prev => prev.filter((_, i) => i !== index));
  };

  const stopListening = () => {
    setIsInitializing(false);
    if (recognitionRef.current) {
      try {
        recognitionRef.current.onend = null;
        recognitionRef.current.abort();
      } catch (e) {
        console.warn("Recognition already inactive.");
      }
      recognitionRef.current = null;
    }
    setIsListening(false);
    setInterimText('');
  };

  const toggleListening = async () => {
    if (isListening || isInitializing) {
      stopListening();
      return;
    }

    setSpeechError(null);
    setIsInitializing(true);

    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      setSpeechError("Browser not supported");
      setIsInitializing(false);
      return;
    }

    try {
      await navigator.mediaDevices.getUserMedia({ audio: true });

      if (recognitionRef.current) {
        recognitionRef.current.onend = null;
        recognitionRef.current.onerror = null;
        try { recognitionRef.current.abort(); } catch(e) {}
      }

      await new Promise(resolve => setTimeout(resolve, 150));

      const recognition = new SpeechRecognition();
      recognition.continuous = true;
      recognition.interimResults = true;
      recognition.lang = 'en-US';

      recognition.onstart = () => {
        setIsListening(true);
        setIsInitializing(false);
        setSpeechError(null);
      };

      recognition.onresult = (event: any) => {
        let finalTranscript = '';
        let interimTranscript = '';

        for (let i = event.resultIndex; i < event.results.length; ++i) {
          const transcript = event.results[i][0].transcript;
          if (event.results[i].isFinal) {
            finalTranscript += transcript;
          } else {
            interimTranscript += transcript;
          }
        }

        if (finalTranscript) {
          setText(prev => {
            const prefix = prev && !prev.endsWith(' ') ? ' ' : '';
            return prev + prefix + finalTranscript.trim();
          });
        }
        setInterimText(interimTranscript);
      };

      recognition.onerror = (event: any) => {
        console.error("Speech recognition error:", event.error);

        if (event.error === 'no-speech') {
          setIsInitializing(false);
          return;
        }

        setIsListening(false);
        setIsInitializing(false);
        setInterimText('');

        if (recognitionRef.current) {
          try { recognitionRef.current.abort(); } catch(e) {}
          recognitionRef.current = null;
        }

        if (event.error === 'network') {
          setSpeechError("Speech service unavailable");
        } else if (event.error === 'not-allowed') {
          setSpeechError("Mic access blocked");
        } else {
          setSpeechError(`Retry speech input`);
        }
      };

      recognition.onend = () => {
        if (recognitionRef.current === recognition) {
          setIsListening(false);
          setIsInitializing(false);
          setInterimText('');
          recognitionRef.current = null;
        }
      };

      recognitionRef.current = recognition;
      recognition.start();

    } catch (err: any) {
      console.error("Failed to initialize speech:", err);
      setIsInitializing(false);
      if (err.name === 'NotAllowedError') {
        setSpeechError("Mic access denied");
      } else {
        setSpeechError("System Error: Try again");
      }
    }
  };

  const currentInputValue = isListening 
    ? text + (interimText ? (text ? ' ' : '') + interimText : '') 
    : text;

  const placeholderText = isLoading 
    ? "Processing..." 
    : isInitializing
      ? "Initializing..."
      : speechError 
        ? speechError 
        : isListening 
          ? "Listening..." 
          : "Ask Neby or describe an image...";

  return (
    <div className="w-full max-w-4xl mx-auto p-4">
      {/* Image Preview Area */}
      {images.length > 0 && (
        <div className="flex gap-3 mb-3 overflow-x-auto pb-2 custom-scrollbar">
          {images.map((img, idx) => (
            <div key={idx} className="relative group flex-shrink-0">
              <img 
                src={img} 
                alt="Preview" 
                className="w-20 h-20 object-cover rounded-lg border border-white/20 shadow-xl"
              />
              <button
                onClick={() => removeImage(idx)}
                className="absolute -top-2 -right-2 bg-black/80 text-zinc-400 hover:text-red-400 rounded-full p-1 shadow-lg border border-white/10 opacity-0 group-hover:opacity-100 transition-opacity"
              >
                <X size={12} />
              </button>
            </div>
          ))}
        </div>
      )}

      <div className={`relative flex flex-col bg-black/40 border rounded-2xl shadow-2xl backdrop-blur-xl transition-all duration-300 overflow-hidden ${
        speechError 
          ? 'border-red-500/40 ring-2 ring-red-500/5' 
          : 'border-white/10 focus-within:ring-2 focus-within:ring-indigo-500/40 focus-within:border-indigo-500/40'
      }`}>

        <div className="flex items-end px-1">
          {/* Attachment Button */}
          <button
            onClick={() => fileInputRef.current?.click()}
            className="p-3 text-zinc-400 hover:text-indigo-300 transition-colors mb-[2px]"
            title="Attach Image"
            disabled={isLoading}
          >
            <ImageIcon size={20} />
          </button>
          <input 
            type="file" 
            ref={fileInputRef} 
            className="hidden" 
            accept="image/*"
            onChange={handleFileSelect}
          />

          {/* Microphone Button */}
          <button
            onClick={toggleListening}
            className={`p-3 transition-all mb-[2px] ${
              isListening || isInitializing
                ? 'text-red-500 hover:text-red-400 scale-110' 
                : speechError 
                  ? 'text-red-400 hover:text-red-300' 
                  : 'text-zinc-400 hover:text-zinc-200'
            }`}
            title={isListening ? "Stop Recording" : "Start Voice Input"}
            disabled={isLoading}
          >
            {isInitializing ? (
              <RefreshCw size={20} className="animate-spin opacity-50" />
            ) : isListening ? (
              <div className="relative">
                <MicOff size={20} />
                <span className="absolute -top-1 -right-1 w-2 h-2 bg-red-500 rounded-full animate-ping"></span>
              </div>
            ) : speechError ? (
              <AlertCircle size={20} className="text-red-500" />
            ) : (
              <Mic size={20} />
            )}
          </button>

          {/* Text Input */}
          <div className="flex-1 relative">
            <textarea
              ref={textareaRef}
              value={currentInputValue}
              onChange={(e) => {
                if (!isListening && !isInitializing) {
                  setText(e.target.value);
                  if (speechError) setSpeechError(null);
                }
              }}
              onKeyDown={handleKeyDown}
              placeholder={placeholderText}
              className={`w-full bg-transparent text-zinc-100 placeholder-zinc-500 p-3 max-h-40 resize-none focus:outline-none custom-scrollbar transition-opacity ${
                isListening || isInitializing ? 'cursor-default opacity-80' : ''
              } ${speechError ? 'placeholder-red-400 font-medium' : ''}`}
              rows={1}
              disabled={isLoading}
              readOnly={isListening || isInitializing}
            />
          </div>

          <div className="flex items-center gap-1 mb-[5px] mr-1.5">
            {/* Imagine Button */}
            <button
              onClick={() => handleSend('image')}
              disabled={(!text.trim() && !interimText.trim()) || isLoading}
              className={`p-2 rounded-xl transition-all ${
                (!text.trim() && !interimText.trim()) || isLoading
                  ? 'text-zinc-600 cursor-not-allowed'
                  : 'bg-purple-600/20 text-purple-400 hover:bg-purple-600 hover:text-white shadow-lg shadow-purple-900/20'
              }`}
              title="Generate Image"
            >
              <Wand2 size={18} />
            </button>

            {/* Send Button */}
            <button
              onClick={() => handleSend('text')}
              disabled={(!text.trim() && !interimText.trim() && images.length === 0) || isLoading}
              className={`p-2 rounded-xl transition-all ${
                (!text.trim() && !interimText.trim() && images.length === 0) || isLoading
                  ? 'bg-white/5 text-zinc-600 cursor-not-allowed'
                  : 'bg-indigo-600 text-white hover:bg-indigo-500 shadow-lg shadow-indigo-900/30'
              }`}
              title="Send Message"
            >
              {isLoading ? <Loader2 size={18} className="animate-spin" /> : <Send size={18} />}
            </button>
          </div>
        </div>

        {/* Listening Indicator Bar */}
        {(isListening || isInitializing) && (
          <div className="h-0.5 bg-zinc-800 w-full overflow-hidden">
            <div className={`h-full bg-gradient-to-r from-indigo-500 via-purple-500 to-indigo-500 w-full ${isInitializing ? 'opacity-30' : 'animate-[shimmer_1s_infinite]'} bg-[length:200%_100%]`}></div>
          </div>
        )}
      </div>

      <div className="text-center mt-2 text-[10px] uppercase tracking-[0.25em] text-zinc-700 font-bold select-none">
        Powered by Gemini API • Cosmic Neural Mesh
      </div>

      <style>{`
        @keyframes shimmer {
          0% { background-position: 100% 0; }
          100% { background-position: -100% 0; }
        }
      `}</style>
    </div>
  );
};

export default ChatInput;

import React, { useState, useRef, useEffect } from 'react';
import { Menu, Sparkles, AlertTriangle } from 'lucide-react';
import ChatMessage from './components/ChatMessage';
import ChatInput from './components/ChatInput';
import Sidebar from './components/Sidebar';
import AuthScreen from './components/AuthScreen';
import { Message, Role, ChatConfig, DEFAULT_CONFIG, ChatSession, User } from './types';
import { geminiService } from './services/geminiService';

const WelcomeLogo = () => {
  return (
    <div className="w-full h-full bg-gradient-to-br from-indigo-600 via-indigo-700 to-purple-800 rounded-[2.5rem] flex items-center justify-center shadow-2xl shadow-indigo-500/20 border border-white/20">
      <Sparkles size={64} className="text-white fill-white/10 animate-pulse" />
    </div>
  );
};

const App: React.FC = () => {
  // Auth State
  const [user, setUser] = useState<User | null>(null);
  const [isGuest, setIsGuest] = useState(false);
  const [authChecked, setAuthChecked] = useState(false);

  // App State
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [config, setConfig] = useState<ChatConfig>(DEFAULT_CONFIG);
  const [slidebarOpen, setSlidebarOpen] = useState(() => typeof window !== 'undefined' ? window.innerWidth >= 1024 : false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  // 1. Check for logged-in user on mount
  useEffect(() => {
    const storedUser = localStorage.getItem('neby_auth_user');
    if (storedUser) {
      setUser(JSON.parse(storedUser));
      setIsGuest(false);
    } else {
      // Default to Guest mode if no user is found to allow immediate access
      setIsGuest(true);
    }
    setAuthChecked(true);
  }, []);

  // 2. Load sessions whenever User changes or Guest mode activates
  useEffect(() => {
    // If not logged in and not in guest mode, don't load anything yet
    if (!user && !isGuest) {
      setSessions([]);
      setCurrentSessionId(null);
      return;
    }

    const sessionKey = user ? `neby_sessions_${user.id}` : `neby_sessions_guest`;
    const saved = localStorage.getItem(sessionKey);

    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed) && parsed.length > 0) {
          setSessions(parsed);
          setCurrentSessionId(parsed[parsed.length - 1].id);
        } else {
          createNewChat();
        }
      } catch (e) {
        createNewChat();
      }
    } else {
      createNewChat();
    }
  }, [user, isGuest]);

  // 3. Save sessions to specific user key or guest key
  useEffect(() => {
    if ((user || isGuest) && sessions.length > 0) {
      const sessionKey = user ? `neby_sessions_${user.id}` : `neby_sessions_guest`;
      localStorage.setItem(sessionKey, JSON.stringify(sessions));
    }
  }, [sessions, user, isGuest]);

  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);
    setIsGuest(false);
    localStorage.setItem('neby_auth_user', JSON.stringify(loggedInUser));
  };

  const handleGuestAccess = () => {
    setUser(null);
    setIsGuest(true);
  };

  const handleLogout = () => {
    setUser(null);
    setIsGuest(false);
    localStorage.removeItem('neby_auth_user');
    setSessions([]);
    setCurrentSessionId(null);
  };

  const currentSession = sessions.find(s => s.id === currentSessionId);
  const messages = currentSession ? currentSession.messages : [];

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const createNewChat = () => {
    const newSession = { id: Date.now().toString(), title: 'New Cosmic Chat', messages: [], createdAt: Date.now() };
    setSessions(prev => [...prev, newSession]);
    setCurrentSessionId(newSession.id);
  };

  const deleteSession = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    setSessions(prev => {
      const newSessions = prev.filter(s => s.id !== id);
      if (currentSessionId === id) {
        if (newSessions.length > 0) {
          setCurrentSessionId(newSessions[newSessions.length - 1].id);
        } else {
          setTimeout(() => createNewChat(), 0);
        }
      }
      return newSessions;
    });
  };

  const renameSession = (id: string, newTitle: string) => {
    setSessions(prev => prev.map(session => 
      session.id === id ? { ...session, title: newTitle } : session
    ));
  };

  const updateCurrentSessionMessages = (updateFn: (msgs: Message[]) => Message[]) => {
    setSessions(prev => prev.map(session => {
      if (session.id === currentSessionId) {
        const msgs = updateFn(session.messages);
        let title = session.title;
        if (session.messages.length === 0 && msgs.length > 0) {
          title = msgs[0].content.slice(0, 30);
        }
        return { ...session, messages: msgs, title };
      }
      return session;
    }));
  };

  const handleSendMessage = async (text: string, images: string[], type: 'text' | 'image' | 'video' = 'text') => {
    if (!currentSessionId) return;

    const userMsg = { id: Date.now().toString(), role: Role.USER, content: text, timestamp: Date.now(), images };
    updateCurrentSessionMessages(prev => [...prev, userMsg]);
    setIsLoading(true);

    const botMsgId = (Date.now() + 1).toString();

    try {
      if (type === 'video') {
        const aistudio = (window as any).aistudio;
        const hasKey = await aistudio.hasSelectedApiKey();
        if (!hasKey) await aistudio.openSelectKey();

        updateCurrentSessionMessages(prev => [...prev, { id: botMsgId, role: Role.MODEL, content: 'Synthesizing cosmic motion...', timestamp: Date.now(), isDirecting: true }]);
        const videoUri = await geminiService.generateVideo(text, (msg) => {
          updateCurrentSessionMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, content: msg } : m));
        });
        updateCurrentSessionMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, content: 'Cosmic render complete.', videoUri, isDirecting: false } : m));
      } else if (type === 'image' || config.model.includes('image')) {
        updateCurrentSessionMessages(prev => [...prev, { id: botMsgId, role: Role.MODEL, content: '', timestamp: Date.now(), isPainting: true }]);
        const generatedImages = await geminiService.generateImage(text);
        updateCurrentSessionMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, content: `I've visualized: "${text}"`, images: generatedImages, isPainting: false } : m));
      } else {
        updateCurrentSessionMessages(prev => [...prev, { id: botMsgId, role: Role.MODEL, content: '', timestamp: Date.now(), isLoading: true }]);
        const stream = geminiService.streamChat([...messages, userMsg], text, images, config);
        let fullContent = '';
        for await (const chunk of stream) {
          if (typeof chunk === 'string') {
            fullContent += chunk;
            updateCurrentSessionMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, content: fullContent, isLoading: false } : m));
          } else if (chunk.groundingChunks) {
            updateCurrentSessionMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, groundingSources: chunk.groundingChunks } : m));
          }
        }
      }
    } catch (error: any) {
      const isEntityNotFound = error.message?.includes("Requested entity was not found");
      updateCurrentSessionMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, content: isEntityNotFound ? "⚠️ Project not found. Please re-select your paid API key." : "☄️ Neural mesh disruption.", isLoading: false, isPainting: false, isDirecting: false } : m));
      if (isEntityNotFound) await (window as any).aistudio.openSelectKey();
    } finally {
      setIsLoading(false);
      messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  };

  if (!authChecked) return null; // or a loading spinner

  // If not logged in AND not selected guest mode, show auth screen
  if (!user && !isGuest) {
    return <AuthScreen onLogin={handleLogin} onGuest={handleGuestAccess} />;
  }

  return (
    <div className="flex h-screen bg-transparent overflow-hidden">
      <Sidebar 
        isOpen={slidebarOpen} 
        onClose={() => setSlidebarOpen(false)} 
        config={config} 
        setConfig={setConfig} 
        sessions={sessions} 
        currentSessionId={currentSessionId} 
        onSelectSession={setCurrentSessionId} 
        onDeleteSession={deleteSession} 
        onRenameSession={renameSession} 
        onNewChat={createNewChat} 
        user={user}
        onLogout={handleLogout}
      />
      <div className={`flex-1 flex flex-col transition-all duration-300 ${slidebarOpen ? 'lg:ml-80' : 'lg:ml-0'}`}>
        <header className="flex items-center p-4 border-b border-white/10 bg-black/20 backdrop-blur-md z-30">
          <button onClick={() => setSlidebarOpen(!slidebarOpen)} className="text-zinc-400 p-2"><Menu size={24} /></button>
          <span className="ml-4 font-semibold text-zinc-100 truncate">{currentSession?.title || 'Neby'}</span>
        </header>
        <main className="flex-1 overflow-y-auto p-4 md:p-6 custom-scrollbar">
          {messages.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-zinc-400 space-y-4">
              <div className="w-32 h-32 bg-white/5 backdrop-blur-xl rounded-[2.5rem] flex items-center justify-center shadow-2xl shadow-purple-900/40 border border-white/10 rotate-3 transform hover:rotate-6 transition-transform duration-500 overflow-hidden">
                <WelcomeLogo />
              </div>
              <h1 className="text-3xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-200 via-indigo-200 to-purple-200 drop-shadow-sm">
                {user ? `Welcome back, ${user.name.split(' ')[0]}` : 'Welcome to Neby'}
              </h1>
              <p className="text-center max-w-md text-sm text-zinc-400 leading-relaxed">
                Neby is ready to explore ideas, reason through problems, and create with you.
              </p>
            </div>
          ) : (
            <>
              {messages.map(m => <ChatMessage key={m.id} message={m} />)}
              <div ref={messagesEndRef} />
            </>
          )}
        </main>
        <ChatInput onSendMessage={handleSendMessage} isLoading={isLoading} />
      </div>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Mail, Lock, User as UserIcon, ArrowRight, Sparkles, AlertCircle, Loader2, UserCircle2, Eye, EyeOff } from 'lucide-react';
import { User } from '../types';

interface AuthScreenProps {
  onLogin: (user: User) => void;
  onGuest: () => void;
}

export default function AuthScreen({ onLogin, onGuest }: AuthScreenProps) {
  const [isLogin, setIsLogin] = useState(true);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [showPassword, setShowPassword] = useState(false);

  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: ''
  });

  const GoogleLogo = () => (
    <svg className="w-5 h-5" viewBox="0 0 24 24">
      <path
        d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"
        fill="#4285F4"
      />
      <path
        d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"
        fill="#34A853"
      />
      <path
        d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"
        fill="#FBBC05"
      />
      <path
        d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"
        fill="#EA4335"
      />
    </svg>
  );

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setLoading(true);

    // Simulate network delay
    await new Promise(resolve => setTimeout(resolve, 800));

    try {
      const usersStr = localStorage.getItem('neby_users');
      const users: any[] = usersStr ? JSON.parse(usersStr) : [];

      if (isLogin) {
        // Login Logic
        const user = users.find(u => u.email === formData.email && u.password === formData.password);
        if (user) {
          const { password, ...safeUser } = user;
          onLogin(safeUser);
        } else {
          setError("Invalid email or password.");
        }
      } else {
        // Signup Logic
        if (!formData.name || !formData.email || !formData.password) {
          setError("Please fill in all fields.");
          setLoading(false);
          return;
        }

        if (users.find(u => u.email === formData.email)) {
          setError("Email already exists.");
        } else {
          const newUser = {
            id: Date.now().toString(),
            name: formData.name,
            email: formData.email,
            password: formData.password, // In a real app, hash this!
            avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${formData.name}`
          };
          users.push(newUser);
          localStorage.setItem('neby_users', JSON.stringify(users));

          const { password, ...safeUser } = newUser;
          onLogin(safeUser);
        }
      }
    } catch (err) {
      setError("Something went wrong. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const handleGoogleLogin = async () => {
    setLoading(true);
    await new Promise(resolve => setTimeout(resolve, 1000)); // Simulate popup

    // Create or login a mock Google user
    const googleUser = {
      id: 'google_user_123',
      name: 'Cosmic Traveler',
      email: 'traveler@galaxy.com',
      avatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Cosmic'
    };

    onLogin(googleUser);
    setLoading(false);
  };

  return (
    <div className="min-h-screen flex items-center justify-center p-4 relative overflow-hidden">
      {/* Background Elements are inherited from index.html body styles, but we add some overlay */}
      <div className="absolute inset-0 bg-black/20 backdrop-blur-[2px]" />

      <div className="w-full max-w-md relative z-10">
        <div className="bg-black/40 backdrop-blur-xl border border-white/10 rounded-3xl p-8 shadow-2xl overflow-hidden">

          {/* Header */}
          <div className="flex flex-col items-center mb-8">
            <div className="w-16 h-16 bg-gradient-to-br from-indigo-600 via-indigo-700 to-purple-800 rounded-2xl flex items-center justify-center shadow-lg border border-white/20 mb-4 transform rotate-3">
              <Sparkles size={32} className="text-white fill-white/10" />
            </div>
            <h1 className="text-2xl font-bold text-white mb-1">Welcome to Neby</h1>
            <p className="text-zinc-400 text-sm">Your intelligent cosmic companion</p>
          </div>

          {/* Form */}
          <form onSubmit={handleSubmit} className="space-y-4">
            {!isLogin && (
              <div className="space-y-1">
                <label className="text-xs font-bold text-zinc-500 uppercase tracking-wider ml-1">Name</label>
                <div className="relative">
                  <UserIcon size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-500" />
                  <input
                    type="text"
                    value={formData.name}
                    onChange={e => setFormData({...formData, name: e.target.value})}
                    placeholder="Enter your name"
                    className="w-full bg-black/20 border border-white/10 rounded-xl py-3 pl-10 pr-4 text-sm text-white placeholder-zinc-600 focus:outline-none focus:border-indigo-500/50 focus:ring-1 focus:ring-indigo-500/50 transition-all"
                  />
                </div>
              </div>
            )}

            <div className="space-y-1">
              <label className="text-xs font-bold text-zinc-500 uppercase tracking-wider ml-1">Email</label>
              <div className="relative">
                <Mail size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-500" />
                <input
                  type="email"
                  value={formData.email}
                  onChange={e => setFormData({...formData, email: e.target.value})}
                  placeholder="name@example.com"
                  className="w-full bg-black/20 border border-white/10 rounded-xl py-3 pl-10 pr-4 text-sm text-white placeholder-zinc-600 focus:outline-none focus:border-indigo-500/50 focus:ring-1 focus:ring-indigo-500/50 transition-all"
                />
              </div>
            </div>

            <div className="space-y-1">
              <label className="text-xs font-bold text-zinc-500 uppercase tracking-wider ml-1">Password</label>
              <div className="relative">
                <Lock size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-500" />
                <input
                  type={showPassword ? "text" : "password"}
                  value={formData.password}
                  onChange={e => setFormData({...formData, password: e.target.value})}
                  placeholder="••••••••"
                  className="w-full bg-black/20 border border-white/10 rounded-xl py-3 pl-10 pr-12 text-sm text-white placeholder-zinc-600 focus:outline-none focus:border-indigo-500/50 focus:ring-1 focus:ring-indigo-500/50 transition-all"
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-zinc-500 hover:text-zinc-300 focus:outline-none p-1"
                >
                  {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>
            </div>

            {error && (
              <div className="flex items-center gap-2 text-red-400 text-xs bg-red-500/10 p-3 rounded-lg border border-red-500/20">
                <AlertCircle size={14} />
                {error}
              </div>
            )}

            <button
              type="submit"
              disabled={loading}
              className="w-full bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-500 hover:to-purple-500 text-white font-semibold py-3.5 rounded-xl shadow-lg shadow-indigo-500/20 transition-all flex items-center justify-center gap-2 group mt-2"
            >
              {loading ? (
                <Loader2 size={18} className="animate-spin" />
              ) : (
                <>
                  {isLogin ? 'Sign In' : 'Create Account'}
                  <ArrowRight size={18} className="group-hover:translate-x-1 transition-transform" />
                </>
              )}
            </button>
          </form>

          {/* Divider */}
          <div className="relative my-6">
            <div className="absolute inset-0 flex items-center"><div className="w-full border-t border-white/10"></div></div>
            <div className="relative flex justify-center text-xs uppercase"><span className="bg-[#0f1016] px-2 text-zinc-500">Or continue with</span></div>
          </div>

          <div className="space-y-3">
            {/* Social Login */}
            <button 
              type="button"
              onClick={handleGoogleLogin}
              disabled={loading}
              className="w-full bg-white text-zinc-900 font-medium py-3 rounded-xl hover:bg-zinc-100 transition-colors flex items-center justify-center gap-2 shadow-lg"
            >
              <GoogleLogo />
              <span>Google Account</span>
            </button>

            {/* Guest Login */}
            <button 
              type="button"
              onClick={onGuest}
              disabled={loading}
              className="w-full bg-white/5 border border-white/10 text-zinc-300 font-medium py-3 rounded-xl hover:bg-white/10 hover:text-white transition-all flex items-center justify-center gap-2"
            >
              <UserCircle2 size={18} />
              <span>Continue as Guest</span>
            </button>
          </div>

          {/* Footer Toggle */}
          <div className="mt-8 text-center text-sm text-zinc-400">
            {isLogin ? "Don't have an account?" : "Already have an account?"}{" "}
            <button 
              onClick={() => { setIsLogin(!isLogin); setError(null); }}
              className="text-indigo-400 hover:text-indigo-300 font-medium hover:underline transition-all"
            >
              {isLogin ? "Sign up" : "Log in"}
            </button>
          </div>

        </div>
      </div>
    </div>
  );
}

import { initializeApp, FirebaseApp } from 'firebase/app';
import { 
  getAuth, 
  signInWithPopup, 
  GoogleAuthProvider,
  signInWithEmailAndPassword,
  createUserWithEmailAndPassword,
  signInAnonymously,
  signOut,
  updateProfile,
  Auth
} from 'firebase/auth';
import { 
  getFirestore, 
  collection, 
  doc, 
  setDoc, 
  deleteDoc, 
  onSnapshot,
  query,
  orderBy,
  Firestore
} from 'firebase/firestore';
import { ChatSession, User } from '../types';

// Configuration - User must provide these in environment variables
const firebaseConfig = {
  apiKey: process.env.FIREBASE_API_KEY,
  authDomain: process.env.FIREBASE_AUTH_DOMAIN,
  projectId: process.env.FIREBASE_PROJECT_ID,
  storageBucket: process.env.FIREBASE_STORAGE_BUCKET,
  messagingSenderId: process.env.FIREBASE_MESSAGING_SENDER_ID,
  appId: process.env.FIREBASE_APP_ID
};

let app: FirebaseApp | undefined;
let auth: Auth | undefined;
let db: Firestore | undefined;

try {
  // Only initialize if keys are present to prevent immediate crashes in empty envs
  if (firebaseConfig.apiKey) {
    app = initializeApp(firebaseConfig);
    auth = getAuth(app);
    db = getFirestore(app);
  } else {
    console.warn("Firebase config missing. Auth and DB features will be disabled.");
  }
} catch (e) {
  console.error("Firebase Initialization Error:", e);
}

export const firebaseService = {
  auth,
  db,

  // --- Auth Methods ---

  async loginGoogle() {
    if (!auth) throw new Error("Firebase not configured");
    const provider = new GoogleAuthProvider();
    const result = await signInWithPopup(auth, provider);
    await this.saveUser(result.user);
    return result.user;
  },

  async loginEmail(email: string, pass: string) {
    if (!auth) throw new Error("Firebase not configured");
    const result = await signInWithEmailAndPassword(auth, email, pass);
    await this.saveUser(result.user);
    return result.user;
  },

  async registerEmail(email: string, pass: string, name: string) {
    if (!auth) throw new Error("Firebase not configured");
    const result = await createUserWithEmailAndPassword(auth, email, pass);
    await updateProfile(result.user, { displayName: name });
    await this.saveUser({ ...result.user, displayName: name });
    return result.user;
  },

  async loginGuest() {
    if (!auth) throw new Error("Firebase not configured");
    const result = await signInAnonymously(auth);
    return result.user;
  },

  async logout() {
    if (!auth) return;
    await signOut(auth);
  },

  // --- Database Methods ---

  async saveUser(firebaseUser: any) {
    if (!db) return;
    const userRef = doc(db, 'users', firebaseUser.uid);
    await setDoc(userRef, {
      uid: firebaseUser.uid,
      email: firebaseUser.email,
      name: firebaseUser.displayName || 'Anonymous',
      avatar: firebaseUser.photoURL || `https://api.dicebear.com/7.x/avataaars/svg?seed=${firebaseUser.uid}`,
      lastLogin: new Date().toISOString()
    }, { merge: true });
  },

  // Real-time listener for sessions
  subscribeToSessions(userId: string, callback: (sessions: ChatSession[]) => void) {
    if (!db) return () => {};

    const chatsRef = collection(db, 'users', userId, 'chats');
    const q = query(chatsRef, orderBy('createdAt', 'asc'));

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const sessions: ChatSession[] = [];
      snapshot.forEach((doc) => {
        sessions.push(doc.data() as ChatSession);
      });
      callback(sessions);
    });

    return unsubscribe;
  },

  async saveSession(userId: string, session: ChatSession) {
    if (!db) return;
    const sessionRef = doc(db, 'users', userId, 'chats', session.id);
    await setDoc(sessionRef, session, { merge: true });
  },

  async deleteSession(userId: string, sessionId: string) {
    if (!db) return;
    const sessionRef = doc(db, 'users', userId, 'chats', sessionId);
    await deleteDoc(sessionRef);
  }
};

import React, { useState } from 'react';
import { Mail, Lock, User as UserIcon, ArrowRight, Sparkles, AlertCircle, Loader2, UserCircle2, Eye, EyeOff } from 'lucide-react';
import { User } from '../types';
import { firebaseService } from '../services/firebase';

interface AuthScreenProps {
  onLogin: (user: User) => void;
  onGuest: () => void;
}

export default function AuthScreen({ onLogin, onGuest }: AuthScreenProps) {
  const [isLogin, setIsLogin] = useState(true);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [showPassword, setShowPassword] = useState(false);

  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: ''
  });

  const GoogleLogo = () => (
    <svg className="w-5 h-5" viewBox="0 0 24 24">
      <path
        d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"
        fill="#4285F4"
      />
      <path
        d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"
        fill="#34A853"
      />
      <path
        d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"
        fill="#FBBC05"
      />
      <path
        d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"
        fill="#EA4335"
      />
    </svg>
  );

  const mapFirebaseUser = (fbUser: any): User => ({
    id: fbUser.uid,
    name: fbUser.displayName || 'User',
    email: fbUser.email || '',
    avatar: fbUser.photoURL || `https://api.dicebear.com/7.x/avataaars/svg?seed=${fbUser.uid}`
  });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setLoading(true);

    try {
      if (isLogin) {
        const fbUser = await firebaseService.loginEmail(formData.email, formData.password);
        onLogin(mapFirebaseUser(fbUser));
      } else {
        if (!formData.name) throw new Error("Name is required");
        const fbUser = await firebaseService.registerEmail(formData.email, formData.password, formData.name);
        onLogin(mapFirebaseUser(fbUser));
      }
    } catch (err: any) {
      console.error(err);
      if (err.message.includes("not configured")) {
        setError("Missing Firebase Config! Please check README.");
      } else if (err.code === 'auth/invalid-credential') {
        setError("Invalid email or password.");
      } else if (err.code === 'auth/email-already-in-use') {
        setError("Email already in use.");
      } else {
        setError(err.message || "Authentication failed.");
      }
    } finally {
      setLoading(false);
    }
  };

  const handleGoogleLogin = async () => {
    setLoading(true);
    setError(null);
    try {
      const fbUser = await firebaseService.loginGoogle();
      onLogin(mapFirebaseUser(fbUser));
    } catch (err: any) {
      console.error(err);
      if (err.message.includes("not configured")) {
        setError("Missing Firebase Config! Please check README.");
      } else {
        setError("Google Sign-in failed. Popup closed or not authorized.");
      }
    } finally {
      setLoading(false);
    }
  };

  const handleGuest = async () => {
    setLoading(true);
    try {
      const fbUser = await firebaseService.loginGuest();
      // We still treat guest as 'onLogin' for Firebase, but map it differently in App
      onGuest(); 
    } catch (err: any) {
      setError("Guest login failed.");
      // Fallback for demo if no firebase keys
      if (err.message.includes("not configured")) {
        onGuest();
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center p-4 relative overflow-hidden">
      <div className="absolute inset-0 bg-black/20 backdrop-blur-[2px]" />

      <div className="w-full max-w-md relative z-10">
        <div className="bg-black/40 backdrop-blur-xl border border-white/10 rounded-3xl p-8 shadow-2xl overflow-hidden">

          <div className="flex flex-col items-center mb-8">
            <div className="w-16 h-16 bg-gradient-to-br from-indigo-600 via-indigo-700 to-purple-800 rounded-2xl flex items-center justify-center shadow-lg border border-white/20 mb-4 transform rotate-3">
              <Sparkles size={32} className="text-white fill-white/10" />
            </div>
            <h1 className="text-2xl font-bold text-white mb-1">Welcome to Neby</h1>
            <p className="text-zinc-400 text-sm">Your intelligent cosmic companion</p>
          </div>

          <form onSubmit={handleSubmit} className="space-y-4">
            {!isLogin && (
              <div className="space-y-1">
                <label className="text-xs font-bold text-zinc-500 uppercase tracking-wider ml-1">Name</label>
                <div className="relative">
                  <UserIcon size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-500" />
                  <input
                    type="text"
                    value={formData.name}
                    onChange={e => setFormData({...formData, name: e.target.value})}
                    placeholder="Enter your name"
                    className="w-full bg-black/20 border border-white/10 rounded-xl py-3 pl-10 pr-4 text-sm text-white placeholder-zinc-600 focus:outline-none focus:border-indigo-500/50 focus:ring-1 focus:ring-indigo-500/50 transition-all"
                  />
                </div>
              </div>
            )}

            <div className="space-y-1">
              <label className="text-xs font-bold text-zinc-500 uppercase tracking-wider ml-1">Email</label>
              <div className="relative">
                <Mail size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-500" />
                <input
                  type="email"
                  value={formData.email}
                  onChange={e => setFormData({...formData, email: e.target.value})}
                  placeholder="name@example.com"
                  className="w-full bg-black/20 border border-white/10 rounded-xl py-3 pl-10 pr-4 text-sm text-white placeholder-zinc-600 focus:outline-none focus:border-indigo-500/50 focus:ring-1 focus:ring-indigo-500/50 transition-all"
                />
              </div>
            </div>

            <div className="space-y-1">
              <label className="text-xs font-bold text-zinc-500 uppercase tracking-wider ml-1">Password</label>
              <div className="relative">
                <Lock size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-500" />
                <input
                  type={showPassword ? "text" : "password"}
                  value={formData.password}
                  onChange={e => setFormData({...formData, password: e.target.value})}
                  placeholder="••••••••"
                  className="w-full bg-black/20 border border-white/10 rounded-xl py-3 pl-10 pr-12 text-sm text-white placeholder-zinc-600 focus:outline-none focus:border-indigo-500/50 focus:ring-1 focus:ring-indigo-500/50 transition-all"
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-zinc-500 hover:text-zinc-300 focus:outline-none p-1"
                >
                  {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>
            </div>

            {error && (
              <div className="flex items-center gap-2 text-red-400 text-xs bg-red-500/10 p-3 rounded-lg border border-red-500/20">
                <AlertCircle size={14} />
                {error}
              </div>
            )}

            <button
              type="submit"
              disabled={loading}
              className="w-full bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-500 hover:to-purple-500 text-white font-semibold py-3.5 rounded-xl shadow-lg shadow-indigo-500/20 transition-all flex items-center justify-center gap-2 group mt-2"
            >
              {loading ? (
                <Loader2 size={18} className="animate-spin" />
              ) : (
                <>
                  {isLogin ? 'Sign In' : 'Create Account'}
                  <ArrowRight size={18} className="group-hover:translate-x-1 transition-transform" />
                </>
              )}
            </button>
          </form>

          <div className="relative my-6">
            <div className="absolute inset-0 flex items-center"><div className="w-full border-t border-white/10"></div></div>
            <div className="relative flex justify-center text-xs uppercase"><span className="bg-[#0f1016] px-2 text-zinc-500">Or continue with</span></div>
          </div>

          <div className="space-y-3">
            <button 
              type="button"
              onClick={handleGoogleLogin}
              disabled={loading}
              className="w-full bg-white text-zinc-900 font-medium py-3 rounded-xl hover:bg-zinc-100 transition-colors flex items-center justify-center gap-2 shadow-lg"
            >
              <GoogleLogo />
              <span>Google Account</span>
            </button>

            <button 
              type="button"
              onClick={handleGuest}
              disabled={loading}
              className="w-full bg-white/5 border border-white/10 text-zinc-300 font-medium py-3 rounded-xl hover:bg-white/10 hover:text-white transition-all flex items-center justify-center gap-2"
            >
              <UserCircle2 size={18} />
              <span>Continue as Guest</span>
            </button>
          </div>

          <div className="mt-8 text-center text-sm text-zinc-400">
            {isLogin ? "Don't have an account?" : "Already have an account?"}{" "}
            <button 
              onClick={() => { setIsLogin(!isLogin); setError(null); }}
              className="text-indigo-400 hover:text-indigo-300 font-medium hover:underline transition-all"
            >
              {isLogin ? "Sign up" : "Log in"}
            </button>
          </div>

        </div>
      </div>
    </div>
  );
}

import React, { useState, useRef, useEffect } from 'react';
import { Menu, Sparkles, AlertTriangle } from 'lucide-react';
import { onAuthStateChanged } from 'firebase/auth';
import ChatMessage from './components/ChatMessage';
import ChatInput from './components/ChatInput';
import Sidebar from './components/Sidebar';
import AuthScreen from './components/AuthScreen';
import { Message, Role, ChatConfig, DEFAULT_CONFIG, ChatSession, User } from './types';
import { geminiService } from './services/geminiService';
import { firebaseService } from './services/firebase';

const WelcomeLogo = () => {
  return (
    <div className="w-full h-full bg-gradient-to-br from-indigo-600 via-indigo-700 to-purple-800 rounded-[2.5rem] flex items-center justify-center shadow-2xl shadow-indigo-500/20 border border-white/20">
      <Sparkles size={64} className="text-white fill-white/10 animate-pulse" />
    </div>
  );
};

const App: React.FC = () => {
  // Auth State
  const [user, setUser] = useState<User | null>(null);
  const [isGuest, setIsGuest] = useState(false);
  const [authChecked, setAuthChecked] = useState(false);

  // App State
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [config, setConfig] = useState<ChatConfig>(DEFAULT_CONFIG);
  const [slidebarOpen, setSlidebarOpen] = useState(() => typeof window !== 'undefined' ? window.innerWidth >= 1024 : false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  // 1. Firebase Auth Listener
  useEffect(() => {
    if (!firebaseService.auth) {
      // Fallback for missing keys: Try localstorage or just set default guest
      const storedUser = localStorage.getItem('neby_auth_user');
      if (storedUser) {
        setUser(JSON.parse(storedUser));
        setIsGuest(false);
      } else {
        setIsGuest(true);
      }
      setAuthChecked(true);
      return;
    }

    const unsubscribe = onAuthStateChanged(firebaseService.auth, (fbUser) => {
      if (fbUser) {
        setUser({
          id: fbUser.uid,
          name: fbUser.displayName || 'Guest',
          email: fbUser.email || '',
          avatar: fbUser.photoURL || `https://api.dicebear.com/7.x/avataaars/svg?seed=${fbUser.uid}`
        });
        setIsGuest(fbUser.isAnonymous);
      } else {
        setUser(null);
        setIsGuest(false);
      }
      setAuthChecked(true);
    });
    return () => unsubscribe();
  }, []);

  // 2. Load sessions via Firestore Listener
  useEffect(() => {
    if (!user) {
      setSessions([]);
      setCurrentSessionId(null);
      return;
    }

    // Real-time subscription to chats
    const unsubscribe = firebaseService.subscribeToSessions(user.id, (loadedSessions) => {
      setSessions(loadedSessions);
      if (loadedSessions.length === 0) {
        // Only create new chat if it's not an initial load of 0 items caused by network delay
        // We'll handle "Empty State" in UI, but if user explicitly has no chats, maybe create one?
        // Let's create one if completely empty
        const newSession = { id: Date.now().toString(), title: 'New Cosmic Chat', messages: [], createdAt: Date.now() };
        firebaseService.saveSession(user.id, newSession);
      } else if (!currentSessionId && loadedSessions.length > 0) {
        // Select most recent
        setCurrentSessionId(loadedSessions[loadedSessions.length - 1].id);
      }
    });

    return () => unsubscribe();
  }, [user]);

  // Handle manual login/guest UI callbacks (AuthScreen)
  const handleLogin = (loggedInUser: User) => {
    // onAuthStateChanged handles state, but for non-firebase fallbacks:
    setUser(loggedInUser);
    setIsGuest(false);
  };

  const handleGuestAccess = () => {
    // onAuthStateChanged handles anonymous login
  };

  const handleLogout = async () => {
    if (firebaseService.auth) {
      await firebaseService.logout();
    } else {
      setUser(null);
      setIsGuest(false);
      localStorage.removeItem('neby_auth_user');
    }
  };

  const currentSession = sessions.find(s => s.id === currentSessionId);
  const messages = currentSession ? currentSession.messages : [];

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const createNewChat = () => {
    if (!user) return;
    const newSession = { id: Date.now().toString(), title: 'New Cosmic Chat', messages: [], createdAt: Date.now() };
    firebaseService.saveSession(user.id, newSession);
    setCurrentSessionId(newSession.id);
  };

  const deleteSession = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!user) return;

    firebaseService.deleteSession(user.id, id);

    // Optimistic UI update handled by listener, but we might need to adjust selection
    if (currentSessionId === id) {
      const remaining = sessions.filter(s => s.id !== id);
      if (remaining.length > 0) {
        setCurrentSessionId(remaining[remaining.length - 1].id);
      } else {
        setCurrentSessionId(null);
      }
    }
  };

  const renameSession = (id: string, newTitle: string) => {
    if (!user) return;
    const session = sessions.find(s => s.id === id);
    if (session) {
      firebaseService.saveSession(user.id, { ...session, title: newTitle });
    }
  };

  // Helper to persist session changes
  const saveCurrentSession = (updatedMessages: Message[], title?: string) => {
    if (!user || !currentSessionId) return;
    const session = sessions.find(s => s.id === currentSessionId);
    if (session) {
      const updatedSession = { 
        ...session, 
        messages: updatedMessages,
        title: title || session.title
      };
      // Save to Firestore
      firebaseService.saveSession(user.id, updatedSession);

      // Optimistic Update (optional, since listener is fast, but good for typing speed)
      setSessions(prev => prev.map(s => s.id === currentSessionId ? updatedSession : s));
    }
  };

  const handleSendMessage = async (text: string, images: string[], type: 'text' | 'image' | 'video' = 'text') => {
    if (!currentSessionId || !user) return;

    // 1. Add User Message
    const userMsg = { id: Date.now().toString(), role: Role.USER, content: text, timestamp: Date.now(), images };
    const updatedMessages = [...messages, userMsg];
    saveCurrentSession(updatedMessages);

    setIsLoading(true);
    const botMsgId = (Date.now() + 1).toString();

    try {
      if (type === 'video') {
        const aistudio = (window as any).aistudio;
        const hasKey = await aistudio.hasSelectedApiKey();
        if (!hasKey) await aistudio.openSelectKey();

        const tempMessages = [...updatedMessages, { id: botMsgId, role: Role.MODEL, content: 'Synthesizing cosmic motion...', timestamp: Date.now(), isDirecting: true }];
        setSessions(prev => prev.map(s => s.id === currentSessionId ? { ...s, messages: tempMessages } : s));

        const videoUri = await geminiService.generateVideo(text, (msg) => {
           // Direct updates not saved to DB to prevent spamming
        });

        // Save Final
        saveCurrentSession([...updatedMessages, { id: botMsgId, role: Role.MODEL, content: 'Cosmic render complete.', videoUri, timestamp: Date.now(), isDirecting: false }]);
      } else if (type === 'image' || config.model.includes('image')) {
        const tempMessages = [...updatedMessages, { id: botMsgId, role: Role.MODEL, content: '', timestamp: Date.now(), isPainting: true }];
        setSessions(prev => prev.map(s => s.id === currentSessionId ? { ...s, messages: tempMessages } : s));

        const generatedImages = await geminiService.generateImage(text);

        saveCurrentSession([...updatedMessages, { id: botMsgId, role: Role.MODEL, content: `I've visualized: "${text}"`, images: generatedImages, timestamp: Date.now(), isPainting: false }]);
      } else {
        // Streaming Text
        const tempMessages = [...updatedMessages, { id: botMsgId, role: Role.MODEL, content: '', timestamp: Date.now(), isLoading: true }];
        setSessions(prev => prev.map(s => s.id === currentSessionId ? { ...s, messages: tempMessages } : s)); // Optimistic

        const stream = geminiService.streamChat([...updatedMessages], text, images, config);
        let fullContent = '';
        let groundingSources: any[] = [];

        for await (const chunk of stream) {
          if (typeof chunk === 'string') {
            fullContent += chunk;
            // Optimistic updates for smooth typing, don't save to DB on every char
            setSessions(prev => prev.map(s => {
              if (s.id === currentSessionId) {
                return {
                  ...s,
                  messages: s.messages.map(m => m.id === botMsgId ? { ...m, content: fullContent, isLoading: false } : m)
                };
              }
              return s;
            }));
          } else if (chunk.groundingChunks) {
            groundingSources = chunk.groundingChunks;
          }
        }

        // Final Save to DB
        let newTitle = currentSession?.title;
        if (currentSession?.messages.length === 0) {
            newTitle = text.slice(0, 30);
        }

        saveCurrentSession([
          ...updatedMessages, 
          { id: botMsgId, role: Role.MODEL, content: fullContent, timestamp: Date.now(), isLoading: false, groundingSources }
        ], newTitle);
      }
    } catch (error: any) {
      const isEntityNotFound = error.message?.includes("Requested entity was not found");
      const errorMsg = isEntityNotFound ? "⚠️ Project not found. Please re-select your paid API key." : "☄️ Neural mesh disruption.";

      saveCurrentSession([...updatedMessages, { id: botMsgId, role: Role.MODEL, content: errorMsg, timestamp: Date.now(), isLoading: false }]);
      if (isEntityNotFound) await (window as any).aistudio.openSelectKey();
    } finally {
      setIsLoading(false);
      messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  };

  if (!authChecked) return null;

  if (!user) {
    return <AuthScreen onLogin={handleLogin} onGuest={handleGuestAccess} />;
  }

  return (
    <div className="flex h-screen bg-transparent overflow-hidden">
      <Sidebar 
        isOpen={slidebarOpen} 
        onClose={() => setSlidebarOpen(false)} 
        config={config} 
        setConfig={setConfig} 
        sessions={sessions} 
        currentSessionId={currentSessionId} 
        onSelectSession={setCurrentSessionId} 
        onDeleteSession={deleteSession} 
        onRenameSession={renameSession} 
        onNewChat={createNewChat} 
        user={user}
        onLogout={handleLogout}
      />
      <div className={`flex-1 flex flex-col transition-all duration-300 ${slidebarOpen ? 'lg:ml-80' : 'lg:ml-0'}`}>
        <header className="flex items-center p-4 border-b border-white/10 bg-black/20 backdrop-blur-md z-30">
          <button onClick={() => setSlidebarOpen(!slidebarOpen)} className="text-zinc-400 p-2"><Menu size={24} /></button>
          <span className="ml-4 font-semibold text-zinc-100 truncate">{currentSession?.title || 'Neby'}</span>
        </header>
        <main className="flex-1 overflow-y-auto p-4 md:p-6 custom-scrollbar">
          {messages.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-zinc-400 space-y-4">
              <div className="w-32 h-32 bg-white/5 backdrop-blur-xl rounded-[2.5rem] flex items-center justify-center shadow-2xl shadow-purple-900/40 border border-white/10 rotate-3 transform hover:rotate-6 transition-transform duration-500 overflow-hidden">
                <WelcomeLogo />
              </div>
              <h1 className="text-3xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-200 via-indigo-200 to-purple-200 drop-shadow-sm">
                {user ? `Welcome back, ${user.name.split(' ')[0]}` : 'Welcome to Neby'}
              </h1>
              <p className="text-center max-w-md text-sm text-zinc-400 leading-relaxed">
                Neby is ready to explore ideas, reason through problems, and create with you.
              </p>
            </div>
          ) : (
            <>
              {messages.map(m => <ChatMessage key={m.id} message={m} />)}
              <div ref={messagesEndRef} />
            </>
          )}
        </main>
        <ChatInput onSendMessage={handleSendMessage} isLoading={isLoading} />
      </div>
    </div>
  );
};

export default App;

import { initializeApp, FirebaseApp } from 'firebase/app';
import { 
  getAuth, 
  signInWithPopup, 
  GoogleAuthProvider,
  signInWithEmailAndPassword,
  createUserWithEmailAndPassword,
  signInAnonymously,
  signOut,
  updateProfile,
  Auth
} from 'firebase/auth';
import { 
  getFirestore, 
  collection, 
  doc, 
  setDoc, 
  deleteDoc, 
  onSnapshot,
  query,
  orderBy,
  Firestore
} from 'firebase/firestore';
import { ChatSession, User } from '../types';

// Configuration
const firebaseConfig = {
  apiKey: process.env.FIREBASE_API_KEY,
  authDomain: process.env.FIREBASE_AUTH_DOMAIN,
  projectId: process.env.FIREBASE_PROJECT_ID,
  storageBucket: process.env.FIREBASE_STORAGE_BUCKET,
  messagingSenderId: process.env.FIREBASE_MESSAGING_SENDER_ID,
  appId: process.env.FIREBASE_APP_ID
};

let app: FirebaseApp | undefined;
let auth: Auth | undefined;
let db: Firestore | undefined;
let isConfigured = false;

try {
  // Only initialize if keys are present
  if (firebaseConfig.apiKey && !firebaseConfig.apiKey.includes("your_api_key")) {
    app = initializeApp(firebaseConfig);
    auth = getAuth(app);
    db = getFirestore(app);
    isConfigured = true;
  } else {
    console.warn("Firebase config missing. Switching to local simulation mode.");
  }
} catch (e) {
  console.error("Firebase Initialization Error:", e);
}

// --- Mock Service for Simulation Mode ---
const mockService = {
  getUsers() {
    return JSON.parse(localStorage.getItem('neby_users') || '[]');
  },

  saveUsers(users: any[]) {
    localStorage.setItem('neby_users', JSON.stringify(users));
  },

  async loginGoogle() {
    await new Promise(r => setTimeout(r, 800));
    return {
      uid: 'mock-google-' + Date.now(),
      displayName: 'Cosmic Traveler',
      email: 'traveler@galaxy.com',
      photoURL: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Cosmic',
      isAnonymous: false
    };
  },

  async loginEmail(email: string, pass: string) {
    await new Promise(r => setTimeout(r, 800));
    const users = this.getUsers();
    const user = users.find((u: any) => u.email === email && u.password === pass);
    if (!user) {
      const error: any = new Error('auth/invalid-credential');
      error.code = 'auth/invalid-credential';
      throw error;
    }
    return {
      uid: user.id,
      displayName: user.name,
      email: user.email,
      photoURL: user.avatar,
      isAnonymous: false
    };
  },

  async registerEmail(email: string, pass: string, name: string) {
    await new Promise(r => setTimeout(r, 800));
    const users = this.getUsers();
    if (users.find((u: any) => u.email === email)) {
      const error: any = new Error('auth/email-already-in-use');
      error.code = 'auth/email-already-in-use';
      throw error;
    }
    const newUser = {
      id: 'user-' + Date.now(),
      email,
      password: pass,
      name,
      avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${name}`
    };
    users.push(newUser);
    this.saveUsers(users);

    return {
      uid: newUser.id,
      displayName: newUser.name,
      email: newUser.email,
      photoURL: newUser.avatar,
      isAnonymous: false
    };
  },

  async loginGuest() {
    return {
      uid: 'guest-' + Date.now(),
      displayName: 'Guest',
      email: '',
      photoURL: null,
      isAnonymous: true
    };
  },

  subscribeToSessions(userId: string, callback: (sessions: ChatSession[]) => void) {
    const key = `neby_sessions_${userId}`;
    const sessions = JSON.parse(localStorage.getItem(key) || '[]');
    callback(sessions);
    return () => {};
  },

  async saveSession(userId: string, session: ChatSession) {
    const key = `neby_sessions_${userId}`;
    const sessions = JSON.parse(localStorage.getItem(key) || '[]');
    const index = sessions.findIndex((s: ChatSession) => s.id === session.id);
    if (index >= 0) {
      sessions[index] = session;
    } else {
      sessions.push(session);
    }
    localStorage.setItem(key, JSON.stringify(sessions));
  },

  async deleteSession(userId: string, sessionId: string) {
    const key = `neby_sessions_${userId}`;
    let sessions = JSON.parse(localStorage.getItem(key) || '[]');
    sessions = sessions.filter((s: ChatSession) => s.id !== sessionId);
    localStorage.setItem(key, JSON.stringify(sessions));
  }
};

// --- Exported Service ---

export const firebaseService = {
  auth,
  db,
  isConfigured,

  async loginGoogle() {
    if (!isConfigured || !auth) return mockService.loginGoogle();
    const provider = new GoogleAuthProvider();
    const result = await signInWithPopup(auth, provider);
    await this.saveUser(result.user);
    return result.user;
  },

  async loginEmail(email: string, pass: string) {
    if (!isConfigured || !auth) return mockService.loginEmail(email, pass);
    const result = await signInWithEmailAndPassword(auth, email, pass);
    await this.saveUser(result.user);
    return result.user;
  },

  async registerEmail(email: string, pass: string, name: string) {
    if (!isConfigured || !auth) return mockService.registerEmail(email, pass, name);
    const result = await createUserWithEmailAndPassword(auth, email, pass);
    await updateProfile(result.user, { displayName: name });
    await this.saveUser({ ...result.user, displayName: name });
    return result.user;
  },

  async loginGuest() {
    if (!isConfigured || !auth) return mockService.loginGuest();
    const result = await signInAnonymously(auth);
    return result.user;
  },

  async logout() {
    if (!isConfigured || !auth) return;
    await signOut(auth);
  },

  async saveUser(firebaseUser: any) {
    if (!isConfigured || !db) return; // Mock service handles user saving in register
    const userRef = doc(db, 'users', firebaseUser.uid);
    await setDoc(userRef, {
      uid: firebaseUser.uid,
      email: firebaseUser.email,
      name: firebaseUser.displayName || 'Anonymous',
      avatar: firebaseUser.photoURL || `https://api.dicebear.com/7.x/avataaars/svg?seed=${firebaseUser.uid}`,
      lastLogin: new Date().toISOString()
    }, { merge: true });
  },

  subscribeToSessions(userId: string, callback: (sessions: ChatSession[]) => void) {
    if (!isConfigured || !db) return mockService.subscribeToSessions(userId, callback);

    const chatsRef = collection(db, 'users', userId, 'chats');
    const q = query(chatsRef, orderBy('createdAt', 'asc'));

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const sessions: ChatSession[] = [];
      snapshot.forEach((doc) => {
        sessions.push(doc.data() as ChatSession);
      });
      callback(sessions);
    });

    return unsubscribe;
  },

  async saveSession(userId: string, session: ChatSession) {
    if (!isConfigured || !db) return mockService.saveSession(userId, session);
    const sessionRef = doc(db, 'users', userId, 'chats', session.id);
    await setDoc(sessionRef, session, { merge: true });
  },

  async deleteSession(userId: string, sessionId: string) {
    if (!isConfigured || !db) return mockService.deleteSession(userId, sessionId);
    const sessionRef = doc(db, 'users', userId, 'chats', sessionId);
    await deleteDoc(sessionRef);
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { Menu, Sparkles, AlertTriangle } from 'lucide-react';
import { onAuthStateChanged } from 'firebase/auth';
import ChatMessage from './components/ChatMessage';
import ChatInput from './components/ChatInput';
import Sidebar from './components/Sidebar';
import AuthScreen from './components/AuthScreen';
import { Message, Role, ChatConfig, DEFAULT_CONFIG, ChatSession, User } from './types';
import { geminiService } from './services/geminiService';
import { firebaseService } from './services/firebase';

const WelcomeLogo = () => {
  return (
    <div className="w-full h-full bg-gradient-to-br from-indigo-600 via-indigo-700 to-purple-800 rounded-[2.5rem] flex items-center justify-center shadow-2xl shadow-indigo-500/20 border border-white/20">
      <Sparkles size={64} className="text-white fill-white/10 animate-pulse" />
    </div>
  );
};

const App: React.FC = () => {
  // Auth State
  const [user, setUser] = useState<User | null>(null);
  const [isGuest, setIsGuest] = useState(false);
  const [authChecked, setAuthChecked] = useState(false);

  // App State
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [config, setConfig] = useState<ChatConfig>(DEFAULT_CONFIG);
  const [slidebarOpen, setSlidebarOpen] = useState(() => typeof window !== 'undefined' ? window.innerWidth >= 1024 : false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  // 1. Firebase Auth Listener
  useEffect(() => {
    // If Firebase is NOT configured, rely on local storage for auth state
    if (!firebaseService.auth || !firebaseService.isConfigured) {
      const storedUser = localStorage.getItem('neby_auth_user');
      if (storedUser) {
        setUser(JSON.parse(storedUser));
        setIsGuest(false);
      } else {
        setIsGuest(true);
      }
      setAuthChecked(true);
      return;
    }

    const unsubscribe = onAuthStateChanged(firebaseService.auth, (fbUser) => {
      if (fbUser) {
        setUser({
          id: fbUser.uid,
          name: fbUser.displayName || 'Guest',
          email: fbUser.email || '',
          avatar: fbUser.photoURL || `https://api.dicebear.com/7.x/avataaars/svg?seed=${fbUser.uid}`
        });
        setIsGuest(fbUser.isAnonymous);
      } else {
        setUser(null);
        setIsGuest(false);
      }
      setAuthChecked(true);
    });
    return () => unsubscribe();
  }, []);

  // 2. Load sessions via Service (Firestore or Mock)
  useEffect(() => {
    if (!user) {
      setSessions([]);
      setCurrentSessionId(null);
      return;
    }

    // Real-time subscription to chats (works for both Firebase and Mock)
    const unsubscribe = firebaseService.subscribeToSessions(user.id, (loadedSessions) => {
      setSessions(loadedSessions);
      if (loadedSessions.length === 0) {
        const newSession = { id: Date.now().toString(), title: 'New Cosmic Chat', messages: [], createdAt: Date.now() };
        firebaseService.saveSession(user.id, newSession);
        // If in mock mode, we need to manually trigger update since there's no real listener firing back immediately
        if (!firebaseService.isConfigured) {
             setSessions([newSession]);
             setCurrentSessionId(newSession.id);
        }
      } else if (!currentSessionId && loadedSessions.length > 0) {
        setCurrentSessionId(loadedSessions[loadedSessions.length - 1].id);
      }
    });

    return () => unsubscribe();
  }, [user]);

  // Handle manual login/guest UI callbacks
  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);
    setIsGuest(false);
    // Persist to local storage if in simulation mode
    if (!firebaseService.isConfigured) {
      localStorage.setItem('neby_auth_user', JSON.stringify(loggedInUser));
    }
  };

  const handleGuestAccess = () => {
    if (!firebaseService.isConfigured) {
       setIsGuest(true);
    }
  };

  const handleLogout = async () => {
    await firebaseService.logout();
    if (!firebaseService.isConfigured) {
      localStorage.removeItem('neby_auth_user');
      setUser(null);
      setIsGuest(false);
    }
  };

  const currentSession = sessions.find(s => s.id === currentSessionId);
  const messages = currentSession ? currentSession.messages : [];

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const createNewChat = () => {
    if (!user) return;
    const newSession = { id: Date.now().toString(), title: 'New Cosmic Chat', messages: [], createdAt: Date.now() };
    firebaseService.saveSession(user.id, newSession);
    // Manually update state for optimistic UI or Mock mode
    setSessions(prev => [...prev, newSession]);
    setCurrentSessionId(newSession.id);
  };

  const deleteSession = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!user) return;

    firebaseService.deleteSession(user.id, id);

    const remaining = sessions.filter(s => s.id !== id);
    setSessions(remaining);

    if (currentSessionId === id) {
      if (remaining.length > 0) {
        setCurrentSessionId(remaining[remaining.length - 1].id);
      } else {
        setCurrentSessionId(null);
      }
    }
  };

  const renameSession = (id: string, newTitle: string) => {
    if (!user) return;
    const session = sessions.find(s => s.id === id);
    if (session) {
      const updated = { ...session, title: newTitle };
      firebaseService.saveSession(user.id, updated);
      setSessions(prev => prev.map(s => s.id === id ? updated : s));
    }
  };

  // Helper to persist session changes
  const saveCurrentSession = (updatedMessages: Message[], title?: string) => {
    if (!user || !currentSessionId) return;
    const session = sessions.find(s => s.id === currentSessionId);
    if (session) {
      const updatedSession = { 
        ...session, 
        messages: updatedMessages,
        title: title || session.title
      };
      // Save to Firestore/Mock
      firebaseService.saveSession(user.id, updatedSession);

      // Optimistic Update
      setSessions(prev => prev.map(s => s.id === currentSessionId ? updatedSession : s));
    }
  };

  const handleSendMessage = async (text: string, images: string[], type: 'text' | 'image' | 'video' = 'text') => {
    if (!currentSessionId || !user) return;

    // 1. Add User Message
    const userMsg = { id: Date.now().toString(), role: Role.USER, content: text, timestamp: Date.now(), images };
    const updatedMessages = [...messages, userMsg];
    saveCurrentSession(updatedMessages);

    setIsLoading(true);
    const botMsgId = (Date.now() + 1).toString();

    try {
      if (type === 'video') {
        const aistudio = (window as any).aistudio;
        const hasKey = await aistudio.hasSelectedApiKey();
        if (!hasKey) await aistudio.openSelectKey();

        const tempMessages = [...updatedMessages, { id: botMsgId, role: Role.MODEL, content: 'Synthesizing cosmic motion...', timestamp: Date.now(), isDirecting: true }];
        setSessions(prev => prev.map(s => s.id === currentSessionId ? { ...s, messages: tempMessages } : s));

        const videoUri = await geminiService.generateVideo(text, (msg) => {
           // Direct updates not saved to DB to prevent spamming
        });

        // Save Final
        saveCurrentSession([...updatedMessages, { id: botMsgId, role: Role.MODEL, content: 'Cosmic render complete.', videoUri, timestamp: Date.now(), isDirecting: false }]);
      } else if (type === 'image' || config.model.includes('image')) {
        const tempMessages = [...updatedMessages, { id: botMsgId, role: Role.MODEL, content: '', timestamp: Date.now(), isPainting: true }];
        setSessions(prev => prev.map(s => s.id === currentSessionId ? { ...s, messages: tempMessages } : s));

        const generatedImages = await geminiService.generateImage(text);

        saveCurrentSession([...updatedMessages, { id: botMsgId, role: Role.MODEL, content: `I've visualized: "${text}"`, images: generatedImages, timestamp: Date.now(), isPainting: false }]);
      } else {
        // Streaming Text
        const tempMessages = [...updatedMessages, { id: botMsgId, role: Role.MODEL, content: '', timestamp: Date.now(), isLoading: true }];
        setSessions(prev => prev.map(s => s.id === currentSessionId ? { ...s, messages: tempMessages } : s)); // Optimistic

        const stream = geminiService.streamChat([...updatedMessages], text, images, config);
        let fullContent = '';
        let groundingSources: any[] = [];

        for await (const chunk of stream) {
          if (typeof chunk === 'string') {
            fullContent += chunk;
            // Optimistic updates for smooth typing, don't save to DB on every char
            setSessions(prev => prev.map(s => {
              if (s.id === currentSessionId) {
                return {
                  ...s,
                  messages: s.messages.map(m => m.id === botMsgId ? { ...m, content: fullContent, isLoading: false } : m)
                };
              }
              return s;
            }));
          } else if (chunk.groundingChunks) {
            groundingSources = chunk.groundingChunks;
          }
        }

        // Final Save to DB
        let newTitle = currentSession?.title;
        if (currentSession?.messages.length === 0) {
            newTitle = text.slice(0, 30);
        }

        saveCurrentSession([
          ...updatedMessages, 
          { id: botMsgId, role: Role.MODEL, content: fullContent, timestamp: Date.now(), isLoading: false, groundingSources }
        ], newTitle);
      }
    } catch (error: any) {
      const isEntityNotFound = error.message?.includes("Requested entity was not found");
      const errorMsg = isEntityNotFound ? "⚠️ Project not found. Please re-select your paid API key." : "☄️ Neural mesh disruption.";

      saveCurrentSession([...updatedMessages, { id: botMsgId, role: Role.MODEL, content: errorMsg, timestamp: Date.now(), isLoading: false }]);
      if (isEntityNotFound) await (window as any).aistudio.openSelectKey();
    } finally {
      setIsLoading(false);
      messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  };

  if (!authChecked) return null;

  if (!user) {
    return <AuthScreen onLogin={handleLogin} onGuest={handleGuestAccess} />;
  }

  return (
    <div className="flex h-screen bg-transparent overflow-hidden">
      <Sidebar 
        isOpen={slidebarOpen} 
        onClose={() => setSlidebarOpen(false)} 
        config={config} 
        setConfig={setConfig} 
        sessions={sessions} 
        currentSessionId={currentSessionId} 
        onSelectSession={setCurrentSessionId} 
        onDeleteSession={deleteSession} 
        onRenameSession={renameSession} 
        onNewChat={createNewChat} 
        user={user}
        onLogout={handleLogout}
      />
      <div className={`flex-1 flex flex-col transition-all duration-300 ${slidebarOpen ? 'lg:ml-80' : 'lg:ml-0'}`}>
        <header className="flex items-center p-4 border-b border-white/10 bg-black/20 backdrop-blur-md z-30">
          <button onClick={() => setSlidebarOpen(!slidebarOpen)} className="text-zinc-400 p-2"><Menu size={24} /></button>
          <span className="ml-4 font-semibold text-zinc-100 truncate">{currentSession?.title || 'Neby'}</span>
        </header>
        <main className="flex-1 overflow-y-auto p-4 md:p-6 custom-scrollbar">
          {messages.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-zinc-400 space-y-4">
              <div className="w-32 h-32 bg-white/5 backdrop-blur-xl rounded-[2.5rem] flex items-center justify-center shadow-2xl shadow-purple-900/40 border border-white/10 rotate-3 transform hover:rotate-6 transition-transform duration-500 overflow-hidden">
                <WelcomeLogo />
              </div>
              <h1 className="text-3xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-200 via-indigo-200 to-purple-200 drop-shadow-sm">
                {user ? `Welcome back, ${user.name.split(' ')[0]}` : 'Welcome to Neby'}
              </h1>
              <p className="text-center max-w-md text-sm text-zinc-400 leading-relaxed">
                Neby is ready to explore ideas, reason through problems, and create with you.
              </p>
            </div>
          ) : (
            <>
              {messages.map(m => <ChatMessage key={m.id} message={m} />)}
              <div ref={messagesEndRef} />
            </>
          )}
        </main>
        <ChatInput onSendMessage={handleSendMessage} isLoading={isLoading} />
      </div>
    </div>
  );
};

