import React, { useState, useRef, useEffect } from 'react';
import { Menu, Sparkles, AlertTriangle } from 'lucide-react';
import ChatMessage from './components/ChatMessage';
import ChatInput from './components/ChatInput';
import Sidebar from './components/Sidebar';
import AuthScreen from './components/AuthScreen';
import { Message, Role, ChatConfig, DEFAULT_CONFIG, ChatSession, User } from './types';
import { geminiService } from './services/geminiService';
import { firebaseService } from './services/firebase';

const WelcomeLogo = () => {
  return (
    <div className="w-full h-full bg-gradient-to-br from-indigo-600 via-indigo-700 to-purple-800 rounded-[2.5rem] flex items-center justify-center shadow-2xl shadow-indigo-500/20 border border-white/20">
      <Sparkles size={64} className="text-white fill-white/10 animate-pulse" />
    </div>
  );
};

const App: React.FC = () => {
  // Auth State
  const [user, setUser] = useState<User | null>(null);
  const [isGuest, setIsGuest] = useState(false);
  const [authChecked, setAuthChecked] = useState(false);

  // App State
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [config, setConfig] = useState<ChatConfig>(DEFAULT_CONFIG);
  const [slidebarOpen, setSlidebarOpen] = useState(() => typeof window !== 'undefined' ? window.innerWidth >= 1024 : false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  // 1. Auth Initialization
  useEffect(() => {
    // Rely on local storage for auth state (Simulation Mode)
    const storedUser = localStorage.getItem('neby_auth_user');
    if (storedUser) {
      setUser(JSON.parse(storedUser));
      setIsGuest(false);
    } else {
      setIsGuest(true);
    }
    setAuthChecked(true);
  }, []);

  // 2. Load sessions via Service (Mock)
  useEffect(() => {
    if (!user) {
      setSessions([]);
      setCurrentSessionId(null);
      return;
    }

    // Real-time subscription to chats
    const unsubscribe = firebaseService.subscribeToSessions(user.id, (loadedSessions) => {
      setSessions(loadedSessions);
      if (loadedSessions.length === 0) {
        const newSession = { id: Date.now().toString(), title: 'New Cosmic Chat', messages: [], createdAt: Date.now() };
        firebaseService.saveSession(user.id, newSession);
        // If in mock mode, we need to manually trigger update since there's no real listener firing back immediately for local storage in some implementations, 
        // but our mockService.subscribeToSessions does invoke callback immediately.
        // However, manual state update ensures UI responsiveness.
        setSessions([newSession]);
        setCurrentSessionId(newSession.id);
      } else if (!currentSessionId && loadedSessions.length > 0) {
        setCurrentSessionId(loadedSessions[loadedSessions.length - 1].id);
      }
    });

    return () => unsubscribe();
  }, [user]);

  // Handle manual login/guest UI callbacks
  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);
    setIsGuest(false);
    // Persist to local storage if in simulation mode
    if (!firebaseService.isConfigured) {
      localStorage.setItem('neby_auth_user', JSON.stringify(loggedInUser));
    }
  };

  const handleGuestAccess = () => {
    if (!firebaseService.isConfigured) {
       setIsGuest(true);
    }
  };

  const handleLogout = async () => {
    await firebaseService.logout();
    if (!firebaseService.isConfigured) {
      localStorage.removeItem('neby_auth_user');
      setUser(null);
      setIsGuest(false);
    }
  };

  const currentSession = sessions.find(s => s.id === currentSessionId);
  const messages = currentSession ? currentSession.messages : [];

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const createNewChat = () => {
    if (!user) return;
    const newSession = { id: Date.now().toString(), title: 'New Cosmic Chat', messages: [], createdAt: Date.now() };
    firebaseService.saveSession(user.id, newSession);
    // Manually update state for optimistic UI or Mock mode
    setSessions(prev => [...prev, newSession]);
    setCurrentSessionId(newSession.id);
  };

  const deleteSession = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!user) return;

    firebaseService.deleteSession(user.id, id);

    const remaining = sessions.filter(s => s.id !== id);
    setSessions(remaining);

    if (currentSessionId === id) {
      if (remaining.length > 0) {
        setCurrentSessionId(remaining[remaining.length - 1].id);
      } else {
        setCurrentSessionId(null);
      }
    }
  };

  const renameSession = (id: string, newTitle: string) => {
    if (!user) return;
    const session = sessions.find(s => s.id === id);
    if (session) {
      const updated = { ...session, title: newTitle };
      firebaseService.saveSession(user.id, updated);
      setSessions(prev => prev.map(s => s.id === id ? updated : s));
    }
  };

  // Helper to persist session changes
  const saveCurrentSession = (updatedMessages: Message[], title?: string) => {
    if (!user || !currentSessionId) return;
    const session = sessions.find(s => s.id === currentSessionId);
    if (session) {
      const updatedSession = { 
        ...session, 
        messages: updatedMessages,
        title: title || session.title
      };
      // Save to Firestore/Mock
      firebaseService.saveSession(user.id, updatedSession);

      // Optimistic Update
      setSessions(prev => prev.map(s => s.id === currentSessionId ? updatedSession : s));
    }
  };

  const handleSendMessage = async (text: string, images: string[], type: 'text' | 'image' | 'video' = 'text') => {
    if (!currentSessionId || !user) return;

    // 1. Add User Message
    const userMsg = { id: Date.now().toString(), role: Role.USER, content: text, timestamp: Date.now(), images };
    const updatedMessages = [...messages, userMsg];
    saveCurrentSession(updatedMessages);

    setIsLoading(true);
    const botMsgId = (Date.now() + 1).toString();

    try {
      if (type === 'video') {
        const aistudio = (window as any).aistudio;
        const hasKey = await aistudio.hasSelectedApiKey();
        if (!hasKey) await aistudio.openSelectKey();

        const tempMessages = [...updatedMessages, { id: botMsgId, role: Role.MODEL, content: 'Synthesizing cosmic motion...', timestamp: Date.now(), isDirecting: true }];
        setSessions(prev => prev.map(s => s.id === currentSessionId ? { ...s, messages: tempMessages } : s));

        const videoUri = await geminiService.generateVideo(text, (msg) => {
           // Direct updates not saved to DB to prevent spamming
        });

        // Save Final
        saveCurrentSession([...updatedMessages, { id: botMsgId, role: Role.MODEL, content: 'Cosmic render complete.', videoUri, timestamp: Date.now(), isDirecting: false }]);
      } else if (type === 'image' || config.model.includes('image')) {
        const tempMessages = [...updatedMessages, { id: botMsgId, role: Role.MODEL, content: '', timestamp: Date.now(), isPainting: true }];
        setSessions(prev => prev.map(s => s.id === currentSessionId ? { ...s, messages: tempMessages } : s));

        const generatedImages = await geminiService.generateImage(text);

        saveCurrentSession([...updatedMessages, { id: botMsgId, role: Role.MODEL, content: `I've visualized: "${text}"`, images: generatedImages, timestamp: Date.now(), isPainting: false }]);
      } else {
        // Streaming Text
        const tempMessages = [...updatedMessages, { id: botMsgId, role: Role.MODEL, content: '', timestamp: Date.now(), isLoading: true }];
        setSessions(prev => prev.map(s => s.id === currentSessionId ? { ...s, messages: tempMessages } : s)); // Optimistic

        const stream = geminiService.streamChat([...updatedMessages], text, images, config);
        let fullContent = '';
        let groundingSources: any[] = [];

        for await (const chunk of stream) {
          if (typeof chunk === 'string') {
            fullContent += chunk;
            // Optimistic updates for smooth typing, don't save to DB on every char
            setSessions(prev => prev.map(s => {
              if (s.id === currentSessionId) {
                return {
                  ...s,
                  messages: s.messages.map(m => m.id === botMsgId ? { ...m, content: fullContent, isLoading: false } : m)
                };
              }
              return s;
            }));
          } else if (chunk.groundingChunks) {
            groundingSources = chunk.groundingChunks;
          }
        }

        // Final Save to DB
        let newTitle = currentSession?.title;
        if (currentSession?.messages.length === 0) {
            newTitle = text.slice(0, 30);
        }

        saveCurrentSession([
          ...updatedMessages, 
          { id: botMsgId, role: Role.MODEL, content: fullContent, timestamp: Date.now(), isLoading: false, groundingSources }
        ], newTitle);
      }
    } catch (error: any) {
      const errorMessage = error.message || error.error?.message || JSON.stringify(error);
      const isEntityNotFound = errorMessage.includes("Requested entity was not found") || error.code === 404;

      const uiErrorMsg = isEntityNotFound 
        ? "⚠️ **Project/Model Access Error**. Please re-select your paid API key from a valid Google Cloud Project." 
        : "☄️ Neural mesh disruption.";

      saveCurrentSession([...updatedMessages, { id: botMsgId, role: Role.MODEL, content: uiErrorMsg, timestamp: Date.now(), isLoading: false }]);

      if (isEntityNotFound) {
        try {
          await (window as any).aistudio.openSelectKey();
        } catch (e) {
          console.error("Failed to open key selector", e);
        }
      }
    } finally {
      setIsLoading(false);
      messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  };

  if (!authChecked) return null;

  if (!user) {
    return <AuthScreen onLogin={handleLogin} onGuest={handleGuestAccess} />;
  }

  return (
    <div className="flex h-screen bg-transparent overflow-hidden">
      <Sidebar 
        isOpen={slidebarOpen} 
        onClose={() => setSlidebarOpen(false)} 
        config={config} 
        setConfig={setConfig} 
        sessions={sessions} 
        currentSessionId={currentSessionId} 
        onSelectSession={setCurrentSessionId} 
        onDeleteSession={deleteSession} 
        onRenameSession={renameSession} 
        onNewChat={createNewChat} 
        user={user}
        onLogout={handleLogout}
      />
      <div className={`flex-1 flex flex-col transition-all duration-300 ${slidebarOpen ? 'lg:ml-80' : 'lg:ml-0'}`}>
        <header className="flex items-center p-4 border-b border-white/10 bg-black/20 backdrop-blur-md z-30">
          <button onClick={() => setSlidebarOpen(!slidebarOpen)} className="text-zinc-400 p-2"><Menu size={24} /></button>
          <span className="ml-4 font-semibold text-zinc-100 truncate">{currentSession?.title || 'Neby'}</span>
        </header>
        <main className="flex-1 overflow-y-auto p-4 md:p-6 custom-scrollbar">
          {messages.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-zinc-400 space-y-4">
              <div className="w-32 h-32 bg-white/5 backdrop-blur-xl rounded-[2.5rem] flex items-center justify-center shadow-2xl shadow-purple-900/40 border border-white/10 rotate-3 transform hover:rotate-6 transition-transform duration-500 overflow-hidden">
                <WelcomeLogo />
              </div>
              <h1 className="text-3xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-200 via-indigo-200 to-purple-200 drop-shadow-sm">
                {user ? `Welcome back, ${user.name.split(' ')[0]}` : 'Welcome to Neby'}
              </h1>
              <p className="text-center max-w-md text-sm text-zinc-400 leading-relaxed">
                Neby is ready to explore ideas, reason through problems, and create with you.
              </p>
            </div>
          ) : (
            <>
              {messages.map(m => <ChatMessage key={m.id} message={m} />)}
              <div ref={messagesEndRef} />
            </>
          )}
        </main>
        <ChatInput onSendMessage={handleSendMessage} isLoading={isLoading} />
      </div>
    </div>
  );
};

