const NebyLogo = () => {
  const [error, setError] = useState(false);
  if (error) return <Brain size={20} className="text-indigo-400" />;
  return (
    <img 
      src="logo.png" 
      alt="Neby" 
      onError={() => setError(true)}
      className="w-8 h-8 object-contain filter drop-shadow-[0_0_5px_rgba(129,140,248,0.3)]"
