// --- Live Session Overlay ---
const LiveSessionOverlay = ({ onClose }: { onClose: () => void }) => {
  const [status, setStatus] = useState("Connecting...");
  const [isSpeaking, setIsSpeaking] = useState(false);
  const visualizerRef = useRef<HTMLDivElement>(null);
  const sessionRef = useRef<any>(null); // Store session promise/ref

  useEffect(() => {
    // Setup Live API
    let cleanup: (() => void) | undefined;

    const startLive = async () => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        const inputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
        const outputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        const outputNode = outputAudioContext.createGain();
        outputNode.connect(outputAudioContext.destination);

        // Input pipeline
        const source = inputAudioContext.createMediaStreamSource(stream);
        const scriptProcessor = inputAudioContext.createScriptProcessor(4096, 1, 1);

        let nextStartTime = 0;

        const sessionPromise = geminiService.ai.live.connect({
          model: 'gemini-2.5-flash-native-audio-preview-12-2025',
          callbacks: {
            onopen: () => setStatus("Listening..."),
            onmessage: async (message: LiveServerMessage) => {
              // Handle Audio Output
              const base64Audio = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
              if (base64Audio) {
                setIsSpeaking(true);
                // Decode & Play
                const binaryString = atob(base64Audio);
                const bytes = new Uint8Array(binaryString.length);
                for (let i = 0; i < bytes.length; i++) bytes[i] = binaryString.charCodeAt(i);

                const float32Data = new Float32Array(bytes.length / 2);
                const dataInt16 = new Int16Array(bytes.buffer);
                for (let i = 0; i < dataInt16.length; i++) float32Data[i] = dataInt16[i] / 32768.0;

                const buffer = outputAudioContext.createBuffer(1, float32Data.length, 24000);
                buffer.getChannelData(0).set(float32Data);

                const sourceNode = outputAudioContext.createBufferSource();
                sourceNode.buffer = buffer;
                sourceNode.connect(outputNode);

                nextStartTime = Math.max(outputAudioContext.currentTime, nextStartTime);
                sourceNode.start(nextStartTime);
                nextStartTime += buffer.duration;

                sourceNode.onended = () => {
                   if (outputAudioContext.currentTime >= nextStartTime) setIsSpeaking(false);
                };
              }
            },
            onclose: () => setStatus("Disconnected"),
            onerror: (e) => setStatus("Error: " + e.type)
          },
          config: {
            responseModalities: [Modality.AUDIO],
            speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } } }
          }
        });

        sessionRef.current = sessionPromise;

        // Send Audio Input
        scriptProcessor.onaudioprocess = (e) => {
          const inputData = e.inputBuffer.getChannelData(0);
          const l = inputData.length;
          const int16 = new Int16Array(l);
          for (let i = 0; i < l; i++) int16[i] = inputData[i] * 32768;

          const bytes = new Uint8Array(int16.buffer);
          let binary = '';
          for (let i = 0; i < bytes.byteLength; i++) binary += String.fromCharCode(bytes[i]);
          const base64 = btoa(binary);

          sessionPromise.then(session => {
            session.sendRealtimeInput({
              media: { mimeType: 'audio/pcm;rate=16000', data: base64 }
            });
          });
        };

        source.connect(scriptProcessor);
        scriptProcessor.connect(inputAudioContext.destination);

        cleanup = () => {
            stream.getTracks().forEach(t => t.stop());
            scriptProcessor.disconnect();
            source.disconnect();
            inputAudioContext.close();
            outputAudioContext.close();
        };

      } catch (e) {
        console.error(e);
        setStatus("Microphone access denied or API error.");
      }
    };

    startLive();
    return () => cleanup && cleanup();
  }, []);

  return (
    <div className="fixed inset-0 z-50 bg-black/90 backdrop-blur-xl flex flex-col items-center justify-center">
       <div className="absolute top-8 right-8">
         <button onClick={onClose} className="p-4 bg-white/10 rounded-full hover:bg-white/20 transition-all">
           <X size={32} />
         </button>
       </div>
       <div className="text-center space-y-8">
         <div className={`w-48 h-48 rounded-full flex items-center justify-center border-4 transition-all duration-300 ${isSpeaking ? 'border-cyan-400 shadow-[0_0_50px_rgba(34,211,238,0.5)] scale-110' : 'border-zinc-700'}`}>
            <div className={`w-40 h-40 rounded-full bg-gradient-to-tr from-cyan-600 to-blue-600 flex items-center justify-center ${isSpeaking ? 'animate-pulse' : ''}`}>
               <Mic size={64} className="text-white" />
            </div>
         </div>
         <div>
            <h2 className="text-3xl font-bold text-white mb-2">Neby Live</h2>
            <p className="text-zinc-400 text-lg animate-pulse">{status}</p>
         </div>
       </div>
    </div>
  );
};


const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [isGuest, setIsGuest] = useState(false);
  const [authChecked, setAuthChecked] = useState(false);
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [config, setConfig] = useState<ChatConfig>(DEFAULT_CONFIG);
  const [slidebarOpen, setSlidebarOpen] = useState(() => typeof window !== 'undefined' ? window.innerWidth >= 1024 : false);
  const [isLiveMode, setIsLiveMode] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const storedUser = localStorage.getItem('neby_auth_user');
    if (storedUser) {
      setUser(JSON.parse(storedUser));
      setIsGuest(false);
    } else {
      setIsGuest(true);
    }
    setAuthChecked(true);
  }, []);

  useEffect(() => {
    if (!user) {
      setSessions([]);
      setCurrentSessionId(null);
      return;
    }
    const unsubscribe = firebaseService.subscribeToSessions(user.id, (loadedSessions) => {
      setSessions(loadedSessions);
      if (loadedSessions.length === 0) {
        const newSession = { id: Date.now().toString(), title: 'New Cosmic Chat', messages: [], createdAt: Date.now() };
        firebaseService.saveSession(user.id, newSession);
        setSessions([newSession]);
        setCurrentSessionId(newSession.id);
      } else if (!currentSessionId && loadedSessions.length > 0) {
        setCurrentSessionId(loadedSessions[loadedSessions.length - 1].id);
      }
    });
    return () => unsubscribe();
  }, [user]);

  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);
    setIsGuest(false);
    if (!firebaseService.isConfigured) {
      localStorage.setItem('neby_auth_user', JSON.stringify(loggedInUser));
    }
  };

  const handleGuestAccess = () => {
    if (!firebaseService.isConfigured) setIsGuest(true);
  };

  const handleLogout = async () => {
    await firebaseService.logout();
    if (!firebaseService.isConfigured) {
      localStorage.removeItem('neby_auth_user');
      setUser(null);
      setIsGuest(false);
    }
  };

  const currentSession = sessions.find(s => s.id === currentSessionId);
  const messages = currentSession ? currentSession.messages : [];

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const createNewChat = () => {
    if (!user) return;
    const newSession = { id: Date.now().toString(), title: 'New Cosmic Chat', messages: [], createdAt: Date.now() };
    firebaseService.saveSession(user.id, newSession);
    setSessions(prev => [...prev, newSession]);
    setCurrentSessionId(newSession.id);
  };

  const deleteSession = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!user) return;
    firebaseService.deleteSession(user.id, id);
    const remaining = sessions.filter(s => s.id !== id);
    setSessions(remaining);
    if (currentSessionId === id) {
      if (remaining.length > 0) setCurrentSessionId(remaining[remaining.length - 1].id);
      else setCurrentSessionId(null);
    }
  };

  const renameSession = (id: string, newTitle: string) => {
    if (!user) return;
    const session = sessions.find(s => s.id === id);
    if (session) {
      const updated = { ...session, title: newTitle };
      firebaseService.saveSession(user.id, updated);
      setSessions(prev => prev.map(s => s.id === id ? updated : s));
    }
  };

  const saveCurrentSession = (updatedMessages: Message[], title?: string) => {
    if (!user || !currentSessionId) return;
    const session = sessions.find(s => s.id === currentSessionId);
    if (session) {
      const updatedSession = { ...session, messages: updatedMessages, title: title || session.title };
      firebaseService.saveSession(user.id, updatedSession);
      setSessions(prev => prev.map(s => s.id === currentSessionId ? updatedSession : s));
    }
  };

  const handleSendMessage = async (text: string, images: string[], type: 'text' | 'image' | 'video' = 'text', videoData?: string) => {
    if (!currentSessionId || !user) return;

    // Determine implied type based on config or inputs
    let actualType = type;
    if (config.model.includes('image') && type === 'text' && !videoData) actualType = 'image';

    // User Message
    const userMsg = { 
      id: Date.now().toString(), 
      role: Role.USER, 
      content: text, 
      timestamp: Date.now(), 
      images,
      videoUri: videoData ? 'Attached Video' : undefined // Basic indicator
    };

    const updatedMessages = [...messages, userMsg];
    saveCurrentSession(updatedMessages);

    setIsLoading(true);
    const botMsgId = (Date.now() + 1).toString();

    try {
      if (actualType === 'video') {
        // VEO Generation (Text to Video OR Image to Video)
        const aistudio = (window as any).aistudio;
        const hasKey = await aistudio.hasSelectedApiKey();
        if (!hasKey) await aistudio.openSelectKey();

        const tempMessages = [...updatedMessages, { id: botMsgId, role: Role.MODEL, content: 'Synthesizing cosmic motion (Veo)...', timestamp: Date.now(), isDirecting: true }];
        setSessions(prev => prev.map(s => s.id === currentSessionId ? { ...s, messages: tempMessages } : s));

        // Pass first image if available for Animate Image feature
        const videoUri = await geminiService.generateVideo(text, config, images[0]);

        saveCurrentSession([...updatedMessages, { id: botMsgId, role: Role.MODEL, content: 'Cosmic render complete.', videoUri, timestamp: Date.now(), isDirecting: false }]);

      } else if (actualType === 'image') {
        // Image Generation / Editing
        const tempMessages = [...updatedMessages, { id: botMsgId, role: Role.MODEL, content: '', timestamp: Date.now(), isPainting: true }];
        setSessions(prev => prev.map(s => s.id === currentSessionId ? { ...s, messages: tempMessages } : s));

        // If images provided, it's editing. If not, generation.
        const generatedImages = await geminiService.generateImage(text, config, images);

        const actionText = images.length > 0 ? "Edited image" : `Generated: "${text}"`;
        saveCurrentSession([...updatedMessages, { id: botMsgId, role: Role.MODEL, content: actionText, images: generatedImages, timestamp: Date.now(), isPainting: false }]);

      } else {
        // Text/Chat/Analysis
        const tempMessages = [...updatedMessages, { id: botMsgId, role: Role.MODEL, content: '', timestamp: Date.now(), isLoading: true }];
        setSessions(prev => prev.map(s => s.id === currentSessionId ? { ...s, messages: tempMessages } : s));

        const stream = geminiService.streamChat([...updatedMessages], text, images, config, videoData);
        let fullContent = '';
        let groundingSources: any[] = [];

        for await (const chunk of stream) {
          if (typeof chunk === 'string') {
            fullContent += chunk;
            setSessions(prev => prev.map(s => {
              if (s.id === currentSessionId) {
                return {
                  ...s,
                  messages: s.messages.map(m => m.id === botMsgId ? { ...m, content: fullContent, isLoading: false } : m)
                };
              }
              return s;
            }));
          } else if (chunk.groundingChunks) {
            groundingSources = chunk.groundingChunks;
          }
        }

        let newTitle = currentSession?.title;
        if (currentSession?.messages.length === 0) newTitle = text.slice(0, 30);

        saveCurrentSession([
          ...updatedMessages, 
          { id: botMsgId, role: Role.MODEL, content: fullContent, timestamp: Date.now(), isLoading: false, groundingSources }
        ], newTitle);
      }
    } catch (error: any) {
      const errorMessage = error.message || error.error?.message || JSON.stringify(error);
      const isEntityNotFound = errorMessage.includes("Requested entity was not found") || error.code === 404;
      const uiErrorMsg = isEntityNotFound 
        ? "⚠️ **Project Access Error**. Please re-select your paid API key from a valid Google Cloud Project." 
        : `☄️ Error: ${errorMessage.slice(0,100)}`;

      saveCurrentSession([...updatedMessages, { id: botMsgId, role: Role.MODEL, content: uiErrorMsg, timestamp: Date.now(), isLoading: false }]);
      if (isEntityNotFound) await (window as any).aistudio.openSelectKey();
    } finally {
      setIsLoading(false);
      messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  };

  if (!authChecked) return null;
  if (!user) return <AuthScreen onLogin={handleLogin} onGuest={handleGuestAccess} />;

  return (
    <div className="flex h-screen bg-transparent overflow-hidden">
      {isLiveMode && <LiveSessionOverlay onClose={() => setIsLiveMode(false)} />}
      <Sidebar 
        isOpen={slidebarOpen} 
        onClose={() => setSlidebarOpen(false)} 
        config={config} 
        setConfig={setConfig} 
        sessions={sessions} 
        currentSessionId={currentSessionId} 
        onSelectSession={setCurrentSessionId} 
        onDeleteSession={deleteSession} 
        onRenameSession={renameSession} 
        onNewChat={createNewChat} 
        user={user}
        onLogout={handleLogout}
      />
      <div className={`flex-1 flex flex-col transition-all duration-300 ${slidebarOpen ? 'lg:ml-80' : 'lg:ml-0'}`}>
        <header className="flex items-center p-4 border-b border-white/10 bg-black/20 backdrop-blur-md z-30">
          <button onClick={() => setSlidebarOpen(!slidebarOpen)} className="text-zinc-400 p-2"><Menu size={24} /></button>
          <span className="ml-4 font-semibold text-zinc-100 truncate">{currentSession?.title || 'Neby'}</span>
        </header>
        <main className="flex-1 overflow-y-auto p-4 md:p-6 custom-scrollbar">
          {messages.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-zinc-400 space-y-4">
              <div className="w-32 h-32 bg-white/5 backdrop-blur-xl rounded-[2.5rem] flex items-center justify-center shadow-2xl shadow-purple-900/40 border border-white/10 rotate-3 transform hover:rotate-6 transition-transform duration-500 overflow-hidden">
                <WelcomeLogo />
              </div>
              <h1 className="text-3xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-200 via-indigo-200 to-purple-200 drop-shadow-sm">
                {user ? `Welcome back, ${user.name.split(' ')[0]}` : 'Welcome to Neby'}
              </h1>
              <p className="text-center max-w-md text-sm text-zinc-400 leading-relaxed">
                Explore the cosmos with Gemini 3, Veo, and Live Audio.
              </p>
            </div>
          ) : (
            <>
              {messages.map(m => <ChatMessage key={m.id} message={m} />)}
              <div ref={messagesEndRef} />
            </>
          )}
        </main>
        <ChatInput 
          onSendMessage={handleSendMessage} 
          isLoading={isLoading} 
          onLiveStart={() => setIsLiveMode(true)}
        />
      </div>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { Send, X, Loader2, Mic, MicOff, Sparkles, Wand2, Video, Paperclip } from 'lucide-react';
import { geminiService } from '../services/geminiService';
import { ModelOption } from '../types';

interface ChatInputProps {
  onSendMessage: (text: string, images: string[], type: 'text' | 'image' | 'video', videoData?: string) => void;
  isLoading: boolean;
  onLiveStart: () => void;
  selectedModel: ModelOption;
}

const ChatInput: React.FC<ChatInputProps> = ({ onSendMessage, isLoading, onLiveStart, selectedModel }) => {
  const [text, setText] = useState('');
  const [images, setImages] = useState<string[]>([]);
  const [video, setVideo] = useState<string | null>(null);

  const [isRecording, setIsRecording] = useState(false);
  const [isTranscribing, setIsTranscribing] = useState(false);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = Math.min(textareaRef.current.scrollHeight, 160) + 'px';
    }
  }, [text]);

  const handleSend = (type: 'text' | 'image' | 'video' = 'text') => {
    if ((!text.trim() && images.length === 0 && !video) || isLoading) return;

    // Determine type: if video attached -> 'text' (video understanding) or 'video' (generation)?
    // Usually, send 'text' with attachments for understanding. 
    // Send 'video' type only if we want Veo generation.
    // Logic handled in App.tsx based on type param.

    onSendMessage(text.trim(), images, type, video || undefined);
    setText('');
    setImages([]);
    setVideo(null);
    if (textareaRef.current) textareaRef.current.style.height = 'auto';
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend('text'); // Default chat send
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];

      if (file.type.startsWith('image/')) {
        const reader = new FileReader();
        reader.onloadend = () => {
          if (typeof reader.result === 'string') {
            setImages(prev => [...prev, reader.result as string]);
          }
        };
        reader.readAsDataURL(file);
      } else if (file.type.startsWith('video/')) {
        if (file.size > 20 * 1024 * 1024) {
          alert("Video too large (Max 20MB for direct upload)");
          return;
        }
        const reader = new FileReader();
        reader.onloadend = () => {
          if (typeof reader.result === 'string') {
            setVideo(reader.result);
          }
        };
        reader.readAsDataURL(file);
      }
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  // Transcription Recording
  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const recorder = new MediaRecorder(stream);
      mediaRecorderRef.current = recorder;
      audioChunksRef.current = [];

      recorder.ondataavailable = (e) => {
        if (e.data.size > 0) audioChunksRef.current.push(e.data);
      };

      recorder.onstop = async () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/wav' });
        await handleTranscription(audioBlob);
        stream.getTracks().forEach(track => track.stop());
      };

      recorder.start();
      setIsRecording(true);
    } catch (e) {
      console.error("Mic access failed", e);
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
    }
  };

  const handleTranscription = async (blob: Blob) => {
    setIsTranscribing(true);
    try {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = (reader.result as string).split(',')[1];
        const text = await geminiService.transcribeAudio(base64);
        setText(prev => (prev ? prev + ' ' : '') + text);
      };
      reader.readAsDataURL(blob);
    } catch (e) {
      console.error(e);
    } finally {
      setIsTranscribing(false);
    }
  };

  const getPlaceholder = () => {
    if (isRecording) return "Listening...";
    if (isTranscribing) return "Transcribing...";

    if (selectedModel.id.includes('veo')) return "Describe a video to create...";
    if (selectedModel.id.includes('image')) return "Describe an image to generate...";
    if (selectedModel.supportsThinking) return `Ask a complex question (${selectedModel.name})...`;

    return `Ask Neby (${selectedModel.name})...`;
  };

  return (
    <div className="w-full max-w-4xl mx-auto p-4">
      {/* Attachments Preview */}
      {(images.length > 0 || video) && (
        <div className="flex gap-3 mb-3 overflow-x-auto pb-2 custom-scrollbar">
          {images.map((img, idx) => (
            <div key={idx} className="relative group flex-shrink-0">
              <img src={img} alt="Preview" className="w-20 h-20 object-cover rounded-lg border border-white/20" />
              <button onClick={() => setImages(prev => prev.filter((_, i) => i !== idx))} className="absolute -top-2 -right-2 bg-black/80 text-zinc-400 hover:text-red-400 rounded-full p-1 border border-white/10">
                <X size={12} />
              </button>
            </div>
          ))}
          {video && (
             <div className="relative group flex-shrink-0 w-20 h-20 bg-black/50 rounded-lg border border-white/20 flex items-center justify-center">
                <Video size={24} className="text-zinc-400" />
                <button onClick={() => setVideo(null)} className="absolute -top-2 -right-2 bg-black/80 text-zinc-400 hover:text-red-400 rounded-full p-1 border border-white/10">
                <X size={12} />
              </button>
             </div>
          )}
        </div>
      )}

      {/* Input Bar */}
      <div className={`relative bg-black/40 border rounded-2xl shadow-2xl backdrop-blur-xl transition-all duration-300 ${isRecording ? 'border-red-500/50 shadow-red-900/20' : 'border-white/10 focus-within:ring-2 focus-within:ring-indigo-500/40'}`}>

        {/* Container with items-end for bottom alignment of buttons */}
        <div className="flex items-end gap-2 p-2">

          {/* Left Actions */}
          <div className="flex items-center gap-1">
            {/* Attach Button (Images & Video) */}
            <button onClick={() => fileInputRef.current?.click()} className="p-2.5 text-zinc-400 hover:text-indigo-300 hover:bg-white/5 rounded-xl transition-all" title="Attach File">
              <Paperclip size={20} />
            </button>
            <input type="file" ref={fileInputRef} className="hidden" accept="image/*,video/*" onChange={handleFileSelect} />

            {/* Microphone (Transcription) */}
            <button 
              onClick={isRecording ? stopRecording : startRecording}
              className={`p-2.5 rounded-xl transition-all ${isRecording ? 'text-red-500 bg-red-500/10 animate-pulse' : 'text-zinc-400 hover:text-white hover:bg-white/5'}`}
              title="Transcribe Audio"
            >
              {isRecording ? <MicOff size={20} /> : <Mic size={20} />}
            </button>
          </div>

          {/* Text Input */}
          <div className="flex-1 relative">
            <textarea
              ref={textareaRef}
              value={text}
              onChange={(e) => setText(e.target.value)}
              onKeyDown={handleKeyDown}
              placeholder={getPlaceholder()}
              className="w-full bg-transparent text-zinc-100 placeholder-zinc-500 py-3 px-2 max-h-40 resize-none focus:outline-none custom-scrollbar leading-relaxed"
              rows={1}
              disabled={isLoading || isTranscribing}
            />
          </div>

          {/* Right Actions */}
          <div className="flex items-center gap-1">
            {/* Live Button */}
            <button
               onClick={onLiveStart}
               className="p-2.5 rounded-xl bg-gradient-to-tr from-blue-500/10 to-cyan-500/10 text-cyan-400 hover:bg-cyan-500/20 transition-all border border-cyan-500/20"
               title="Start Live Voice Session"
            >
               <Sparkles size={18} />
            </button>

            {/* Veo Button */}
            <button
              onClick={() => handleSend('video')}
              disabled={(!text && !images.length && !video) || isLoading}
              className="p-2.5 rounded-xl bg-purple-600/20 text-purple-400 hover:bg-purple-600 hover:text-white transition-all"
              title="Generate Video"
            >
              <Wand2 size={18} />
            </button>

            {/* Send Button */}
            <button
              onClick={() => handleSend('text')}
              disabled={(!text.trim() && !images.length && !video) || isLoading}
              className={`p-2.5 rounded-xl transition-all ${
                (!text.trim() && !images.length && !video) || isLoading
                  ? 'bg-white/5 text-zinc-600 cursor-not-allowed'
                  : 'bg-indigo-600 text-white hover:bg-indigo-500 shadow-lg'
              }`}
            >
              {isLoading ? <Loader2 size={18} className="animate-spin" /> : <Send size={18} />}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

