import React, { useState } from 'react';
import { Mail, Lock, User as UserIcon, ArrowRight, Sparkles, AlertCircle, Loader2, X, Eye, EyeOff } from 'lucide-react';
import { User } from '../types';
import { firebaseService } from '../services/firebase';

interface AuthScreenProps {
  onLogin: (user: User) => void;
  onGuest: () => void;
  onClose?: () => void;
}

export default function AuthScreen({ onLogin, onGuest, onClose }: AuthScreenProps) {
  const [isLogin, setIsLogin] = useState(true);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [showPassword, setShowPassword] = useState(false);

  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: ''
  });

  const GoogleLogo = () => (
    <svg className="w-5 h-5" viewBox="0 0 24 24">
      <path
        d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"
        fill="#4285F4"
      />
      <path
        d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"
        fill="#34A853"
      />
      <path
        d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"
        fill="#FBBC05"
      />
      <path
        d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"
        fill="#EA4335"
      />
    </svg>
  );

  const mapFirebaseUser = (fbUser: any): User => ({
    id: fbUser.uid,
    name: fbUser.displayName || 'Guest',
    email: fbUser.email || '',
    avatar: fbUser.photoURL || `https://api.dicebear.com/7.x/avataaars/svg?seed=${fbUser.uid}`
  });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setLoading(true);

    try {
      if (isLogin) {
        const fbUser = await firebaseService.loginEmail(formData.email, formData.password);
        onLogin(mapFirebaseUser(fbUser));
      } else {
        if (!formData.name) throw new Error("Name is required");
        const fbUser = await firebaseService.registerEmail(formData.email, formData.password, formData.name);
        onLogin(mapFirebaseUser(fbUser));
      }
    } catch (err: any) {
      console.error(err);
      if (err.message.includes("not configured")) {
        setError("Missing Firebase Config! Please check README.");
      } else if (err.code === 'auth/invalid-credential') {
        setError("Invalid email or password.");
      } else if (err.code === 'auth/email-already-in-use') {
        setError("Email already in use.");
      } else {
        setError(err.message || "Authentication failed.");
      }
    } finally {
      setLoading(false);
    }
  };

  const handleGoogleLogin = async () => {
    setLoading(true);
    setError(null);
    try {
      const fbUser = await firebaseService.loginGoogle();
      onLogin(mapFirebaseUser(fbUser));
    } catch (err: any) {
      console.error(err);
      if (err.message.includes("not configured")) {
        setError("Missing Firebase Config! Please check README.");
      } else {
        setError("Google Sign-in failed. Popup closed or not authorized.");
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-black/40 backdrop-blur-xl border border-white/10 rounded-3xl p-8 shadow-2xl overflow-hidden relative w-full">
      {onClose && (
        <button onClick={onClose} className="absolute top-4 right-4 text-zinc-500 hover:text-white transition-colors p-2 rounded-full hover:bg-white/10">
          <X size={20} />
        </button>
      )}

      <div className="flex flex-col items-center mb-8">
        <div className="w-16 h-16 bg-gradient-to-br from-indigo-600 via-indigo-700 to-purple-800 rounded-2xl flex items-center justify-center shadow-lg border border-white/20 mb-4 transform rotate-3">
          <Sparkles size={32} className="text-white fill-white/10" />
        </div>
        <h1 className="text-2xl font-bold text-white mb-1">
          {isLogin ? 'Welcome Back' : 'Join Neby'}
        </h1>
        <p className="text-zinc-400 text-sm">Sign in to save your history</p>
      </div>

      <form onSubmit={handleSubmit} className="space-y-4">
        {!isLogin && (
          <div className="space-y-1">
            <label className="text-xs font-bold text-zinc-500 uppercase tracking-wider ml-1">Name</label>
            <div className="relative">
              <UserIcon size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-500" />
              <input
                type="text"
                value={formData.name}
                onChange={e => setFormData({...formData, name: e.target.value})}
                placeholder="Enter your name"
                className="w-full bg-black/20 border border-white/10 rounded-xl py-3 pl-10 pr-4 text-sm text-white placeholder-zinc-600 focus:outline-none focus:border-indigo-500/50 focus:ring-1 focus:ring-indigo-500/50 transition-all"
              />
            </div>
          </div>
        )}

        <div className="space-y-1">
          <label className="text-xs font-bold text-zinc-500 uppercase tracking-wider ml-1">Email</label>
          <div className="relative">
            <Mail size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-500" />
            <input
              type="email"
              value={formData.email}
              onChange={e => setFormData({...formData, email: e.target.value})}
              placeholder="name@example.com"
              className="w-full bg-black/20 border border-white/10 rounded-xl py-3 pl-10 pr-4 text-sm text-white placeholder-zinc-600 focus:outline-none focus:border-indigo-500/50 focus:ring-1 focus:ring-indigo-500/50 transition-all"
            />
          </div>
        </div>

        <div className="space-y-1">
          <label className="text-xs font-bold text-zinc-500 uppercase tracking-wider ml-1">Password</label>
          <div className="relative">
            <Lock size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-500" />
            <input
              type={showPassword ? "text" : "password"}
              value={formData.password}
              onChange={e => setFormData({...formData, password: e.target.value})}
              placeholder="••••••••"
              className="w-full bg-black/20 border border-white/10 rounded-xl py-3 pl-10 pr-12 text-sm text-white placeholder-zinc-600 focus:outline-none focus:border-indigo-500/50 focus:ring-1 focus:ring-indigo-500/50 transition-all"
            />
            <button
              type="button"
              onClick={() => setShowPassword(!showPassword)}
              className="absolute right-3 top-1/2 -translate-y-1/2 text-zinc-500 hover:text-zinc-300 focus:outline-none p-1"
            >
              {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
            </button>
          </div>
        </div>

        {error && (
          <div className="flex items-center gap-2 text-red-400 text-xs bg-red-500/10 p-3 rounded-lg border border-red-500/20">
            <AlertCircle size={14} />
            {error}
          </div>
        )}

        <button
          type="submit"
          disabled={loading}
          className="w-full bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-500 hover:to-purple-500 text-white font-semibold py-3.5 rounded-xl shadow-lg shadow-indigo-500/20 transition-all flex items-center justify-center gap-2 group mt-2"
        >
          {loading ? (
            <Loader2 size={18} className="animate-spin" />
          ) : (
            <>
              {isLogin ? 'Sign In' : 'Create Account'}
              <ArrowRight size={18} className="group-hover:translate-x-1 transition-transform" />
            </>
          )}
        </button>
      </form>

      <div className="relative my-6">
        <div className="absolute inset-0 flex items-center"><div className="w-full border-t border-white/10"></div></div>
        <div className="relative flex justify-center text-xs uppercase"><span className="bg-[#0f1016] px-2 text-zinc-500">Or continue with</span></div>
      </div>

      <div className="space-y-3">
        <button 
          type="button"
          onClick={handleGoogleLogin}
          disabled={loading}
          className="w-full bg-white text-zinc-900 font-medium py-3 rounded-xl hover:bg-zinc-100 transition-colors flex items-center justify-center gap-2 shadow-lg"
        >
          <GoogleLogo />
          <span>Google Account</span>
        </button>
      </div>

      <div className="mt-8 text-center text-sm text-zinc-400">
        {isLogin ? "Don't have an account?" : "Already have an account?"}{" "}
        <button 
          onClick={() => { setIsLogin(!isLogin); setError(null); }}
          className="text-indigo-400 hover:text-indigo-300 font-medium hover:underline transition-all"
        >
          {isLogin ? "Sign up" : "Log in"}
        </button>
      </div>
    </div>
  );
}

import React, { useState, useRef, useEffect } from 'react';
import { Send, X, Loader2, Mic, MicOff, Sparkles, Video, Paperclip, RotateCcw, RotateCw } from 'lucide-react';
import { geminiService } from '../services/geminiService';
import { ModelOption } from '../types';

interface ChatInputProps {
  onSendMessage: (text: string, images: string[], type: 'text' | 'image' | 'video', videoData?: string) => void;
  isLoading: boolean;
  onLiveStart: () => void;
  selectedModel: ModelOption;
}

const ChatInput: React.FC<ChatInputProps> = ({ onSendMessage, isLoading, onLiveStart, selectedModel }) => {
  const [text, setText] = useState('');
  const [images, setImages] = useState<string[]>([]);
  const [video, setVideo] = useState<string | null>(null);

  // Undo/Redo State
  const [history, setHistory] = useState<string[]>(['']);
  const [historyIndex, setHistoryIndex] = useState(0);
  const typingTimeoutRef = useRef<NodeJS.Timeout | null>(null);

  const [isRecording, setIsRecording] = useState(false);
  const [isTranscribing, setIsTranscribing] = useState(false);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = Math.min(textareaRef.current.scrollHeight, 160) + 'px';
    }
  }, [text]);

  const addToHistory = (newText: string) => {
    const newHistory = history.slice(0, historyIndex + 1);
    newHistory.push(newText);
    setHistory(newHistory);
    setHistoryIndex(newHistory.length - 1);
  };

  const handleTextChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const val = e.target.value;
    setText(val);

    if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);

    typingTimeoutRef.current = setTimeout(() => {
      if (val !== history[historyIndex]) {
        addToHistory(val);
      }
    }, 500);
  };

  const handleUndo = () => {
    if (historyIndex > 0) {
      const newIndex = historyIndex - 1;
      setHistoryIndex(newIndex);
      setText(history[newIndex]);
    }
  };

  const handleRedo = () => {
    if (historyIndex < history.length - 1) {
      const newIndex = historyIndex + 1;
      setHistoryIndex(newIndex);
      setText(history[newIndex]);
    }
  };

  const handleSend = (type: 'text' | 'image' | 'video' = 'text') => {
    if ((!text.trim() && images.length === 0 && !video) || isLoading) return;

    onSendMessage(text.trim(), images, type, video || undefined);

    // Clear state
    setText('');
    setImages([]);
    setVideo(null);

    // Commit the clear to history so user can undo to get the message back
    addToHistory('');

    if (textareaRef.current) textareaRef.current.style.height = 'auto';
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend('text');
    }
    // Optional: Ctrl+Z / Ctrl+Y support if native doesn't work well with React state
    if ((e.ctrlKey || e.metaKey) && e.key === 'z') {
      e.preventDefault();
      if (e.shiftKey) handleRedo();
      else handleUndo();
    }
    if ((e.ctrlKey || e.metaKey) && e.key === 'y') {
      e.preventDefault();
      handleRedo();
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];

      if (file.type.startsWith('image/')) {
        const reader = new FileReader();
        reader.onloadend = () => {
          if (typeof reader.result === 'string') {
            setImages(prev => [...prev, reader.result as string]);
          }
        };
        reader.readAsDataURL(file);
      } else if (file.type.startsWith('video/')) {
        if (file.size > 20 * 1024 * 1024) {
          alert("Video too large (Max 20MB for direct upload)");
          return;
        }
        const reader = new FileReader();
        reader.onloadend = () => {
          if (typeof reader.result === 'string') {
            setVideo(reader.result);
          }
        };
        reader.readAsDataURL(file);
      }
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  // Transcription Recording
  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const recorder = new MediaRecorder(stream);
      mediaRecorderRef.current = recorder;
      audioChunksRef.current = [];

      recorder.ondataavailable = (e) => {
        if (e.data.size > 0) audioChunksRef.current.push(e.data);
      };

      recorder.onstop = async () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/wav' });
        await handleTranscription(audioBlob);
        stream.getTracks().forEach(track => track.stop());
      };

      recorder.start();
      setIsRecording(true);
    } catch (e) {
      console.error("Mic access failed", e);
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
    }
  };

  const handleTranscription = async (blob: Blob) => {
    setIsTranscribing(true);
    try {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = (reader.result as string).split(',')[1];
        const text = await geminiService.transcribeAudio(base64);

        // Append transcribed text and update history
        const newText = (text ? text + ' ' : '') + text;
        setText(prev => {
            const val = (prev ? prev + ' ' : '') + text;
            addToHistory(val); // Commit transcription to history
            return val;
        });
      };
      reader.readAsDataURL(blob);
    } catch (e) {
      console.error(e);
    } finally {
      setIsTranscribing(false);
    }
  };

  const getPlaceholder = () => {
    if (isRecording) return "Listening...";
    if (isTranscribing) return "Transcribing...";

    if (selectedModel.id.includes('veo')) return "Describe a video to create...";
    if (selectedModel.id.includes('image')) return "Describe an image to generate...";
    if (selectedModel.supportsThinking) return `Ask a complex question (${selectedModel.name})...`;

    return `Ask Neby (${selectedModel.name})...`;
  };

  return (
    <div className="w-full max-w-4xl mx-auto p-4">
      {/* Attachments Preview */}
      {(images.length > 0 || video) && (
        <div className="flex gap-3 mb-3 overflow-x-auto pb-2 custom-scrollbar">
          {images.map((img, idx) => (
            <div key={idx} className="relative group flex-shrink-0">
              <img src={img} alt="Preview" className="w-20 h-20 object-cover rounded-lg border border-white/20" />
              <button onClick={() => setImages(prev => prev.filter((_, i) => i !== idx))} className="absolute -top-2 -right-2 bg-black/80 text-zinc-400 hover:text-red-400 rounded-full p-1 border border-white/10">
                <X size={12} />
              </button>
            </div>
          ))}
          {video && (
             <div className="relative group flex-shrink-0 w-20 h-20 bg-black/50 rounded-lg border border-white/20 flex items-center justify-center">
                <Video size={24} className="text-zinc-400" />
                <button onClick={() => setVideo(null)} className="absolute -top-2 -right-2 bg-black/80 text-zinc-400 hover:text-red-400 rounded-full p-1 border border-white/10">
                <X size={12} />
              </button>
             </div>
          )}
        </div>
      )}

      {/* Input Bar */}
      <div className={`relative bg-black/40 border rounded-2xl shadow-2xl backdrop-blur-xl transition-all duration-300 ${isRecording ? 'border-red-500/50 shadow-red-900/20' : 'border-white/10 focus-within:ring-2 focus-within:ring-indigo-500/40'}`}>

        {/* Container with items-end for bottom alignment of buttons */}
        <div className="flex items-end gap-2 p-2">

          {/* Left Actions */}
          <div className="flex items-center gap-0.5">
            {/* Undo */}
            <button 
                onClick={handleUndo} 
                disabled={historyIndex <= 0}
                className={`p-2 rounded-xl transition-all ${historyIndex > 0 ? 'text-zinc-400 hover:text-white hover:bg-white/5' : 'text-zinc-700 cursor-not-allowed'}`}
                title="Undo (Ctrl+Z)"
            >
              <RotateCcw size={18} />
            </button>

            {/* Redo */}
            <button 
                onClick={handleRedo} 
                disabled={historyIndex >= history.length - 1}
                className={`p-2 rounded-xl transition-all ${historyIndex < history.length - 1 ? 'text-zinc-400 hover:text-white hover:bg-white/5' : 'text-zinc-700 cursor-not-allowed'}`}
                title="Redo (Ctrl+Y)"
            >
              <RotateCw size={18} />
            </button>

            <div className="w-px h-5 bg-white/10 mx-1" />

            {/* Attach Button (Images & Video) */}
            <button onClick={() => fileInputRef.current?.click()} className="p-2 text-zinc-400 hover:text-indigo-300 hover:bg-white/5 rounded-xl transition-all" title="Attach File">
              <Paperclip size={18} />
            </button>
            <input type="file" ref={fileInputRef} className="hidden" accept="image/*,video/*" onChange={handleFileSelect} />

            {/* Microphone (Transcription) */}
            <button 
              onClick={isRecording ? stopRecording : startRecording}
              className={`p-2 rounded-xl transition-all ${isRecording ? 'text-red-500 bg-red-500/10 animate-pulse' : 'text-zinc-400 hover:text-white hover:bg-white/5'}`}
              title="Transcribe Audio"
            >
              {isRecording ? <MicOff size={18} /> : <Mic size={18} />}
            </button>
          </div>

          {/* Text Input */}
          <div className="flex-1 relative">
            <textarea
              ref={textareaRef}
              value={text}
              onChange={handleTextChange}
              onKeyDown={handleKeyDown}
              placeholder={getPlaceholder()}
              className="w-full bg-transparent text-zinc-100 placeholder-zinc-500 py-3 px-2 max-h-40 resize-none focus:outline-none custom-scrollbar leading-relaxed"
              rows={1}
              disabled={isLoading || isTranscribing}
            />
          </div>

          {/* Right Actions */}
          <div className="flex items-center gap-1">
            {/* Live Button */}
            <button
               onClick={onLiveStart}
               className="p-2.5 rounded-xl bg-gradient-to-tr from-blue-500/10 to-cyan-500/10 text-cyan-400 hover:bg-cyan-500/20 transition-all border border-cyan-500/20"
               title="Start Live Voice Session"
            >
               <Sparkles size={18} />
            </button>

            {/* Send Button */}
            <button
              onClick={() => handleSend('text')}
              disabled={(!text.trim() && !images.length && !video) || isLoading}
              className={`p-2.5 rounded-xl transition-all ${
                (!text.trim() && !images.length && !video) || isLoading
                  ? 'bg-white/5 text-zinc-600 cursor-not-allowed'
                  : 'bg-indigo-600 text-white hover:bg-indigo-500 shadow-lg'
              }`}
            >
              {isLoading ? <Loader2 size={18} className="animate-spin" /> : <Send size={18} />}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

