          ) : (
            <div className="max-w-4xl mx-auto pt-4 md:pt-10">
              {messages.map(m => (
                <ChatMessage 
                  key={m.id} 
                  message={m} 
                  onUpdateMessage={handleUpdateMessage}
                  onEditSave={handleEditMessage}
                />
              ))}
              <div ref={messagesEndRef} />
