              <div className="text-center mt-2">
                  <p className="text-[10px] text-zinc-600 font-medium">
                      Powered by Google Gemini 3 • AI can make mistakes.
                  </p>
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

