export class RateLimiter {
  private tokens: number;
  private maxTokens: number;
  private refillRate: number; // tokens per second
  private lastRefill: number;

  constructor(maxTokens: number = 10, refillRate: number = 0.2) { // Default: 10 burst, 1 refill every 5s
    this.tokens = maxTokens;
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.lastRefill = Date.now();
  }

  checkLimit(): boolean {
    const now = Date.now();
    const timePassed = (now - this.lastRefill) / 1000;
    this.tokens = Math.min(this.maxTokens, this.tokens + timePassed * this.refillRate);
    this.lastRefill = now;

    if (this.tokens >= 1) {
      this.tokens -= 1;
      return true;
    }
    return false;
  }

  getTimeToNextToken(): number {
     if (this.tokens >= 1) return 0;
     return Math.ceil((1 - this.tokens) / this.refillRate);
  }
}

// Security Constants
export const SECURITY_LIMITS = {
    MAX_MESSAGE_LENGTH: 30000,
    MAX_SYSTEM_INSTRUCTION_LENGTH: 5000,
    MAX_IMAGES: 4,
    MAX_IMAGE_SIZE_MB: 5,
};

export function validateInput(text: string, images: string[] = []): string | null {
    if (!text.trim() && images.length === 0) return "Message cannot be empty.";

    // Text Length Check
    if (text.length > SECURITY_LIMITS.MAX_MESSAGE_LENGTH) {
        return `Message too long. Max ${SECURITY_LIMITS.MAX_MESSAGE_LENGTH.toLocaleString()} characters.`;
    }

    // Image Count Check
    if (images.length > SECURITY_LIMITS.MAX_IMAGES) {
        return `Too many images. Max ${SECURITY_LIMITS.MAX_IMAGES}.`;
    }

    // Image Validation
    for (const img of images) {
        if (!img.startsWith('data:image/')) return "Invalid image format detected.";

        // Base64 Size Estimation: (length * 3/4) - padding
        const sizeInBytes = (img.length * 3) / 4 - (img.indexOf('=') > 0 ? (img.length - img.indexOf('=')) : 0);
        if (sizeInBytes > SECURITY_LIMITS.MAX_IMAGE_SIZE_MB * 1024 * 1024) {
            return `Image too large. Max ${SECURITY_LIMITS.MAX_IMAGE_SIZE_MB}MB allowed.`;
        }
    }

    return null; // Valid
}

export function sanitizeInput(text: string): string {
    // Remove null bytes and control characters (except newlines/tabs)
    // This helps prevent basic injection attacks or processing errors
    return text.replace(/[\x00-\x08\x0B-\x1F\x7F]/g, "").trim(); 
}

// Helper to remove API Keys from error objects before logging
export function sanitizeError(error: any): Error {
    const str = JSON.stringify(error, Object.getOwnPropertyNames(error));
    // Simple regex to mask potential key patterns if they appear in error messages
    const sanitized = str.replace(/AIza[0-9A-Za-z-_]{35}/g, '***API_KEY_HIDDEN***');
    return new Error(JSON.parse(sanitized).message || "An unexpected error occurred");
}

import { GoogleGenAI, Part, Modality } from "@google/genai";
import { ChatConfig, Message, Role } from '../types';
import { RateLimiter, validateInput, sanitizeInput, sanitizeError } from '../utils/security';

// Initialize Rate Limiter: 15 requests burst, refill 1 every 3 seconds
const globalRateLimiter = new RateLimiter(15, 0.33);

export class GeminiService {
  public ai: GoogleGenAI;

  constructor() {
    // API Key must come strictly from env
    const apiKey = process.env.API_KEY || '';
    if (!apiKey) {
      console.warn("Security Warning: API_KEY is missing from environment.");
    }
    this.ai = new GoogleGenAI({ apiKey });
  }

  private checkRateLimit() {
    if (!globalRateLimiter.checkLimit()) {
      const waitTime = globalRateLimiter.getTimeToNextToken();
      throw new Error(`Rate limit exceeded. Please wait ${waitTime}s.`);
    }
  }

  /**
   * Generates a short title for the chat session.
   */
  async generateTitle(message: string): Promise<string> {
    try {
      this.checkRateLimit();
      const cleanMessage = sanitizeInput(message).slice(0, 1000); // Strict limit for title generation

      // Re-instantiate to ensure fresh key usage if env changes
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [{ text: `Generate a short, concise title (max 5 words) for a chat starting with this message: "${cleanMessage}". Return ONLY the title text. Do not use quotes.` }]
        }
      });
      return response.text?.trim() || cleanMessage.slice(0, 30);
    } catch (error) {
      console.error("Title Generation Error:", sanitizeError(error));
      return message.slice(0, 30);
    }
  }

  /**
   * Transcribes audio using Gemini 3 Flash.
   */
  async transcribeAudio(audioBase64: string): Promise<string> {
    try {
      this.checkRateLimit();
      if (!audioBase64) throw new Error("Empty audio data.");

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'audio/wav', data: audioBase64 } },
            { text: "Transcribe this audio exactly as spoken." }
          ]
        }
      });
      return response.text || "";
    } catch (error) {
      console.error("Transcription Error:", sanitizeError(error));
      throw sanitizeError(error);
    }
  }

  /**
   * Generates audio from text using the specialized TTS model.
   */
  async generateSpeech(text: string): Promise<string> {
    try {
      this.checkRateLimit();
      const cleanText = sanitizeInput(text);
      if (!cleanText) throw new Error("Text is required for speech generation.");

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: `Read this message naturally: ${cleanText}` }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: 'Kore' },
            },
          },
        },
      });

      const audioBase64 = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (!audioBase64) {
        throw new Error("No audio data returned from Gemini TTS");
      }
      return audioBase64;
    } catch (error) {
      console.error("Gemini TTS Error:", sanitizeError(error));
      throw sanitizeError(error);
    }
  }

  /**
   * Generates or Edits images.
   */
  async generateImage(prompt: string, config: ChatConfig, inputImages?: string[]): Promise<string[]> {
    try {
      this.checkRateLimit();
      const cleanPrompt = sanitizeInput(prompt);

      const validationError = validateInput(cleanPrompt, inputImages);
      if (validationError) throw new Error(validationError);

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
      const model = config.model; 

      const parts: Part[] = [];

      if (inputImages && inputImages.length > 0) {
        for (const img of inputImages) {
          parts.push({
            inlineData: {
              mimeType: 'image/jpeg',
              data: img.split(',')[1]
            }
          });
        }
      }
      parts.push({ text: cleanPrompt });

      let imageConfig: any = {
        aspectRatio: config.aspectRatio || "1:1"
      };

      const response = await ai.models.generateContent({
        model: model,
        contents: { parts },
        config: {
          imageConfig: model.includes('pro-image') ? { ...imageConfig, imageSize: config.imageSize } : imageConfig
        }
      });

      const images: string[] = [];
      const resParts = response.candidates?.[0]?.content?.parts || [];

      for (const part of resParts) {
        if (part.inlineData) {
          images.push(`data:${part.inlineData.mimeType};base64,${part.inlineData.data}`);
        }
      }

      if (images.length === 0) {
        throw new Error("No image data returned from model.");
      }

      return images;
    } catch (error) {
      console.error("Gemini Image Generation Error:", sanitizeError(error));
      throw sanitizeError(error);
    }
  }

  /**
   * Generates Video or Animates Image.
   */
  async generateVideo(prompt: string, config: ChatConfig, inputImage?: string, onStatusUpdate?: (status: string) => void): Promise<string> {
    try {
      this.checkRateLimit();
      const cleanPrompt = sanitizeInput(prompt);
      const validationError = validateInput(cleanPrompt, inputImage ? [inputImage] : []);
      if (validationError) throw new Error(validationError);

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

      const requestConfig: any = {
        numberOfVideos: 1,
        resolution: '1080p',
        aspectRatio: ['16:9', '9:16'].includes(config.aspectRatio || '') ? config.aspectRatio : '16:9'
      };

      let operation;
      if (inputImage) {
        operation = await ai.models.generateVideos({
          model: 'veo-3.1-fast-generate-preview',
          prompt: cleanPrompt || "Animate this image",
          image: {
            imageBytes: inputImage.split(',')[1],
            mimeType: 'image/jpeg',
          },
          config: requestConfig
        });
      } else {
        operation = await ai.models.generateVideos({
          model: 'veo-3.1-fast-generate-preview',
          prompt: cleanPrompt,
          config: requestConfig
        });
      }

      while (!operation.done) {
        if (onStatusUpdate) onStatusUpdate("Synthesizing video frames...");
        await new Promise(resolve => setTimeout(resolve, 5000));
        operation = await ai.operations.getVideosOperation({ operation: operation });
      }

      const videoUri = operation.response?.generatedVideos?.[0]?.video?.uri;
      if (!videoUri) {
        throw new Error("No video URI returned from Gemini Veo");
      }

      // Note: In a production app with a backend, you would proxy this download.
      // Since this is client-only, we must append the key to fetch the content.
      return `${videoUri}&key=${process.env.API_KEY}`;
    } catch (error) {
      console.error("Gemini Video Generation Error:", sanitizeError(error));
      throw sanitizeError(error);
    }
  }

  async *streamChat(
    history: Message[], 
    newMessage: string, 
    images: string[], 
    config: ChatConfig,
    videoData?: string
  ): AsyncGenerator<string | { groundingChunks: any[] }, void, unknown> {

    try {
        this.checkRateLimit();
        const cleanMessage = sanitizeInput(newMessage);
        const validationError = validateInput(cleanMessage, images);

        // Yield error immediately if validation fails
        if (validationError) {
             yield `⚠️ **Validation Error**: ${validationError}`;
             return;
        }

        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

        const chatHistory = history
          .filter(msg => !msg.isLoading && msg.role !== Role.SYSTEM) 
          .map(msg => ({
            role: msg.role === Role.USER ? 'user' : 'model',
            parts: msg.images && msg.images.length > 0 
              ? [
                  ...msg.images.map(img => ({ inlineData: { mimeType: 'image/jpeg', data: img.split(',')[1] } })),
                  { text: sanitizeInput(msg.content) }
                ]
              : [{ text: sanitizeInput(msg.content) }]
          }));

        const currentParts: Part[] = [];

        if (images.length > 0) {
          images.forEach(img => {
            currentParts.push({
              inlineData: {
                mimeType: 'image/jpeg',
                data: img.split(',')[1]
              }
            });
          });
        }

        if (videoData) {
          currentParts.push({
            inlineData: {
              mimeType: 'video/mp4',
              data: videoData.split(',')[1]
            }
          });
        }

        currentParts.push({ text: cleanMessage });

        const tools: any[] = [];
        if (config.useSearch && config.model.includes('gemini-3')) {
          tools.push({ googleSearch: {} });
        }
        if (config.useMaps && config.model.includes('gemini-2.5-flash')) {
          tools.push({ googleMaps: {} });
        }

        const thinkingConfig = (config.useThinking && config.model.includes('gemini-3'))
          ? { thinkingBudget: config.model.includes('pro') ? 32000 : 16000 } 
          : undefined;

        const isSingleTurnOnly = config.model.includes('tts') || config.model.includes('image');

        const contents = isSingleTurnOnly 
          ? [{ role: 'user', parts: currentParts }]
          : [
              ...chatHistory,
              { role: 'user', parts: currentParts }
            ];

      const result = await ai.models.generateContentStream({
        model: config.model,
        contents: contents,
        config: {
          systemInstruction: sanitizeInput(config.systemInstruction),
          temperature: config.useThinking ? undefined : config.temperature,
          tools: tools.length > 0 ? tools : undefined,
          thinkingConfig: thinkingConfig,
        }
      });

      for await (const chunk of result) {
        const text = chunk.text;
        if (text) yield text;

        const groundingChunks = chunk.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (groundingChunks) yield { groundingChunks };

        const candidate = chunk.candidates?.[0];
        if (candidate?.finishReason === 'SAFETY') {
          yield "\n\n⚠️ *The response was filtered by safety settings.*";
        }
      }
    } catch (error: any) {
      console.error("Gemini API Error Detail:", sanitizeError(error));

      const errorMessage = error.message || error.error?.message || JSON.stringify(error);
      const statusCode = error.status || (error.response?.status) || error.code;

      if (errorMessage.includes("Rate limit exceeded")) {
         yield "🛑 **Rate Limit**: " + errorMessage;
         return;
      }

      if (errorMessage.includes("Requested entity was not found") || statusCode === 404) {
        throw sanitizeError(error);
      }
      if (statusCode === 429) {
        yield "🚀 **Server Rate Limit Reached**: Please wait a moment.";
        return;
      }
      yield "☄️ **Error**: " + (errorMessage.slice(0, 100) + "...");
    }
  }
}

export const geminiService = new GeminiService();

import React, { useState, useRef, useEffect } from 'react';
import { Send, X, Loader2, Mic, MicOff, Sparkles, Video, Paperclip, StopCircle, AlertTriangle } from 'lucide-react';
import { geminiService } from '../services/geminiService';
import { ModelOption } from '../types';
import { validateInput, SECURITY_LIMITS } from '../utils/security';

interface ChatInputProps {
  onSendMessage: (text: string, images: string[], type: 'text' | 'image' | 'video', videoData?: string) => void;
  isLoading: boolean;
  onLiveStart: () => void;
  selectedModel: ModelOption;
}

const ChatInput: React.FC<ChatInputProps> = ({ onSendMessage, isLoading, onLiveStart, selectedModel }) => {
  const [text, setText] = useState('');
  const [images, setImages] = useState<string[]>([]);
  const [video, setVideo] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const [isRecording, setIsRecording] = useState(false);
  const [isTranscribing, setIsTranscribing] = useState(false);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = Math.min(textareaRef.current.scrollHeight, 120) + 'px';
    }
    // Clear error if input changes
    if (error) setError(null);
  }, [text, images, video]);

  const handleSend = (type: 'text' | 'image' | 'video' = 'text') => {
    // Client-side Validation Check
    const validationError = validateInput(text, images);
    if (validationError) {
        setError(validationError);
        return;
    }

    if ((!text.trim() && images.length === 0 && !video) || isLoading) return;
    onSendMessage(text.trim(), images, type, video || undefined);
    setText('');
    setImages([]);
    setVideo(null);
    setError(null);
    if (textareaRef.current) textareaRef.current.style.height = 'auto';
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend('text');
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];

      // Basic size check before read
      if (file.size > SECURITY_LIMITS.MAX_IMAGE_SIZE_MB * 1024 * 1024 * 5) { // 5x limit for videos mostly, images strictly checked in validation
         setError("File is too large.");
         return;
      }

      if (file.type.startsWith('image/')) {
        const reader = new FileReader();
        reader.onloadend = () => { if (typeof reader.result === 'string') setImages(prev => [...prev, reader.result as string]); };
        reader.readAsDataURL(file);
      } else if (file.type.startsWith('video/')) {
        if (file.size > 20 * 1024 * 1024) { setError("Video too large (Max 20MB)"); return; }
        const reader = new FileReader();
        reader.onloadend = () => { if (typeof reader.result === 'string') setVideo(reader.result); };
        reader.readAsDataURL(file);
      }
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const recorder = new MediaRecorder(stream);
      mediaRecorderRef.current = recorder;
      audioChunksRef.current = [];
      recorder.ondataavailable = (e) => { if (e.data.size > 0) audioChunksRef.current.push(e.data); };
      recorder.onstop = async () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/wav' });
        await handleTranscription(audioBlob);
        stream.getTracks().forEach(track => track.stop());
      };
      recorder.start();
      setIsRecording(true);
      setError(null);
    } catch (e) { console.error("Mic access failed", e); setError("Microphone access denied."); }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
    }
  };

  const handleTranscription = async (blob: Blob) => {
    setIsTranscribing(true);
    try {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = (reader.result as string).split(',')[1];
        const text = await geminiService.transcribeAudio(base64);
        setText(prev => (prev ? prev + ' ' : '') + text);
      };
      reader.readAsDataURL(blob);
    } catch (e) { console.error(e); setError("Transcription failed."); } finally { setIsTranscribing(false); }
  };

  const getPlaceholder = () => {
    if (isRecording) return "Listening...";
    if (isTranscribing) return "Transcribing...";
    if (selectedModel.id.includes('veo')) return "Describe a video to generate...";
    if (selectedModel.id.includes('image')) return "Describe an image to generate...";
    return `Ask anything...`;
  };

  return (
    <div className="w-full max-w-4xl mx-auto p-4 z-20">

      {/* Validation Error Toast */}
      {error && (
        <div className="mb-3 p-2.5 bg-red-500/10 border border-red-500/20 rounded-xl flex items-center gap-2 text-xs text-red-300 animate-in slide-in-from-bottom-2 fade-in">
           <AlertTriangle size={14} />
           <span>{error}</span>
           <button onClick={() => setError(null)} className="ml-auto hover:text-white"><X size={12} /></button>
        </div>
      )}

      {/* Media Previews */}
      {(images.length > 0 || video) && (
        <div className="flex gap-3 mb-3 pl-2 overflow-x-auto pb-2 custom-scrollbar animate-message-enter">
          {images.map((img, idx) => (
            <div key={idx} className="relative group shrink-0 w-20 h-20 rounded-xl overflow-hidden border border-white/20 shadow-lg">
              <img src={img} alt="Preview" className="w-full h-full object-cover" />
              <button onClick={() => setImages(prev => prev.filter((_, i) => i !== idx))} className="absolute top-1 right-1 bg-black/60 text-white p-1 rounded-full backdrop-blur-sm opacity-0 group-hover:opacity-100 transition-opacity"><X size={10} /></button>
            </div>
          ))}
          {video && (
             <div className="relative group shrink-0 w-20 h-20 rounded-xl overflow-hidden border border-white/20 shadow-lg bg-black/50 flex items-center justify-center">
                <Video size={24} className="text-zinc-300" />
                <button onClick={() => setVideo(null)} className="absolute top-1 right-1 bg-black/60 text-white p-1 rounded-full backdrop-blur-sm opacity-0 group-hover:opacity-100 transition-opacity"><X size={10} /></button>
             </div>
          )}
        </div>
      )}

      {/* Floating Input Capsule */}
      <div className={`relative bg-[#09090b]/60 backdrop-blur-2xl border transition-all duration-300 rounded-[24px] shadow-2xl ${isRecording ? 'border-red-500/50 shadow-[0_0_30px_rgba(239,68,68,0.2)]' : error ? 'border-red-500/30' : 'border-white/10 hover:border-white/20 focus-within:border-indigo-500/30 focus-within:ring-1 focus-within:ring-indigo-500/30'}`}>

        <div className="flex items-end p-2 gap-2">

          {/* Left Actions */}
          <div className="flex items-center gap-1 pb-1 pl-1">
             <button onClick={() => fileInputRef.current?.click()} className="p-2.5 text-zinc-400 hover:text-white hover:bg-white/10 rounded-full transition-colors" title="Attach Media">
               <Paperclip size={20} />
             </button>
             <input type="file" ref={fileInputRef} className="hidden" accept="image/*,video/*" onChange={handleFileSelect} />

             {/* Live Mode Toggle (Only if available) */}
             <button onClick={onLiveStart} className="hidden md:flex p-2.5 text-zinc-400 hover:text-cyan-400 hover:bg-cyan-500/10 rounded-full transition-colors" title="Start Live Session">
               <Sparkles size={20} />
             </button>
          </div>

          {/* Text Area */}
          <textarea
            ref={textareaRef}
            value={text}
            onChange={(e) => setText(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder={getPlaceholder()}
            className="flex-1 bg-transparent text-zinc-100 placeholder-zinc-500 py-3.5 px-2 max-h-32 resize-none focus:outline-none custom-scrollbar text-[15px] leading-relaxed"
            rows={1}
            disabled={isLoading || isTranscribing}
            maxLength={SECURITY_LIMITS.MAX_MESSAGE_LENGTH}
          />

          {/* Right Actions */}
          <div className="flex items-center gap-2 pb-1 pr-1">
             {/* Mic Button */}
             <button 
               onClick={isRecording ? stopRecording : startRecording}
               className={`p-2.5 rounded-full transition-all duration-300 ${isRecording ? 'bg-red-500/20 text-red-500 scale-110' : 'text-zinc-400 hover:text-white hover:bg-white/10'}`}
               title="Voice Input"
             >
               {isRecording ? <StopCircle size={22} className="animate-pulse" /> : <Mic size={20} />}
             </button>

             {/* Send Button */}
             <button
               onClick={() => handleSend('text')}
               disabled={(!text.trim() && !images.length && !video) || isLoading}
               className={`p-3 rounded-2xl transition-all duration-300 shadow-lg ${
                 (!text.trim() && !images.length && !video) || isLoading
                   ? 'bg-white/5 text-zinc-600 cursor-not-allowed'
                   : 'bg-indigo-600 text-white hover:bg-indigo-500 hover:scale-105 hover:shadow-indigo-500/30'
               }`}
             >
               {isLoading ? <Loader2 size={18} className="animate-spin" /> : <Send size={18} />}
             </button>
          </div>
        </div>
      </div>
    </div>
  );
};

